/* 平成21年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h21.committeeSessions.push(...[{"id":"h21-20090925-8","meetingId":"h21-cm09","date":"2009年9月25日","dateIso":"2009-09-25","committee":"建設委員会","time":"午前１０時０３分～午後０時１１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"武内委員","kind":"質問","question":"ちょっと気になったのは、両方とも主催は品川区ということですか。その上で、それぞれ人数が１５人、２４人となっていますけれども、これは事前申し込みじゃなくて、もう来た順にという……。","respondent":"工藤環境課長","answer":"それで、申し込みですけれども、一応先着順ということで、期限を設けて周知しています。周知の方法に関しましては、広報に出しましたり、ホームページに掲載しています。","id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました。私はあまりわからないものですから、１つばかり例としてこんなものがエコドライブの方法なんだというのがあれば、教えていただきたい。","respondent":"工藤環境課長","answer":"もう１つは、適度な車間間隔をあけまして、加速と減速を繰り返さないというのが手法の主なものです。例えば、不要な荷物は積まないとか、最短距離で運転をするようにということがエコドライブの大きなテクニックと手法とされているところです。","id":"exchange-002"},{"speaker":"阿部副委員長","kind":"質問","question":"参加してくださいという形で、これは前回なんかも、まさに一般の方がいらしているんですか。もう１つは教習会じゃなくて、実地教習会ぐらいにするとか、何か名前を混同しないようにしたほうがいいのではないかと思います。","respondent":"工藤環境課長","answer":"一般的な公募で大体半分の１０名、あと半分は、私どもがいろいろとお声をかけた団体から出ていただいたということが実績です。来年度に向けて、そういった部分でわかりやすい形の広報を工夫、検討していきたいと考えています。","id":"exchange-003"},{"speaker":"阿部副委員長","kind":"意見","question":"すぐにルーティン化してしまったり、内容の充実がおろそかになりがちなので、そこは気をつけてほしいと求めました。名称についても工夫してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"}]},{"id":"topic-02","title":"品川区ホームページによる道路台帳平面図の公開","agenda":"品川区ホームページによる道路台帳平面図の公開","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"業者が活用されるということがほとんどということなんですよね。その辺の価値というのは、どういうところに出てくるのかわからない、その辺がよくわからないとの意見を述べました。","respondent":"小野土木管理課長","answer":"年に１回ここでホームページ上にアップしているデータと、幾つかの手順については、区役所に来る回数が減るだろうと考えております。","id":"exchange-005"},{"speaker":"菊地委員","kind":"意見","question":"１年ごとに見直しをしていくということであれば、あるのかなという気がするので、そこだけもう１度との意見を述べました。","respondent":"小野土木管理課長","answer":"最初のこのシステムの開発とセットアップをするのに、平成２１年度の事業費ですけれども、２００万円ほどかかっている。年に１回メンテナンスをしていくということについては７７万円ほどかかっているということで、区民サービスになっているだろうと考えております。","id":"exchange-006"},{"speaker":"菊地委員","kind":"意見","question":"もう１つだけ、こうやって載せますよね。これは１年後の話になってしまいますけれども、使ったとかというところというのは、最終的にチェックされるのかどうかちょっと……との意見を述べました。","respondent":"小野土木管理課長","answer":"システム的には、このページを見たというログをカウントすれば、どれぐらいの方がご利用にしたかというのは記録する形になります。","id":"exchange-007"},{"speaker":"原委員","kind":"質問","question":"その辺のところをまず教えてほしい。多分宅建業法の３５条の重要事項の説明なんかにも必要だからというところからのスタートだと思うんですけれども、もしそれを教えていただければ。","respondent":"小野土木管理課長","answer":"ここのどの位置はだれの所有権、これはまた法務局の形になりますので、それは品川区で管理をしているということではございません。これはちょっと別の図面ということでご理解をいただきたいと思います。","id":"exchange-008"},{"speaker":"原委員","kind":"確認","question":"では、もう１回確認しますと、個人だろうと、業者だろうと、あくまでも参考として見るという感覚でのサービス提供ということでいいのかなと。ほかのことは全部証明書という形でのものであれば、そうしなければならないというお話だったんですけれども、そこをもう１回。","respondent":"小野土木管理課長","answer":"おっしゃるとおり、参考ということで、証明の能力はございません。それは新たに窓口でとっていただく必要があります。","id":"exchange-009"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、要望としては、なるべく現況に即した形での対応をしてほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"この施策ですが、まず、どこからか強い要望があって、予算をつけて反映したのか。要望でなければ、課でこういうふうにやろうと決めたのであるならば、改めてなぜやろうと決めたのか、改めて教えていただきたい。","respondent":"小野土木管理課長","answer":"インターネットに載せる状況が出てまいりましたので、区民の方にお役立ていただくという形で、区のほうから考えたと。流れとしては台帳の電子化をやり、それをインターネットで情報公開するという全体の行政の流れの中で取り組んだものと理解しています。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"この関係部署に来て、いろいろ話したり、相談をしたりということで今まで成り立っていたと自分は思うんです。２００万円初期投資をして、こういう施策をしていくべきなのかなという思いがあるんですけれども、もっと明確にお答えいただきたい。","respondent":"小野土木管理課長","answer":"区として公的にきちっと計測しているものを情報として、そういう活用とかをお考えになったときに、いろいろお調べになっていくんだろうな。それを踏まえて、こういう基礎的な情報というのを公開するというのは、広い意味で区民の利益になると考えています。","id":"exchange-012"},{"speaker":"市川委員","kind":"質問","question":"１つだけお聞きしたいんですけれども、調査ために業者の方が来庁されたときに、今、窓口の職員の方というのはどういう対応をされているのかということ、それから、例えば、２３区の中では、こういうホームページによる公開というのが、今どんな状況でされているのかと、そこの状況を説明を求めました。","respondent":"小野土木管理課長","answer":"窓口の対応ということですけれども、細かくご相談に乗る、ご説明するという対応をしております。２３区でどれくらいこういうものが公開されているかということを正確にはつかんでおりませんけれども、ほかもたくさん公開されていると。","id":"exchange-013"},{"speaker":"阿部副委員長","kind":"意見","question":"あるいは、もしかしたら、今後と思っているようなことはありますか。逆に言えば、これを公開すれば、大分来庁者を減らせる、あるいは居ながらに調査ができるだろうなと思われるような資料というのはありますかとの意見を述べました。","respondent":"片田建築課長","answer":"これを今検討して、行ってまいりますので、近い先にはインターネット等の情報で区民の方に開示していくような対応を考えています。","id":"exchange-014"}]},{"id":"topic-03","title":"武蔵小山駅バス運行開始","agenda":"武蔵小山駅バス運行開始","exchanges":[{"speaker":"武内委員","kind":"質問","question":"今まで品川区内は五反田からここはとまらずに世田谷区民会館と弦巻営業所に行っていたということ、それで武蔵小山ができたから、武蔵小山を経由するようになったということか尋ねました。","respondent":"松代都市計画課長","answer":"そこで乗降していただきまして、補助２６号線を相互に通行したと。こちらのほうへ回り入れまして、一番の目的の駅との交通アクセス網ということで、利用者の方がご利用いただけるように今回したものです。","id":"exchange-015"}]},{"id":"topic-04","title":"併設施設のある区営住宅耐震化工事","agenda":"併設施設のある区営住宅耐震化工事","exchanges":[{"speaker":"武内委員","kind":"質問","question":"そうすると、あと残りの５住宅というのは順次やっていくという意味合いなんですか。ちょっとその辺。","respondent":"柏原住宅担当課長","answer":"平成２２年度に１住宅予定しておりまして、平成２３年度に行う予定でございまして、平成２７年度までには全部完了させるという予定です。","id":"exchange-016"},{"speaker":"武内委員","kind":"質問","question":"教えてほしいんですけれども、その辺はどうするのかということと、その辺を説明を求めました。","respondent":"柏原住宅担当課長","answer":"これは１つの案ですけれども、いろいろな面を考えながら、こちらで用意することを検討しております。","id":"exchange-017"},{"speaker":"武内委員","kind":"質問","question":"居ながらできるほうが多いと考えていいんか尋ねました。","respondent":"柏原住宅担当課長","answer":"基本的にはそういった方向で進めたいと考えています。","id":"exchange-018"},{"speaker":"阿部副委員長","kind":"確認","question":"これは確認なんですけれども、保育園の利用も居ながらが基本と考えていらっしゃるんか尋ねました。","respondent":"柏原住宅担当課長","answer":"基本としましては居ながら工事を考えておりますけれども、まだ設計をしている段階ですので、そういった方向で考えます。現在調整をしているというところで、その辺も含めて、所管課と調整しながらです。","id":"exchange-019"},{"speaker":"阿部副委員長","kind":"質問","question":"基本は居ながらということですが、これは平成２３年度工事予定で、居ながらで済むのか、やっぱり代替施設になるのかはいつごろ決まるものなんか尋ねました。","respondent":"柏原住宅担当課長","answer":"現在設計をかなり進めているんですけれども、今年度は基本設計ということで、平成２３年の工事につきましてはやっておりますので、今年度中には大方のところは出てくるだろうと考えています。","id":"exchange-020"}]},{"id":"topic-05","title":"大崎駅西口駅前交通広場（Ｃ地区デッキ部）整備工事委託","agenda":"大崎駅西口駅前交通広場（Ｃ地区デッキ部）整備工事委託","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"ソニーのほうも事業所ビルですから、今考えておられる部分があれば、教えてちょっといただきたいんです。","respondent":"青木都市開発課長","answer":"そこを利用される従業員の方、それと南地区、これはテナントビルと住宅を予定しています。補助１６３号線を通って、かけ替えを予定しています百反歩道橋を渡って、そちらの方面へ行かれる方々がご利用されることを想定しております。","id":"exchange-021"},{"speaker":"菊地委員","kind":"質問","question":"設定が区道的な設定になっているのかどうかというのはよくわからないんですけれども、でき上がっていく負担をするものか、その辺も教えていただけますか。","respondent":"青木都市開発課長","answer":"区の施設として扱ってまいります。地元の開発事業者４社、未来永劫というわけではないんですけれども、それをもとに品川区のほうで管理していくということを想定しております。","id":"exchange-022"},{"speaker":"原委員","kind":"意見","question":"協定締結の相手ですけれども、一番初めのときに独立行政法人との間でスタートしたと思うんです。それで、今のご説明だと、総務委員会のほうのＯＫが出ているので、こちらは建設委員会としての範囲で結構なので、ちょっとお話を願いますとの意見を述べました。","respondent":"青木都市開発課長","answer":"金額を決めた中で、基本協定に基づいて、個別の案件ごとにさらに具体的なことを定めた協定を締結して履行していただいているというものです。今回可決いただいた後に協定を締結すると申し上げましたのは…","id":"exchange-023"},{"speaker":"原委員","kind":"質問・要望","question":"確認させていただきたかったところだったのと、建設委員会としてもう１回いただきたいのは、伺いたいと思います。","respondent":"青木都市開発課長、岩田防災まちづくり事業部長","answer":"これまでは平成２０年度までは、平成２４年度までに向けて、都市再生機構のほうでは組織を解消しておられます。いつまで都市再生機構に任せられるのか、非常に慎重な判断が必要になるんですけれども… ご案内のとおり、全国でこういったハードなまちづくりを各自治体がやろうと思っても、どこの自治体もそれなりの職員の手当てができないんです。あまり好ましいことではありませんので、経験…","id":"exchange-024"},{"speaker":"原委員","kind":"質問・要望","question":"これは最後に要望なんですけれども、ほかの自治体よりはかなり能力を持っている集団というか、自治体であると思っているんです。今後において結構いろいろな意味でダイナミックに変わってくる可能性があるので、それをしっかりと見きわめてやっていただきたい、最後に要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問・要望","question":"料金関係を見直していくその辺の必要性をもう少し教えてほしいと求めました。滞納者１件当たりの対応回数は、区からの指導としてそれぞれに、そういう基準みたいなものがあるのかどうかということを教えていただけますか。","respondent":"諸石交通安全担当課長、柏原住宅担当課長","answer":"何かもうちょっと、例えば、３０分であれば、無料とか、そういうサービスはできないのかというようなお話もいただいています。そういうところをこれから検討していきたいと考えておりますので、内容につきましてはこれから検討しますの… 先ほども申しましたように、どうしても指定管理者の会社の人数の関係もあって、なかなか訪問ができないというのもあったんです。それから、維持管理の面で回っていますので…","id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"自転車駐輪場のほうでもう１つお聞きしたい。住宅をお貸ししているわけですから、果たしてこの仕事を進めていく上で十分なものなのかどうかということも含めて、その辺はどうなんか尋ねました。","respondent":"諸石交通安全担当課長、柏原住宅担当課長","answer":"例えば、もっと高い料金設定になるのではないかという委員からのご質問についてお答えしますが、品川区の条例に規定されております。利用料金制度が導入になっても、料金の設定については条例に定めるというところは変わりませんので… 先ほど１つご報告が漏れてしまったんですけれども、１回当たりの折衝の時間については、数字としては最近上がってきているところです。ここだけ低過ぎるというような認識は持っていないんですけれども、徐々にではありますが…","id":"exchange-027"},{"speaker":"藤原委員","kind":"確認","question":"ちょっと確認なんですけれども、滞納者が専決事項のああいうパターンになるのかということを１つ確認と、あともう１つ確認なんですけれども。ですから、改めて確認ですが、区民住宅に入るからには、家賃を払うということは当たり前のことなのか、違うのか、改めて質問したいと思います。","respondent":"柏原住宅担当課長","answer":"昨日もご報告申し上げたように、お支払いがこれ以上は厳しいだろうという方に対して、訴えの提起をするというような流れになります。そういった方が入居する際には、その分、その建物に応じた使用料をお支払いいただくということは間違いないということで認識しているわけです。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"だけれども、この品川宅建管理センターは、みずから決めた収納率がなぜ９８％、１００％になるのが当たり前ですよね。みずから９８％でいいやと、そんなおかしいことはないんじゃないか尋ねました。","respondent":"柏原住宅担当課長、岩田防災まちづくり事業部長","answer":"何かのきっかけで１月漏れてしまうとか、本来は１００％を目標にすべきだというのはおっしゃるとおりだと思いますので、品川宅建管理センターには申していきたいと思います。 ちょっと考えなければいけないのは、別の目的でやっている行政サービスとは、当然対応は変えなければいけません。厳しく対応する必要があります。","id":"exchange-029"},{"speaker":"武内委員","kind":"質問","question":"住宅の別紙１では、真ん中あたりに、自治会からも高評価を得ていたという文面がある。それなりに指定管理者に指定されているわけですから、チェックしたりしていると思うんですけれども、その辺がどんな感じになっているのかその辺を。","respondent":"諸石交通安全担当課長、柏原住宅担当課長","answer":"細かいいろいろな話をさせていただいて、実際に駐輪場の運営がどんな状況なのかというのは目で見て確認させていただいているところであります。ＮＣＤの担当者が毎日区の自転車係のほうへ連絡で顔を出しますので… 例えば、それは一度指定管理者を通してなんですが、そういったものでどういう意見が出たかというのもこちらに報告が上がってまいります。それはそのまま上がってまいりますので、そういったところとあわせまして…","id":"exchange-030"},{"speaker":"高橋委員","kind":"質問","question":"１つは指定管理業務の概要の中に設備の維持・修繕・入れかえとあるんですけれども、もう１つは、それを監視する方はまた別にいらっしゃいますよね。注意したことによって、その辺の線引きはどういうふうにしているのか、その２つを説明を求めました。","respondent":"諸石交通安全担当課長","answer":"これが１週間とか、１０日とか、長期にわたって全然移動した形跡がないというような自転車があるわけなんです。そうしたものについては、連絡をしていただいて、区と連携をとった上でこれを速やかに撤去するということでやらせていただいているものです。","id":"exchange-031"},{"speaker":"阿部副委員長","kind":"質問","question":"その上で２点ほどお伺いしたいんですけれども、それは単なる表現の問題なのか、ちょっと教えてください。あるいはノウハウの面でフォローを、既にやっていらっしゃるのかもしれないですけれど、その辺の考え方を説明を求めました。","respondent":"諸石交通安全担当課長、柏原住宅担当課長","answer":"弾力的な料金の導入についての検討、先ほども申し上げましたとおり、区の条例の範囲内でやっていただくということになります。平成２３年度に入りますと、それまでに区は料金の体系について… 品川宅建管理センターの部分ですけれども、こちらにもありますように、事務処理能力であるとか、こういった記載をさせていただいているところです。平成２０年度から人員が大分変わりまして…","id":"exchange-032"},{"speaker":"阿部副委員長","kind":"質問","question":"放置自転車の減少に効果があるというような社会実験もかなり積み重なっているようですので、また別の機会があれば、お聞きしたいと思います。ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"}]},{"id":"topic-06","title":"その他を議題とします。まず、（１）の所管質問","agenda":"その他を議題とします。まず、（１）の所管質問","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"ですから、この問題点として挙げられる部分をどういうふうにクリアしていくのかということが、早急に必要なのではないかと思っています。ですから、その辺についてもう少し詳しい答弁をもらえればと思っています。","respondent":"吉川防災整備担当課長","answer":"実施状況ですが、耐震診断を平成１６年度から行いまして、平成１８年度を除いて、年々件数が増加し、５年間で２９４件の実施です。高齢者等の建て替えや住み替えの啓発につきましては、今検討中の住情報センターの検討とも連携して、取り組みを考えていきたいと考えています。","id":"exchange-034"},{"speaker":"菊地委員","kind":"質問","question":"本当に命を守る課題ですから、９０％の目標に対してどうするのかというのは、今までの手だてでいいのかというのがあると思うんです。そこをもう１度……。","respondent":"吉川防災整備担当課長","answer":"それと、耐震診断は５年間実施しておりまして、３００件近い実績も上げているところです。さまざまな、スタートしてまだ間もない事業ですので、今後実施状況が急激に伸びていくことも全く期待できないわけではないと考えております。","id":"exchange-035"},{"speaker":"菊地委員","kind":"意見","question":"目標である９０％にどう到達するか、そういう目標設定の仕方というのが、どうしても必要になるのではないかと思うんです。そもそも９０％という目標に対してどのように、９０％目標をどのようにとらえているか、そこをちょっとお聞かせ願えますかとの意見を述べました。","respondent":"岩田防災まちづくり事業部長","answer":"それよりもまず、今回、去年やった住民の方々の認識度の低さ、向こう数十年の間に東京直下の地震があるということは、８割以上の方が認知されている。これは十分検討しながら、今後の施策を打っていきたい。","id":"exchange-036"},{"speaker":"菊地委員","kind":"質問・要望","question":"９０％目標に到達するためにどういう手だてを打てばいいのかという目標設定をしながらやっていかない限りは、今、制度ができ上がっているから。ですから、上がっていくんじゃないかと、そういう目標設定をしていっていただきたいなと思いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"新しい首相が２５％削減するとどおんと打ち出したんですけれども、堺市にしても、これが切り替えていかなきゃならない部分につながるものなんですか。そこだけ教えていただきたい。","respondent":"久保田都市環境事業部長","answer":"堺市がどういうふうに考えるかというのは、これから行ってお聞きしていただければと思います。まさしく策定検討中ですので、国の方針、それは基本だろうとは考えています。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814084?Template=document&Id=3958#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":38858,"voices":120}},{"id":"h21-20090925-9","meetingId":"h21-cm09","date":"2009年9月25日","dateIso":"2009-09-25","committee":"文教委員会","time":"午前１０時０３分～午後３時０１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件整理しています。","topics":[{"id":"topic-01","title":"はじめに(1)区営住宅に併設する図書館の耐震化工事","agenda":"はじめに(1)区営住宅に併設する図書館の耐震化工事","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"平成２３年度中に工事を始めるということなのか、１年なのか、どういう工程を見込んでいるのか教えてください。もう１つ、品川区の図書館はたしか全部で１０館あったと思うんですけれども、現状についてあわせてご説明いただけますか。","respondent":"小川品川図書館長","answer":"工期の見込みですが、予定では平成２２年度に実施設計を行う予定です。今、おそらく半年以上はかかるだろうというぐらいまでしかまだ見込みはたっておりません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"二葉図書館の休館はおそらく半年以上ということでしょうから、しっかりお知らせのほうはよろしくお願いします。それといわゆる休館中というのは窓口の委託契約というのはどういう扱いになるのか、ちょっと教えていただけますか。","respondent":"小川品川図書館長","answer":"１点目のゆたか図書館の建設年度ですが、設立は昭和５０年１０月になります。休館中は当然サービスも差し止めることになりますので、この期間中は契約をしないということになろうかと思います。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"築何年になるんですか。まだどういう形になるかわかりませんけれども、もし老朽化が激しいということであるならば、その原因は何かおわかりか尋ねました。","respondent":"小川品川図書館長","answer":"建設年度は昭和４４年度ですので、約４０年近く経っているかと思います。あわせまして関係課、技術系の部門と相談した結果、耐震補強をするという選択になったものです。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"それと耐震化工事ということは、これはまだ具体的にどういうものでやっていくかはわからないですけれども、補強という形なんですかね。それはどういう形になるんか尋ねました。","respondent":"小川品川図書館長","answer":"補強するための鉄骨を入れるですとか、そういったことを行いますので、当然図書館全体ではレイアウトの変更が必要になろうかと思います。ただ現状の図書館機能は維持できるということは保証されておりますので、限られた中で工夫をしてまいりたいと考えています。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"整備を進めていただきたいという気持ちもあるんですが、そのためには、耐震工事をすることですませたという形ができてしまうと思うんですね。それは所管が違うという部分になってしまうと思いますので、意見として言っておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"二葉図書館の蔵書をどうされるのかというのが気になっていて、そこら辺の概略、もしわかっている部分がありましたら説明を求めました。","respondent":"小川品川図書館長","answer":"約５万８,０００冊程度の蔵書がございまして、当然ですが、ほかに一旦は置くことになろうかと思います。ちなみに２年ほど前ですが、日野中の体育館をお借りしたような経緯がありますので、工夫していきたいと考えております。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"一旦は不利益というんでしょうかね、そこら辺はしっかりと住民の方に理解を得られるような形をつくってほしいと求めました。例えば配本というんでしょうかね、そういった面というか、そういうことも少しは考えなければいけないのかなと。","respondent":"小川品川図書館長","answer":"今はそういったことになっておりますが、こちらにつきましても、一度は来ていただく。それから返しに来ていただくという流れは、できますれば今後も続けていきたいと考えております。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"そういうところでのこれから危惧されていることとか、検討していかなければいけないなというところがあれば、ちょっと紹介してほしいなと。私もわかっていないのですけれども、その辺で何か区のほうで考えていることとか、懸念されていることがあれば説明を求めました。","respondent":"小川品川図書館長","answer":"都のほうにもいろいろ情報を収集していただいているところなんですが、今のところ、詳細内容が伝わってきていないというのが現状です。今のところはまだそちらのほうもわかっていないので、今後とも情報収集に努めて、できればきちっと連携をしていきたいと考えております。","id":"exchange-008"},{"speaker":"林副委員長","kind":"質問","question":"平成２３年度にやるということになるんだけれども、耐震工事をやっていて、どこも休んでいないんだよね。そうすると、ここの二葉一丁目住宅の耐震工事をやったときに、図書館とか保育園を休まなければいけない理由というのがあるんか尋ねました。","respondent":"小川品川図書館長、市川教育次長","answer":"図書館に関しましては、基本的には本を読むところということで、騒音に関してはかなり激しい騒音が出るということは伺っております。 建物の外部の一部、例えば通路がふさがれたりとかしていますけれども、建物の構造を支えている壁とか柱には基本的に手を入れない。したがって中の業務は継続できるということですが、今…","id":"exchange-009"},{"speaker":"林副委員長","kind":"質問","question":"とすると、住宅も明け渡してもらうんですか、一時。ああそうですか、じゃ、私たちは区民サービスをしているのを閉鎖するというのは断じてならないというふうに教育長は言わないのか尋ねました。","respondent":"市川教育次長","answer":"小・中学校の耐震補強工事を実施してくる中で、これは耐震性能を強度なものにする、一定の数字をクリアするように強度を持たせなくてはいけない。あの外壁を補強することによって、建物全体の強度がもつような場合にはいいんですが…","id":"exchange-010"},{"speaker":"林副委員長","kind":"質問","question":"２６号線の工事がずっと続いていて、空き巣が２件入っているんですよ、あの近隣で。ですから、事故なく、そういう区民に害が及ぶようなことも極力ないように進めていただくようにお願いをしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ平成２３年度に工事をやるということ、その資料を教えてくれればそれでわかったんだと思うんだけれども、その流れをご説明いただきたい。３つ目が、それとももうここに仮設をするという意味なのか、ちょっとよくわからなかったのでご説明願います。","respondent":"吉岡保育課長","answer":"実施設計、平成２２年度が設計の期間、平成２３年度が工事の実施年度ということで決まったというのがスケジュールです。できればここで保育園業務を継続できれば一番いいわけでして、平塚小学校の跡地施設のほうに入れられるように段取りはつけておいたです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"それはいつからなのか、何年間なのか、教えていただけますか。それともどこか仮設を考えているのか、同じ保育園なのによくわからないので、わかりやすくご説明いただけますか。","respondent":"吉岡保育課長","answer":"ご説明が適切でなかったのかもしれないんですけれども、必ず出なければいけない、必ず残れるということが今の時点では未確定な部分があるです。保育園をそこで継続することができれば、先ほど申し上げたように、その辺については設計の中で探っていくものかなと考えております。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"まだ別の園舎に行くか行かないかも含めて今、検討しているというご説明なんでしょうか。この時期に区議会に報告していただいたその理由というのはどこにあるのか教えていただきたいのと、具体的にいつどんな方法で保護者に、おそらく今。","respondent":"吉岡保育課長、古川子ども未来事業部長","answer":"平成２３年度に工事を予定していますので、５歳の方は卒園されちゃうんですけれども、在園児にも説明しなくてはいけないということ。こちらは平成２３年度までに工事するわけですけれども、平成２１年度以降… 住宅におきましてはお住まいの方、併設する施設においては施設の利用者等々に、平成２３年に間違いなく工事を予定している。近くです平塚小学校の跡地に今、ちょうどそこに新しく建物を予定しているものがありますので…","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"先ほどの説明ですと、公立の認可保育園はあと都営住宅と併設している八ツ山保育園のみで、あとは終わったという説明でよろしかったでしょうか。品川区の耐震改修促進計画か尋ねました。","respondent":"吉岡保育課長","answer":"私立園につきましては、それぞれ一定の工事費等が必要になるということで、それぞれ検討されて、努力はされているところだと聞いておりますけれども、今、手元に各園ごとの資料を持っておりませんので、それ以上の説明は控えします。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"公立、私立問わず、認可保育園の耐震化を１日も早く進めていただきたい、要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"未確定なところが多々あると思うんですが、この後、報告があると思いますけれども、平塚小学校跡の土地、清水台保育園というのは、ここの敷地内に仮園舎を、ということなんか尋ねました。","respondent":"吉岡保育課長","answer":"後ほど、平塚幼保のご報告の中で図面が出てきますので、その際にはその図面をごらんいただきたいんですけれども、とりあえず新しくつくっている施設の敷地の中に仮設の園舎を置かせていただきたいということで、今お願いをしております。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"平成２２年度、平成２３年度、仮設の園舎に。ここの中で安全面とか、どういう格好にしていくのかというのが見えないんですけれども。","respondent":"吉岡保育課長","answer":"工事は平成２３年度中に実施をするということは今、あるいは８カ月で終わるのか、その中で固まっていくと考えています。その際、当然両方とも園舎が建ちますので、当然工事現場とは遮蔽をするなり、十分な対応をとった上で工事を施行していただくという形になります。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"これは周知をするときに配慮していただきたいことなんですけれども、そうなると、そこはきっちりと説明を加えていただきたいと思っています。やっていただきたいなという部分もあるんですが、考えられないことではないと思うので、配慮をお願いします。","respondent":"吉岡保育課長","answer":"それが終わって安全、耐震性が担保されれば、またもとへ戻るという予定でおります。その辺も含めて、十分誤解のないように、保護者の方等にはお話ししていきたいと考えています。","id":"exchange-019"}]},{"id":"topic-02","title":"御殿山幼稚園の移転","agenda":"御殿山幼稚園の移転","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"移転計画がどういう流れなのかよくわからなかったのでお聞きしたいんですけれども、戻ってくるというんですかね。それともう１点は、その辺はどんなふうに考えていらっしゃるのか、教えていただけますか。","respondent":"吉岡保育課長","answer":"直線距離にして７００ｍから８００ｍかなと思いますが、その辺は事前にご説明する予定でおります。４歳児、５歳児はそれぞれ卒園されてしまいますので、これから入園を予定されている方にこういう移転が予定されておりますということをお話しして。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"そうなると、品川地区の小中一貫校の幼保一体施設というんですか。４歳児、５歳児と書いてありますので、ご説明いただけますか。","respondent":"吉岡保育課長、田村庶務課長、古川子ども未来事業部長","answer":"それから開設の時期につきましては、移転を平成２３年４月に予定していますので、平成２３年４月にはじめるです。５歳児だけではなくて… 御殿山幼稚園の幼保の移転だとか、また再開発のところに戻るという話と御殿山小学校の改築とは、特に連動していません。ですから… 先ほどご説明しましたように、そこで３年間、御殿山幼稚園としての運営をしていきたい。２歳、３歳までの保育園は当初から考えておりましたので…","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここの幼保一体施設というんですか、その２つが同居している、そういう考えでよろしかったんでしょうか。御殿山幼稚園が戻った後は、４歳、５歳も保育園児として年齢が拡大するというんですかね。","respondent":"吉岡保育課長","answer":"ただ４歳児から幼稚園部分に入る方の枠というのをご用意しています。先ほど部長がご説明しましたように、幼稚園の新設ということは考えてございませんので、４歳から５歳までの保育園という形になろうかと思います。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"０歳から５歳までの年齢ごとの定員は何人になるのかというのを伺いたいんですけれども、もちろん御殿山幼稚園が３年間来るわけですから、何人枠になるのかご説明いただけますか。","respondent":"吉岡保育課長","answer":"平塚のほうもまだ人数を最終的に固めてございませんので、しかるべき時期が来れば、適切な形で定員を定めていきたいと考えております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"同じ規模の４歳、５歳の定員になるというのは明らかなんでしょうか。結果として３年後できる幼保一体化施設の定員というのも今後決めていくということなのか。","respondent":"吉岡保育課長","answer":"失礼いたしました。幼稚園については１クラス３５人というのが上限になってありますので、その範囲内で、適切な定員を設定していきたいと考えているところです。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"１歳、２歳、３歳を含めた幼保一体の施設になるわけですね。その形をもって、平成２５年、平成２６年に再開発に戻っていきますよということか尋ねました。","respondent":"吉岡保育課長","answer":"０歳から３歳までを加えた保育園機能と幼稚園機能をあわせ持った幼保一体施設として平成２３年４月から品川の小中一貫校のところで運営を始めます。それから戻るときなんですけれども、どういう形で戻れるのか、それを見極めながら最終的な判断はする形になろうかなと考えていま…","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"ということは、先ほどの説明で平成１９年のときとそこが変わっているということ、まだ不確定だということでいいんですか。だけど今は、どういう状況になるのか、ならないのか不確定ですよという段階なのかということです。","respondent":"古川子ども未来事業部長","answer":"ですからそのとおりに動けば、再開発組合における完成した中に幼保一体施設をつくるという考えはあるわけです。したがって、新設の保育園はいずれにしても２カ所に将来はできるということです。","id":"exchange-026"},{"speaker":"西本委員","kind":"確認","question":"それの確認と、それから、そうなると、かなりそこを説明していかないと、０歳、１歳、２歳、３歳ですよね。そこの説明とかというのははっきりといつどのような形でされているのか。","respondent":"吉岡保育課長","answer":"１点目の御殿山幼稚園が再開発施設内へ戻った後の保育園ですけれども、幼稚園を新設する考えはございませんので、残るのは保育園が残る。年明けぐらいに保育園の募集をかけるときに、３年後には御殿山幼稚園は戻りますというご説明は、当然あわせてするということになると思いま…","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"幼保一体施設、幼稚園と保育園の垣根をなくそうという形で、いろいろ幼稚園側もやっていると思うんですね。認定こども園だといっても、多分まだまだそう整理はできない部分があると思うので、しっかりと説明をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"井上委員","kind":"意見","question":"幼稚園型の幼保一体型になったとすると、０歳から３歳までも一緒に移転をするのかどうかということが、そこのところがまずどうなのかというのが１点。保育園型の幼保一体というふうにお話を聞いたら、途中で部長が幼稚園型ですというようなこと…","respondent":"吉岡保育課長","answer":"工事による移転の３年間が終わったときには、御殿山幼稚園は再開発地区に予定されているところへ戻って、幼保一体施設としてそのまま戻ります。この時点では幼稚園ではありませんので、乳幼児教育の充実はほかの園と同様実施していきますけれども、残るのは保育園です。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問・要望","question":"この地域で説明はどういうふうに、どういう形で今の説明というか、ちょっと確認させてほしいと求めました。","respondent":"田村庶務課長","answer":"地域の町会だとかＰＴＡなどを含めた中では、幼保の施設についても区として必要なので、飛び地のほうに設置をしますという形で説明はしています。３年の仮移転なので、今の時点でその名前を品川の小中一貫校にくっつけてどうするかとかいう話は…","id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"今、しっかりと説明をいただく機会を設けてほしいなというのが１点ありますので、あの地域は就学前のお子さんが結構増えているんですね。限られた人ではない方たちへの説明も企画していきたいと思うんですが、まずはそのことが地域に発信されるのはいつと考えたらよろしいんか尋ねました。","respondent":"吉岡保育課長","answer":"本日、委員会への報告が終わりますので、早急にしていきたいと考えております。","id":"exchange-031"},{"speaker":"井上委員","kind":"質問・要望","question":"早急って、大体いつごろというところをはっきりと、いついつですというのはないにしても、１０月初旬なのか、中旬なのか、そういうことぐらいはお伝えほしいと求めました。","respondent":"吉岡保育課長","answer":"幼稚園の今年度の入園の説明会が１０月２７日に予定されておりますので、地域についてはそれまでにはお話しします。","id":"exchange-032"},{"speaker":"浅野委員","kind":"質問","question":"１点だけなんですけれども、飛び地のほうなんですけれども、将来的には０歳から５歳までが入る施設になるわけですけれども、例えば地震ですとか災害が起きたときに、隣の学校に避難することが想定されるのか、どういう形でかちょっとお伺いします。","respondent":"吉岡保育課長","answer":"保育園児、幼稚園児の避難場所ということでしょうか。","id":"exchange-033"},{"speaker":"浅野委員","kind":"質問・要望","question":"かなり道路が細かったりしていて、また駐輪場が１２台ということもありますので、そういう計画もしっかりとぜひともお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"林副委員長","kind":"確認","question":"この品川地区の一体型の小中一貫校にできるいわゆる就学前の子どもたちの施設というのは、幼保一体型じゃないんですか。どっちが答えなんか尋ねました。","respondent":"古川子ども未来事業部長","answer":"今後さまざまな地域の事情を踏まえた上で検討させてくださいと、こういう答弁をした記憶があります。５歳児も当然、平成２６年度以降は保育園を母体とした、幼保一体にひけをとらないような教育環境を整備をしていきたいと考えております。","id":"exchange-035"},{"speaker":"林副委員長","kind":"質問","question":"一体型の一貫校をつくるときには、幼保一元化された就学前の施設をつくるというのは、もう放棄したんですか。これは教育委員会に聞きます。","respondent":"市川教育次長","answer":"ドッキングができる範囲で、考慮できる限りは幼保一体施設の併設を考えてまいります、こういった趣旨の説明をこれまでさせていただいたと思います。私どもがちょっと見込めないアクシデントと申しましょうか、これから設計に取りかかってまいりますけれども、荏原東については。","id":"exchange-036"},{"speaker":"林副委員長","kind":"確認","question":"確認しておきますけれども、うちで独自に考えた形をつくっていく、そういうふうに理解しておいてよろしいか尋ねました。","respondent":"市川教育次長、古川子ども未来事業部長","answer":"ましてや保幼小の連携ということを今いろいろ言っているときですので、可能性を追求していきたいという考えは持ってあります。そういったことを区長部局のほうに常に投げかけていきたいと考えていますし… したがって私どもは、当然子どもは０歳から５歳児に、その後６歳児から小学校、中学校に行きます。子どもが大人になっていく、その貴重な時間を共有しながら子どもの教育にあたる、このように考えております。","id":"exchange-037"},{"speaker":"林副委員長","kind":"質問","question":"改めてまた教育委員会あるいは品川区の全体的な考え方、ここだけでは済まない話にもなりかねないので、また別の機会でやりますので置いておきます。それから戻るという話をもう１時間近くやっているんだけれども、知らんぷりしていてていいわけですか、現段階では。","respondent":"田村庶務課長","answer":"御殿山小学校の改築については、先ほども、２年前もそうなんですが、再開発と連動して改築を現敷地内で予定している。実施設計１年、さらに１年追加するのか、最終的な詰めを行っているという状況です。","id":"exchange-038"},{"speaker":"林副委員長","kind":"質問","question":"その改築するところの御殿山小学校と御殿山幼稚園というのは、一体型にできるという自信はお持ちなんですか。教育委員会の考え方をちょっと聞かせてくれますか。","respondent":"市川教育次長","answer":"確定しないまでも、改築をするという方針には基本的には変わりはないということで、私どもできる限り早く時期の明示をしたいとは考えております。ただそのソフトを考えるときにも、１つ検討のポイントにはなるだろうと考えています。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問・要望","question":"以前にやったこともありますので、ほかの委員会同士が２つで説明を受けたことがありますので、そういうはかりをぜひしてほしいと求めました。御殿山小学校の改築で以前文教委員会にいなかったので確認なんですが、保護者の方が伺っていますが、その辺をちょっとだけ確認させてください。","respondent":"市川教育次長","answer":"本日、資料で提供いたしました中で、平成１７年１１月に文教委員会にて報告となって以後、今、委員のご質問にございました仮設はつくりませんというような説明は一切行ってきてございません。","id":"exchange-040"}]},{"id":"topic-03","title":"（仮称）平塚幼保一体施設整備計画","agenda":"（仮称）平塚幼保一体施設整備計画","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"改めて伺いたいのは、要は、認可保育園の新たな設置にもなるということですよね。それと定員が１２０名から１５０名程度ということですけれども、年齢別にどう想定しているのか、ご説明いただけますか。","respondent":"吉岡保育課長","answer":"幼稚園の定員の上限が１クラス３５人になってありますので、今、基本的には幼稚園部分については同じような内容かなと考えています。０歳から３歳の保育園児につきましては、どのような形が一番適切なのか、充分検討しまして設定を行っていきたいと考えております。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"保育園部分の０歳から３歳の定員の入園の動向を見て設定ということですけれども、どういうふうに保育需要を担っていくのか。仮設１のところではまず幼稚園の仮設があって、仮設２のところの保育園が先ほどの保育園の仮設園舎、教えていただけますか。","respondent":"吉岡保育課長","answer":"こちらの開設の予定が、その間に検討し、考え方としてはそういうことです。あるいは近隣の公園を使用するなど、具体的な現場の状況につきまして、安全に十分配慮しながら検討してまいります。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"それをどんなふうにつかみ把握して、それがどう定員として反映していくのか、この仕組みがよくわからなかったんですね。平塚の周りでもなかなか保育園なんかが大分不足しているという話をよく伺いますので、幼保一体化施設の要望にどうこたえる形で、定員だったり。","respondent":"吉岡保育課長","answer":"定員の考え方については、基本的には、最終的には施設のキャパシティに限定されるのが、マキシマムでの上限ということになろうかと思います。いずれにしても２年後の話ですから、その間の入園希望の状況等々を見ながら、設定をすることになろうかと思います。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"確認をさせていただきたいんですが、保育園と幼稚園と、それから区民の方が使われる部分という、これというのは完全に、動線を知りたいんですけれども、完全にシャットアウトしてしまうのか、保育園側から使えるという形もつくり出せるのか、そこはいかがか尋ねました。","respondent":"吉岡保育課長","answer":"詳細はまだこれから実施設計の中で詰めていくんですけれども、基本的な考え方といたしまして、しっかり確保していきたいと考えています。これからの区民施設のほうの運営の問題とも絡んでくるところですので、どのような形での活用ができるのか…","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"１階にもスタジオ、これはどういう使い方をされるのかということと、駐輪場はどのくらいの収容を考えているのかなと思うんですね。駐車場というよりは駐輪場のほうが広いほうがいいのかな、という部分があるんですが、それはどういうお考えなんか尋ねました。","respondent":"吉岡保育課長","answer":"先ほどちょっとご説明を漏らしてしまったんですけれども、こちらは幼保施設の所管なので、区民施設のほうは存じていない部分もあります。聞いております範囲では、駐輪場は区民施設のほうとしては２カ所合わせて１２０台、駐車場は２４台と聞いてあります。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"駐輪場なんですが、幼稚園側のほうにも必要だと思うんですけれども、それはどこら辺に設置する形なんか尋ねました。","respondent":"吉岡保育課長","answer":"詳細は実施設計を進める中で最終的には詰めていきたいと思います。いずれにしても施設の隣接したところです。","id":"exchange-046"},{"speaker":"浅野委員","kind":"質問","question":"ここに駐車場もまた今回の仮の校舎というんでしょうかね、そういう制限があるのかどうかということをちょっとお伺いしたいなということ。出入りは制限されるんじゃないかなと思うんですけれども、これだけ細くて長いのはちょっと気になっているんですけれども、この２点について。","respondent":"吉岡保育課長","answer":"こちらの三角形の部分が使えないで残っているというところにつきましては、設計上の話になりますので、ちょっと詳細はご容赦いただきたいと思います。直接外部の人が入れないような形の管理を行うというふうに考えてありますので…","id":"exchange-047"},{"speaker":"林副委員長","kind":"質問・要望","question":"１面と２面。ちょっと説明を求めました。","respondent":"吉岡保育課長","answer":"階段を上っていくと２階部分へ行かれるという形でございまして、２枚目の１階平面図ですけれども、それを真っすぐ入っていくと１階へ入れる。これを上っていくと２階へ出るという構造です。","id":"exchange-048"},{"speaker":"林副委員長","kind":"質問","question":"２枚目のこの左側は喫茶室とか絵がかいてあるのね。１枚目と２枚目と全然違う絵なんか尋ねました。","respondent":"吉岡保育課長","answer":"ここが先ほど申しましたように１階の地盤面になるんですけれども、こちらについては、階段を上がったこの面は２階の床面になります。こちらは１階の建物部分になりますので、２枚目の１階平面図の喫茶室や便所なんかがかいてあるところがここに入るということです。","id":"exchange-049"},{"speaker":"林副委員長","kind":"確認","question":"もう１回確認する。１枚目のこのカラーの絵は、２階部分を鳥瞰図みたいにあらわしてあるんか尋ねました。","respondent":"吉岡保育課長","answer":"これはいわゆるパース図というものでして、一応立体的に見えるように透視図法的にかかれている絵ということでございまして、これは位置関係から言うと、斜め上方から見たような感じのイメージの絵ということになります。","id":"exchange-050"},{"speaker":"林副委員長","kind":"質問","question":"１枚目の絵は大ざっぱに鳥がのぞいているような鳥瞰図というのか、そういう絵だから、参考程度に見ておいてくださいよと。そういうふうに理解しておけばいいわけか尋ねました。","respondent":"吉岡保育課長","answer":"フロアごとの施設の配置がどうなっているかということをあらわした図面が２枚目です。１枚目については、その模型の絵画版のようなイメージで、イメージはこういう外観になるということでお考えいただければいいと思います。","id":"exchange-051"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"改めてまず一般質問のほうからなんですけれども、小中一貫校の法的位置づけという質問に対して併設校という答弁がありましたけれども、経過についてご説明いただきたいんですが。","respondent":"和氣小中一貫教育担当課長","answer":"さらに平成１７年１１月７日に、構造改革特別区域変更申請を出しまして、平成１７年１２月１日付でこれが認可されました。平成２０年度になりまして、この特別区域変更ということでございましたが、どこでもやっていいよという形に変更になりました。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"もうちょっと伺いたいと思うんですけれども、一番初めの平成１４年の文部科学省研究開発学校というのは、たしか３年間の指定でしたか。目的は小中９年間を一貫した、ということですけれども、研究開発学校というこの位置づけがどういう位置づけなのかを教えていただきたい。","respondent":"和氣小中一貫教育担当課長","answer":"実際にどういうカリキュラムを組んでいくのかという実践研究になりますので、実際に実践的に検証しながら研究を進めてまいったわけです。最初は本当に研究、研究だったのが、だんだんそれが認知されていき、最終的には認められてきたという経過だとご理解いただければと思います。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"初めの３年間の研究開発校の３年を待たずに、こちらの特区のほうに移行したというか、２つの学校が進んでいるということなんでしょうかね。つまり１年後にもう一方が動き出すという、それと一緒に伺いますけれども、文部科学省のほうの変更と言ったらいいんでしょうかね。","respondent":"冠木指導課長","answer":"考え方としては、規制緩和という一環の中で教育をどういうふうに見ていくかという考え方からのスタートですので、その辺の部分はあります。構造改革特別区域ということで内閣府が進めてまいりましたけれども、文部科学省の教育課程の特例校という扱いになってきたです。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"平成２０年の認定のときも取り消しというのがあって、こういう形になった。この６年間でここまでの節目、方向としてはどういう方向を向いているのかがあるんですけれども、ちょっとそこを説明を求めました。","respondent":"和氣小中一貫教育担当課長","answer":"ご説明していましたように、これは全部議会に報告させていただいていますので、別に秘密裏にやってきたわけでは全くございません。文科省の中でも法制化に向けたプロジェクトチームも設置されておりまして、今、その方向に動いていると考えています。","id":"exchange-055"},{"speaker":"中塚委員","kind":"意見","question":"で公教育がどうあるべきかとか、あと学習と、そういうのを養っていく。そういう公教育の役割も同時に必要というか、当たり前のことですけれども、大切かなと思うんですとの意見を述べました。","respondent":"若月教育長","answer":"今、中塚委員がおっしゃったことはもっとものことです。どの地域へ行っても、またどんな形態の義務教育でも、学習指導要領によってすべての学習の内容は担保されているということであります。","id":"exchange-056"},{"speaker":"中塚委員","kind":"意見","question":"子どもたちに接するそういう環境、これはやっぱり要というか、大切だなと思いますとの意見を述べました。","respondent":"若月教育長","answer":"したがって、一貫教育であろうと、６・３の普通のあれであろうと、教師が子どもに直接触れ、地域と一緒にやっていく。それは少しも変わらないんだということ、それをよくお考えいただきたいと思います。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"昨日配付された資料なんですけれども、昨日もちょっとお伺いしましたけれども、要するにこの位置づけはと。これは何だということをご説明いただきたい。","respondent":"和氣小中一貫教育担当課長","answer":"平成２０年度に関しましては、新時代に対応した高等学校教育等改革推進事業という研究事業の委託を受けまして、これで検証を進めてまいりました。３年次にわたりまして、これにつきましては、経年でとるものについては来年度以降も私どもは検証を続けてまいりたいと思ってありま…","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"今のご説明ですと、平成１８年、平成１９年が新教育開発プログラムの予算を使ってということだったんでしょうかね。平成２０年は、要するに別の予算を使ったけれども、３年間の検証をしたということで、来年もというお話でよかったんでしょうかね。","respondent":"和氣小中一貫教育担当課長","answer":"個々の個別の細かい部分での変更なんかもこれを参考にしながらやっていますけれども、そこに全部反映されているという考えていただければと思います。これを踏まえて私どもは次の政策を考え、継続するものはしっかり継続をしていくというふうに…","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が聞きたいのは、教育委員会としての総括を、プラン２１が始まって１０年余りでしょうかね。それをしっかりと示していくときではないのかなと思うので、そこをご説明いただきたいんですけれども。","respondent":"若月教育長","answer":"その都度、さまざまな変更点があれば、皆様方にご報告を申し上げている。今やっている教育改革そのものをやめるとか何とかという意味での総括では全くありませんので、その点は十分にご理解をいただきたいと思います。","id":"exchange-060"},{"speaker":"中塚委員","kind":"意見","question":"施設一体型の学校だったり、またいわゆる９年制といいますか、教育のカリキュラムの中身そのものでしょうね。まあ、子どもの反応を教師や保護者がどう感じ取るかという部分もあるでしょうけれども、そういう総括が必要ではないのかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問・要望","question":"この場合に求めたもの、品川区が求めた規制緩和は何だったのかということを、ちょっと確認させてください。","respondent":"和氣小中一貫教育担当課長","answer":"さらにこれが３年延長になり、６年間やらせていただくんですけれども、そのまま日野は継続できたということであります。品川区全域を認定してほしいという形での変更申請を出させていただいて、品川区のすべての小・中学校でこの小中一貫教育を展開できるということです。","id":"exchange-062"},{"speaker":"井上委員","kind":"質問・要望","question":"もう既にここの平成１５年のところで原小学校と伊藤中学校の、議事録を確認して、なかなか納得ができない。納得ができないという部分は本当に反省をしていただきたいと思っているので、区民がわかるように、ちょっと詳しく説明をほしいと求めました。","respondent":"和氣小中一貫教育担当課長","answer":"それ以降、それに合わせてやりましたし、平成１５年には教育委員会で小中一貫校も決定しております。誤解だと思います。","id":"exchange-063"},{"speaker":"井上委員","kind":"質問・要望","question":"わかりました。２点だけお伺いしたいんですが、義務教育学校の法制化の９年間の教育ということで、お答えほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"井上委員","kind":"意見","question":"そういう法制化なのか、それは国がやることだと思うんですけれども、イメージがちょっとの意見を述べました。","respondent":"和氣小中一貫教育担当課長","answer":"今、これについて特に大きく変更する考えは今のところございませんけれども、さまざまな形の義務教育が９年間の展開ができるようなことを。９年間という義務教育の範囲内でさまざまな形態の学校の設置ができるように法整備をしていただきたいというお願いをしています。","id":"exchange-065"},{"speaker":"林副委員長","kind":"意見","question":"それを今さらどうするという話を持ち上げないようにしてほしいというのは、これは教育委員会に伝えておきます。いろいろな議会の議員の所属する会派の思惑によって教育をどうこうしようという考えにはならないでほしいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"中塚委員","kind":"意見","question":"平成２１年度から移行期間となっており、今どうやって授業をやっているのかと思うんですけれども、まずそこをご説明いただけますか。もう１つは、どういう仕組みで学校からの希望を受け付けているのか、あわせてご説明いただけますかとの意見を述べました。","respondent":"富田学務課長","answer":"教育会の理科部会のほうでおおむね改訂に伴う統一した物品をリストアップしていただいて、その希望を各学校ごとにとるということを１度いたしました。それとは別個だけれども、老朽化してどうにかしてほしいという希望調査も行い、この２度の調査を合わせて購入金額を決めたです。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"学習指導要領の改訂ですから、もっと学校に自由度というんですかね、どうも時間の落差を感じてしまうんですね。もっと学校の自由度を高めることというのはできないものなのか、その辺をご説明いただけますか。","respondent":"富田学務課長","answer":"教育会等々の協力も得てやっておりますので、その点は学校の教材費で買うものと、学校としても選別して希望を出してきたものと考えているところです。議案として提出していますので、本件の議決を正式にしていただきました後に正式な契約を行い…","id":"exchange-068"}]},{"id":"topic-05","title":"行政施設","agenda":"行政施設","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"何が伺いたいかというと、どういうふうに実践しているんだろうというのが一番この学校では学びたいなということなので、そこをよろしくお願いします。お聞きしてもいいか尋ねました。","respondent":"市川教育次長","answer":"ご質問いただいてすぐにぱっと浮かんだのが１校だけなんですけれども、芳水小学校は、もともとが民間人の方の私財を投じたというものから始まった。あるいは明電舎のスポンサーシップの中で提供される事業などを通じて行っているということを認識しておりまして、まさに地域を学…","id":"exchange-069"},{"speaker":"中塚委員","kind":"意見","question":"その１つは学校の成り立ちだったり、もちろん戦争という経験も１つの歴史の１ページだと思いますので、文化ですよね。意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問","question":"この報告について一言いいですか。何日にここ、次の日、午前と午後、大ざっぱと思いますけれども、行程表をご検討いただけたらと思います。","respondent":"堺委員長","answer":"それはまた正副で検討していきたいと思います。以上で本日の予定はすべて終了いたしました。","id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/298846?Template=document&Id=4682#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":61916,"voices":196}},{"id":"h21-20090925-5","meetingId":"h21-cm09","date":"2009年9月25日","dateIso":"2009-09-25","committee":"総務委員会","time":"午前１０時０２分～午前１１時５７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"１つ目なんですが、５１ページの土木費の中のしながわ水族館運営費の中で照明とありますけれども、そのところを教えてほしいと求めました。その計画性についてはどうだったのかという、その３点、教えてほしいと求めました。","respondent":"金子企画財政課長","answer":"他の区の施設、それを推奨していくというような形で対応をさまざま、これから検討していくものであるというような段階だというふうに考えてあります。契約を分割しなければならないということがありますので、その辺はこれから私どもとしましても…","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問・要望","question":"３点ほどなんですけれども、１つは５３ページのところで、暫定というのはどういう意味なのか教えていただきたい。補正で出てきているというのはどういう意味なのか、どういうふうなところに来ているのか、そこをお伺いしたいと思います。","respondent":"金子企画財政課長","answer":"最終的な整備をする予定ですけれども、例えばトイレの設置であるとか、あるいはスロープの設置であるとか。そういったところを推進するために、この地区について国のほうが事業を採択したということでの補正予算を計上しているものであります。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"この金額自体どうなのということになるので、大体このぐらい回るので、ちょっとお伺いしたいと思います。あるいは停滞しているということなんか尋ねました。","respondent":"金子企画財政課長","answer":"先ほど３つの広場をまとめてお答えしてしまったんですけれども、トイレを設置するのは今のところ１カ所で、それはその中でも一番広いところですね。具体的に出てきたときに実施するということで、あくまでも暫定であるという位置づけで、ここのところは変わりがございません。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問・要望","question":"二葉四丁目のところの２カ所については、それが今は公園なんだけれども、別な目的になる可能性があるということでいいんでしょうか。厳しい状況というのが今、再開発そのものがどうなのかということになっているんですけれども、そこがもうちょっと説明をいただきたい。","respondent":"金子企画財政課長","answer":"密集市街地住宅事業の種地として開放する予定はなかったんですけれども、あくまでもその事業、そのようにご理解いただければと思います。個人商店等の方もいらっしゃいますので、そういったところでは、非常に厳しい経済状況が反映しているかなと申し上げたところです。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどの暫定整備というと、二葉四丁目のところの小さいほうの公園についても、そういった小さいところについても今の説明でいいんでしょうか。こういうマンションだけはそういう意味では再開発をどんどん進めるというのはやっぱり一般区民から理解されないと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"土井委員","kind":"質問・要望","question":"ちょっとお伺いしたいんですけれども、補正というものは、いろいろな性格が含まれているわけですね。最初に言った、国が出してきたというのを予算化するというのはまた当然のことですから、緊急経済対策等で決まったからやるというものがあると。","respondent":"金子企画財政課長","answer":"冒頭にご説明しましたとおり、国の補正予算絡みが非常に多いということで、そういったものが対応している部分があります。少子高齢化社会への対応、その他将来に向けた地域の実情に応じるきめ細かな事業を積極的に実施できるよう交付するというふうに言われております。","id":"exchange-006"},{"speaker":"土井委員","kind":"意見","question":"何十分の１なり何なりの、何億という金額なのかどうか知らないけれども、それはどういうことなんでしょう。そして、その辺の考え方をちょっと、これからもこういうのがあったらどうするのという参考にもなる気がしますとの意見を述べました。","respondent":"金子企画財政課長","answer":"残る２分の１はこれも当てられますよということで、言ってみれば推奨がありましたので、これについては使う方向で考えていると。それから修学旅行につきましても、これも例示されていたものの１つでしたので、これについても当てさせていただいたという経緯があります。","id":"exchange-007"},{"speaker":"土井委員","kind":"質問","question":"それは区民のため、子どもたちのために使うのは別に何の問題もないわけですからね。それはまた別として、そういうものなのかということを聞きたいわけ。","respondent":"金子企画財政課長","answer":"小・中学校のテレビに関しましては、このところのテレビはご案内のとおり、アナログからデジタル化されるということが１つあります。国のほうでも５０インチぐらいという話がありましたけれども、品川区としては４２インチで、その辺ではご理解をいただきたいと思います。","id":"exchange-008"},{"speaker":"土井委員","kind":"意見","question":"この種のお金のときにどういう使い方をしていくかという下案が我々の中に、さあ、やろうということになったのかどうかということなんです。ここをちょっと聞きたいとの意見を述べました。","respondent":"金子企画財政課長","answer":"それはやっぱり何らかの事業を起こさなければならないというふうな判断もしていまして、たまたまこの地域活性化・経済危機対策臨時交付金の適用が明らかであるということがありましたので、これを対象事業として今回ご提案申し上げているという内容です。","id":"exchange-009"},{"speaker":"土井委員","kind":"意見","question":"そういうものというのは、まだある意味では予定なんだよね。執行することによって初めて、そして認定されることによってのみ、出てくるんだと思うんですけれども、それでいいんですよねとの意見を述べました。","respondent":"日下部企画部長","answer":"確かに予定には違いないんですが、今回、こういう形で国としては補正予算を考えている。国と地方のお互いの１つの地域の活性化なり何なり、今後とも、有効な活用を図っていくという基本的な考え方で進めてまいりたいと考えております。","id":"exchange-010"},{"speaker":"土井委員","kind":"質問","question":"区民のためにちゃんと使われるということと同時に、やっぱりそれが有効なんだなと。ちょっとお伺いさせていただいたので、あってほしいと思いながら、終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"山元委員","kind":"質問・要望","question":"何かそういうものがあれば教えていただきたいということと、教えていただければということで、その２点を教えていただきたい。","respondent":"金子企画財政課長、中川原広報広聴課長","answer":"それから自然体験活動開発支援事業は、大間窪小学校であります。手を挙げる学校が多い場合には、そういう観点から選んで指定するというふうに聞いているところで、そして先ほど申し上げた４校になったです。 私のほうから、４１ページのまちのサインの現況調査についてお答えいたします。有効なといいますか、役に立つサイン計画の策定をしていきたいということで、あげさせていただいたものです。","id":"exchange-012"},{"speaker":"山元委員","kind":"質問","question":"１つ、先ほど公募によってプラン２１の特色ある教育ということで、この学校は例えばサッカーが強いとか何かそういうことがあるんですか。それに決定的な何かがないと、ただ手を挙げたから、そこにしようというものか尋ねました。","respondent":"金子企画財政課長","answer":"学校の名前と募集の仕方は確認したんですけれども、申しわけないんですけれども、そこのそれぞれの学校の特色ということまでまだちょっと確認していないので、それは後でご説明させていただければと思います。","id":"exchange-013"},{"speaker":"須貝委員","kind":"確認","question":"どの程度の被害があったのかということをちょっと確認の意味で、５億円使っているわけですが、ここで密集住宅市街地整備ですよね。ＪＴの社宅跡地なんでしょうが、ここが防災活動広場また公園として整備するんでしょうが、ここは密集住宅市街地に当たるんか尋ねました。","respondent":"金子企画財政課長、大沢委員長","answer":"目黒区がそれぞれの地区ごとに応分の負担をもって対応しているというふうに聞いていまして、それも後ほど対応させていただければと思います。それから… 企画財政課長にお願いを申し上げます。総合審査における答弁ですので、総合的、包括的なご答弁のほうで結構ですので、個別的なものに関しては… 密集住宅市街地は二葉三丁目、四丁目、豊町六丁目のかなり広範囲に設定しています。","id":"exchange-014"},{"speaker":"須貝委員","kind":"確認","question":"項目の内容とすると、名前がちょっとふさわしくないのかなという、確認のために聞いた次第です。ここの繰越金というのが、これは区からの繰入金という解釈で、区から３億６,４００万円ですか、それを出してという考え方でよろしいんですよね。","respondent":"金子企画財政課長","answer":"そういう意味では、年度の当初予算は見込みでつくっておりますので、相差の部分があります。その相差の部分のところから、こちらのほうに繰越金を多少積み増しするという格好で計上しています。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"実際一般財源から入れて使っている、今回補正に対して使う額というのは、どこかに載っているんですか。総額で今回補正に対しては、それを区からは今回は一切繰入金というか、予算の持ち出しはないというふうな見方をすればいいんか尋ねました。","respondent":"金子企画財政課長","answer":"ちょっと質問趣旨を諮りかねるところがあるんですけれども、あくまでも平成２０年度予算の中で決算をした結果繰り越しをした額があります。その部分のところから計上しているということですので、新たに一般財源をどこからか工面しているとか、そういうことではないです。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"いろいろな分野にわたって雇用確保、緊急雇用ですか、あと経済対策ということその他教育関係も本当に評価できるものだと思います。そういうものじゃないというのなら、それで構いません。","respondent":"金子企画財政課長","answer":"年度当初に予定していなかったもの、当然のことながら、国にとっての必要なものというのを計上していかなければならないというふうに思っております。こういったことは大切なことだと考えておりますので、そういった考えで、今後もやっていきたいと考えています。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"プレミアム商品券の助成等は商連の要望ということもあって、使うほうも、私はこれはおかしいと思います。私は今の区政運営においてやっぱり根幹のところになってくるのではないかと思うので、これはこの中身から行くと、賛成できないと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"この状況を具体的に、どういうふうな状況なのか、具体的にどういうふうに回収をやっていくのか。何人ぐらい雇っていくのか、その辺がわからないので、教えてほしいと求めました。","respondent":"金子企画財政課長","answer":"具体的に対応するのは２人なんですけれども、保険料の収納率が９７.１％という収納率だったわけで、約７％の方が滞納者になっているわけです。あるいは訪問、あるいは口座振替の勧奨ということで、区職員の補助として位置づけて仕事を進めていっていただくという内容のものです。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今の７％とお話があったんですが、具体的に２人で対応する人数がわかったらですけれども、教えていただきたい。８月、９月のところの全体の普通徴収だったときの収納率というのと、１０月からのというのはわかるか尋ねました。","respondent":"金子企画財政課長","answer":"その細かい数字は持っておりませんので、わかりません。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"例えばこれから、この２人がいろいろ対応していくんですけれども、滞納している理由とか、そこのところは何か傾向というのは、区のほうとしてはつかんでいるか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"これをわざわざ２人配置するわけですよね。何か問題意識というか、そういうのがあったんじゃないかなと思うんですけれども、そこら辺のところはどういうふうに考えているのか尋ねました。","respondent":"榎本人事課長","answer":"この非常勤の関係ですけれども、実際に今、介護保険のほうでも同じく非常勤が２人ついております。正規職員を３人分追加した職員というのも一緒に合わせて、この中で後期高齢者の全体をやっていくという形で進めていくというふうに考えております。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"いろいろ例示して、やっぱりこれはこういうやり方で収納率を上げるというのは、私はやるべきじゃないと思います。反対ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと細かいことですけれども、精算で返すものだと思うんですけれども、国庫支出金等となっているんですけれども、国庫支出金と支払基金それぞれ大体どのくらいの金額になっているか、もうちょっと詳しい中身がわかるか尋ねました。","respondent":"金子企画財政課長","answer":"それから東京都につきましては１,０００万円ほど。支払基金が１,４００万円弱というような金額になっております。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと国の大体半分ぐらいが東京都になるのかなと思ったんですけれども、この違いが出てくるというのは何かわかるでしょうか。ちょっと私の記憶だと、国の半分が東京都だったかなと思うんですけれども、大分金額に差があるので確認しておきたいんですけれども。","respondent":"金子企画財政課長","answer":"国と都と支払基金を３つに分けましたけれども、お尋ねのところちょっと直接お答えできないんですけれども、さらに細分化したものがあるということでご理解いただきたいと思います。","id":"exchange-025"}]},{"id":"topic-02","title":"では２の行政視察についてですが、先に３のその他","agenda":"では２の行政視察についてですが、先に３のその他","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"全戸配布のことなんですけれども、今の説明に対して、考え方、どういうときに全戸配布をやるのかというのをもう１回聞いておきたいんですけれどもとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"平成１８年に区政６０周年記念を迎えたときに、区の６０年の歩みを特集しまして、品川ガイドの中にあわせましてお伝えすると。今後１０年、それと品川ガイドの本体の部分をあわせまして、保存版としてお使いいただく形で配布をするものです。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういう意味では必要な情報というのは広報で出ているわけですから、みんなに知ってほしいとか、やっぱり全部全戸配布するというふうにしてほしいと。そういう姿勢で対応するというのが必要だと思うので、私は改めて区報とか、そういうのはやっぱり全戸配布を要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"一部でもいいですから、いまだにやはり混んでいるということは、ちょっと問題があるのかなと。ちょっと無になっているのかなという気もしますので、そこはちょっと要望だけさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/829737?Template=document&Id=1834#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":34338,"voices":105}},{"id":"h21-20090928-14","meetingId":"h21-cm09","date":"2009年9月28日","dateIso":"2009-09-28","committee":"行財政改革特別委員会","time":"午前１０時０３分～午前１１時４６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"幾つかお伺いしますが、最初に数字を追いかけてしまっていたんですが、そもそもこの利用率の出し方はどういうふうに出していますでしょうか。ティーンズ館は８時までか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"それに対しまして、実際に利用されたのは４２コマですので、４２を６６で割りまして利用率を出しています。は日曜開館を行っている児童センターにつきましても、日曜の目的外使用は行っていないという状況です。","id":"exchange-001"},{"speaker":"渡部委員","kind":"確認","question":"確認だけなんですけれども、同じ中小企業センターでも、この部屋は工事をやっていたから使えませんでしたという日は分母から引いてある。必ずしも分母は一緒じゃないという認識でいいんですね。","respondent":"久保田行財政改革担当課長","answer":"委員がおっしゃるとおりで、工事等で使っていないところは分母から除いてありますので、同じ集会所の施設の中でも、分母の回数は異なるです。","id":"exchange-002"},{"speaker":"川西委員","kind":"質問","question":"それから区民集会所の使用料の決定基準、これは面積比なのかどうかということも含めて、もう１回伺います。これの決定の経緯も説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"私のほうで１０時までになった経緯を把握してございませんので、確認いたしまして、後ほどご回答させていただきたいと思います。使用料の全額を免除するという規定になってありますので、これ以外の利用については中小企業センターの減額といったものは適用されないです。","id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、２番目の区民集会所の使用料については、主に平米数で決定するということで承知しておいていいか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"委員おっしゃるとおり、基本的には平米数のほうから算出しまして、それぞれの施設の使用料を定めているといったところです。","id":"exchange-004"},{"speaker":"川西委員","kind":"確認","question":"それから先ほどの減免団体の申請は、２年に１回といいますと、今度何年が対象になりましょうかが１つですね。それから中小企業センターを利用している人から伺っていることなんですが、品川区で働いている人たちの名簿を出すと、この辺を確認したいと思います。","respondent":"久保田行財政改革担当課長","answer":"登録日から２年間ということですので、それぞれの団体に応じて、２年間の更新日が来ましたら更新をしていただくといったところです。勤労者が使用する場合には、予約の段階で勤労者のお集まりの方には優先的に予約をしていただけるといった規定を設けているところです。","id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"ちょっとだけもう１つ。その辺については、まさかきゅりあんより高くならないと思いますよと想像で言っていますが、見通してとして検討はどこかでされているんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"検討は所管課のほうでやっていると思いますけれども、使用料の算定にあたりましては、それは基本的に考えているです。個別の料金につきましては、検討しまして、しかるべき時期に議会のほうにご報告をするという形です。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"使用料の単価というのはそれぞれの施設によって違うかどうかということもお伺いしたいと思います。改めてお伺いしたいんですけれども、その原因があれば教えていただきたいのと、普通の集会所という感じの施設なんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"りんし２１につきましては、委員おっしゃいますように、普通の集会所としてご利用いただいているです。場所的にも不便な場所ということもありますので、なかなか利用がされないといった状況があるのかなと推測しています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"各企業とか、認定団体とか、利用のうちどういう団体がどの部分をどれぐらい占めているのかというのを数字でつかんでいらっしゃいますでしょうか。団体の種類ごとに、大体どれぐらい利用されているとか、そういったことを出していただくことは可能かどうかお伺いします。","respondent":"久保田行財政改革担当課長","answer":"ただ使うにあたりまして、私どもの使用の不承認といったものが条例の第４条で規定があります。不特定多数の方を集めて製品の説明会をやるとか、区民ですので、お貸し出しをしています。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"考え方はわかりましたけれども、実際に企業の皆さんがどれくらい使用されているか。特に大崎第１地域センターとかですと、周りに会社も多いとか、そういったことはつかんでいらっしゃるかという後段の質問はいかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"ただ数字としてそういうものが抽出できるかということは、所管のほうに確認しないとなかなかお答えできないなです。後ほどまた正副委員長のほうにご相談をさせていただきたいと思います。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"どういう経緯で現在のようになったのか教えていただきたいのと、そういう基準や考え方があるのかどうか、あれば内容を教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"本日ご説明しましたように、児童センターとか、地域の方のそういった地域福祉のための振興に役立てていきたいです。私どもの地域センターと集会所等を設けるために、それぞれの地域のほうのこれまでの経過の中で現在の配置になっているといった状況です。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のこれまでの経過の中でというところだったんですけれども、基準というとあまりにもかちっとし過ぎているのでお答えづらいと思うんです。考え方という形でいいので、そういった集会所施設の配置の考え方をもう１度お伺いしたいのと、もう少し教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"品川区は今、地域センターの管轄ということで１３の管轄に分けてありますので、細かく１３の地域に分けてそういったものを設けてきたです。東西に長いとかいろいろありますので、全体的に地域バランスを考えながら、１３の地域に集会所を配置してきたという経過です。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"料金の考え方と、あとりんし２１についてお伺いしたいと思います。それから先ほども話題に出ましたりんし２１、企画を中心に今後どのような活用策をとっていくかということで、その辺のことをお伺いしたいと思います。","respondent":"金子企画財政課長、久保田行財政改革担当課長","answer":"大企業というよりは中小企業が使っている例が多いということから、区民集会所の実態もかなりそういう傾向が強いのではないかと考えています。特に大企業等の利用が増えてくるとか、そういったことがあれば別ですけれども… りんし２１についてですけれども、りんし２１につきましては、いろいろな検討が必要だというところでは考えているところです。ただ、現に約５％の利用率でもお使いになっていただいている方がいますので…","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"りんし２１はいろいろ難しい問題があると思うので、検討しているのであれば検討しているときちんと答弁すべきであったのではないかと。きちんと質問のあったことについては、ご検討していることはいいことなわけですから、きちんとおっしゃってほしいと求めました。","respondent":"日下部企画部長","answer":"りんし２１の件ですけれども、りんし２１の利用実績がどうして低いのかというご質問でございましたので、ああいう形でのご答弁をさせていただいた。ただその後、阿部委員のほうから今のような形で具体的な検討についてどう進めているのかというご質問がありましたので。","id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"その２つの間を埋める発想がどうもわかりにくかったと思いますけれども、先ほどのご質問の中で、なぜ低いのかということが。だから駅から遠いというだけのご答弁では十分ではなかったのではないかと言わせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これもやはり自民党内でも大分議論になって要望してという経緯もあった中で、個々のケースでもわりと大きな施設にはそういうのがありがちかなと。グラウンド等でも、そういった施設では多数お声を自分なんかも把握しているつもりなので、その辺の利用率と予約に対する考え方を伺えればと思います。","respondent":"久保田行財政改革担当課長","answer":"２カ月前から予定を決めてお使いいただくという方ばかりではございませんので、何らかの形で集会所をお使いいただけるのかなと考えているところです。例えば集会所はだめだけれども、広くご案内をさせていただいて、できるだけ多くの方にお使いいただけるように努力をしています。","id":"exchange-015"},{"speaker":"山内委員","kind":"質問","question":"ここで質問なんですが、この一覧を見ますと、年間大体幾らぐらいの利用料金があがったのかということが記載されていないんですね。金額的なことが記載されない何か理由があるのか、その辺をお尋ねしたいんですが。","respondent":"金子企画財政課長","answer":"使用料全体としましては、４億９,６００万円、約５億円ですね。こういうのが平成１９年度実績の数字としています。","id":"exchange-016"},{"speaker":"山内委員","kind":"意見","question":"そうじゃなくて、だったら各施設で年間幾らぐらいの利用料があがったんですよということを記載してもいいはずなんですね。それが何でできないのかということを私は今聞いているんですけれどもとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"本日は施設の概要ということで、こういった形で資料をお示しさせていただいているところですので、今後またそういうご要望がございましたら、正副委員長のほうと調整させていただいて、資料としてご提供していきたいと考えているところです。","id":"exchange-017"},{"speaker":"山内委員","kind":"質問・要望","question":"利用率、それから人数的な部分で、ここをどう変えていったらいいかということも大事だとは思うんですが、あがって何ぼの世界だと思うんですね。これは要望になりますけれども、一つ一つの施設で大体幾らあがっているのかということを、ちゃんと明確にしていただきたいなという要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"中塚委員","kind":"意見","question":"先ほど料金の話が出ていましたけれども、一方で予約をして料金を支払って取り消す場合というのがあるんですね。いわゆる取り消しだったり、払い戻しであったり、この仕組みがどうなっているのか、ご説明いただけますかとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"直接それぞれの施設に申し込みますので、その使用の申請の際に使用料をお支払いいただいて、７日前までに取りやめた場合には５割お返しをしています。こちらにつきましては、使用日の２日前までに取りやめた場合には、５割返還という規定をさせていただいているところです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろなサークルの方法があって、次の日でもまた５割返還になってしまって、どうも利便が悪いなという話もよく伺うんですね。伺いたいのは、どういった利用要望が多いのか、どのように把握しているのか教えていただきたい。","respondent":"久保田行財政改革担当課長","answer":"その規定に基づいて、利用するにあたりまして、申し込みされるときに間違いのないようにご利用いただくような形でお願いをしています。例えばその後７日以内にお支払いがない場合は、できるだけむだのないように…","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"その利用実態や利用目的、また区民要望、こうしたものの把握というのはどのように行っていらっしゃるのかを教えていただきたい。荏原区民センターのレクホールは年間だと９５％か尋ねました。","respondent":"久保田行財政改革担当課長","answer":"そこに例えば利用要望等があればご記入いただくような形で工夫をしている施設等もありますので、そういった中で利用状況を把握しています。推測するに、何か運動的なものでお使いいただいているのかなという形では推測してはいますけれども、詳細については把握していないです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際、ぜひそういう利用実態や利用目的に合わせて区民要望を吸い上げていただいて、そのつなげるところをどのようにお考えなのか教えていただきたい。そういうのもよく伺うんですけれども、そこはどうお考えなのか、最後に説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"今、そういったダンスができるようなスタジオ等の整備というものを行われるという予定になってありますので、数的にはそういったところの。制約はありますけれども、制約がある中で申しわけないんですけれども…","id":"exchange-022"},{"speaker":"市川委員","kind":"質問","question":"２点ほど伺いたいんですが、その辺のことをどのように考えるのかお聞きしたいのが１点と、使われない日もあるのかなと。そういうときの管理というか、受け付けの業務とか、その辺はどういう形でやられているのか、その２点をお聞きしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"これは政策的な区の考え方ということで聞いておりますので、そういった集会所はお使いいただけないかなという話を聞いているところです。シルバーセンター、目的外利用がない場合には施設を閉じているですので、目的外利用がないときには施設は閉じられていると伺っております。","id":"exchange-023"},{"speaker":"市川委員","kind":"質問","question":"かなり使わないで人を配置したりしなかったりというのは、その辺のところで行き違いとかで使えなかったりということはないんでしょうか。なかなか難しい管理の仕方だなと思いますので、ちょっとそこだけ説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"そういった例えば申し込んだのにシルバー人材センターの人が来なくて使えなかったといったことがないようには努力していると聞いておりますが、万が一そういうことが起きても、臨機応変に対応できるようにはしていると所管のほうから伺っているところです。","id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"集まりができないというときに、やむを得ず借りるということがあったものですから、長年訴えてきました。しかしこの実績を見ると結構な数字ですから、やはり和室というのはこの日本社会の中で必要なんだなと。","respondent":"久保田行財政改革担当課長","answer":"和室ですけれども、一定程度、例えば各集会所であれば、各施設に１つは和室というものを設けてあります。和室のほうが使いやすいといった声も聞いておりますので、そういう中では一定程度和室というものが必要なのかなと考えているところです。","id":"exchange-025"},{"speaker":"須藤委員","kind":"質問","question":"それを出さないで１０月だけで年間はこっちですよというので出して、見てくださいと言われても、いろいろな調整ができない。我々が見ているのは、その辺は何か説明があって１０月だけというふうにとられたのか、説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"１０月というものは平均的な数値になるのかなというところで、９月、１０月を選ばせていただいたです。委員からご指摘いただきましたように、各所管のほうとも調整をして、できるだけ精緻な集計ができるように努力していきたいと考えております。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"土・日はどうなんだというのがきちんととらえられるような、今後どういうふうにやって、説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"１０月というところで利用実績をとっているところを見ますと、平成２０年度のところでも数値の集計というのはできるのかなとは思っているところですが、お答えできるようにしていきたいと考えています。","id":"exchange-027"},{"speaker":"須藤委員","kind":"質問・要望","question":"質問されて、土・日・平日はどうなっているんですかと。やはり全体を比較するなら全体を比較した数字で出していただきたいと、正副委員長にお願いをしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"若林委員","kind":"確認","question":"日にちを違えて同じ第１集会室とか、それを確認させていただいて、要するにお金の入るところは全部会計に入ってくるわけですよね。はりんし２１、また条例的に大変大きな壁があるということがあれば、１つ参考にお聞きしたいと思います。","respondent":"日下部企画部長、久保田行財政改革担当課長","answer":"区有施設につきましては、確かにご指摘にありましたように、数年前に１度、行革委員会でご検討いただいた経緯があります。その検討に当たっての一番土台になりますのは、改めてその辺はご提出をするということで… 今後、またどういった手法ができるのかとかというのも、私どものほうでも検討をしていきたいなとは考えております。りんし２１の関係ですけれども、もしこちらを変更するということであれば…","id":"exchange-029"},{"speaker":"阿部委員","kind":"意見","question":"その変え先が空いていれば、例えば変更手数料みたいなものを取りながらとか、いろいろやり方はあると思います。先ほどご答弁の中で、キャンセル以外に変更という考え方も取り入れながら規則を見直すということもあってもいいのかなと、これは意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういうところをぜひ利用者の利便に立って、柔軟に対応していただきたいなと思いますので、これも意見だけで結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"もしあるのであれば教えていただきたいんですが。電話とまた窓口に来てくださいということで。","respondent":"久保田行財政改革担当課長","answer":"これは所管のほうに確認をしまして、後ほどお答えをしたいと思いますので、よろしくお願いいたします。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/592995?Template=document&Id=5870#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":34481,"voices":71}},{"id":"h21-20090929-15","meetingId":"h21-cm09","date":"2009年9月29日","dateIso":"2009-09-29","committee":"環境対策特別委員会","time":"午前１０時０３分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/485957?Template=document&Id=6174#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":1210,"voices":8}},{"id":"h21-20090930-4","meetingId":"h21-c-settlement","date":"2009年9月30日","dateIso":"2009-09-30","committee":"決算特別委員会","time":"午前１０時０２分～午後６時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を141件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山元副委員長","kind":"質問・要望","question":"経過時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても直ちに取りやめていただきます。第６項、５階の理事者控室に当委員会の模様を放送いたしますので、そちらでお聞きいただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"議員活動をする際には必ずつけておくのが決まりだと思うんですけれども、そのあたりは、今までどおりの考え方でいいわけですね。つけていない方がいらっしゃると思うんですけれども、そのあたりはどうふうに手配していくんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問・要望","question":"記章についても、その時に委員会では義務づけをしないということが、議会運営委員会での議論で確認されているというふうに聞いております。ですから、これまでずっとそういう対応でやってきているんですけれども、突然、そういう対応をしようということは、ちょっと無理がある。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"須藤委員","kind":"質問・要望","question":"議員活動をするときには記章はつけるということで、申し合わせ確認事項ではないけれども、議会運営委員会でそういう議論もさせてもらった。そういうことをきちんとやっていただきたいというお話をして、そのように徹底しますということですから、それで結構だと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういう申し合わせ確認事項だけではなくて、議会運営委員会での議論の経過をしっかり確認させてほしいと求めましたので、委員長。この間の議会運営委員会の議論の経過と確認があるはずですから、ここのところの確認をお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"そのときに、どうするんですか、いいですという話で私は、流れたような、そのときの話し合いが決まったようなことを記憶しております。でも、これは別ですから、そこまでちゃんとやるならば、私は、議会運営委員会でしっかり議会全体のことを決めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問・要望","question":"こういう問題を、一つの委員会で結論を出すということは、そういう拙速なやり方はやめてほしいと求めました。委員長が、この決算特別委員会での結論ということで結論を出すような拙速なやり方はやめていただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問・要望","question":"先ほど来、言っているように、この間の議会運営委員会での議論の経過、結果、確認内容をしっかり踏まえた上でやるというふうにしていただきたい。当然いるわけですから、このまま今の委員長のまとめ、方向性でいいとはいきません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"}]},{"id":"topic-02","title":"以上で決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２０年度品川区一般会計歳入歳出決算","agenda":"以上で決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２０年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"鈴木委員","kind":"確認","question":"ご説明をいただきました平成２０年度財政健全化判断比率の件について、ちょっと確認だけしたいんですが、内容的にも理解はしているつもりです。その辺の考え方としては、どうなんか尋ねました。","respondent":"金子企画財政課長","answer":"理解しづらい部分がありますので、私どもとしましては、参考までに算出比率を載せてあります。傾向を判断するためには、もし必要であれば、様式についても何らかの工夫をしていくということも検討していきたいと考えています。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これが、１月から３月いっぱいということですから、期間が短かった中で、どの程度効果があらわせたのか。それからもう一つは、平成２０年度全体のこの決算のポイントは、どの辺にあるのかということについて、お答えほしいと求めました。","respondent":"金子企画財政課長","answer":"平成２０年度中につきましては、各事業、延べ１３０件の事業があったわけですけれども、すべての事業について実施しております。先ほどの緊急経済対策を実施することによりまして、区民生活の維持・安定、それなりの成果を上げられたと考えているところです。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"いろいろ質問も出てまいりましたが、これから平成２２年度の予算を組んでいく中で、ひとつお願いをしたいと思います。その中で、多少、基金の取り崩しというのは、どういう判断をした上で、基金の取り崩しを考えていくのか、その辺もお答えほしいと求めました。","respondent":"金子企画財政課長","answer":"当初から予定している部分もありますが、区民生活を維持するために、ある一定の基金の取り崩しも検討していかなければならないと考えています。さらに一層の努力を全庁的に重ねまして、財政的にも、財政基盤の安定化にも努力していきたいと考えているところです。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"意見","question":"たしか歳入総額のおのおの３０％近くを占めているので、これから大変厳しい状況にもなると思いますので、その辺もよろしくお願いしたいと思います。それとも、毎年ほとんど変わらないのか、その辺をお願いいたしますとの意見を述べました。","respondent":"金子企画財政課長","answer":"委員のご案内のとおり、都道府県の事務が市区町村に移譲されて、その部分の配分金ということになります。最近の動向を見ますと、委員ご指摘の部分もありますが、若干ずつ増えているというのが、最近の傾向です。","id":"exchange-012"},{"speaker":"浅野委員","kind":"提案","question":"この３,０００件の予算を立てるときに、平成２０年の状況が、ある程度反映されているのかどうか、お伺いします。住民基本台帳カード発行料を免除するという提案をさせていただきまして、平成２１年度の今までの分がわかれば、それぞれお願いいたしますとの意見を述べました。","respondent":"梶戸籍住民課長、久保田都市環境事業部長","answer":"ちなみに、平成１９年度が３,１６０件となっておりますので、順調に増えているところです。今年度に入りまして、４月以降なんですけれども、８月３１日現在、また１,３０８件ほど伸びてありますので、順調に伸びているところです。 免許証返納に伴う住民基本台帳カード交付の状況ですけれども、平成２０年度は２４９人ございました。平成２１年度は、今、調べていますので、ちょっとお待ちいただきたいと思います。","id":"exchange-013"},{"speaker":"浅野委員","kind":"確認","question":"１件１,０００円ということと、申請と受領で２回区役所に足を運ぶことが基本となっていると、ホームページで確認しました。私も、相談で、もっと手軽に発行してもらいたいという声も聞いておりますけれども、本区の見解についてお伺いします。","respondent":"梶戸籍住民課長","answer":"他自治体におきましては、５００円というところが多うありますので、発行枚数等によりまして、それはまた今後の検討かなと考えております。そういう悪意の発行等がないような形でできるか、そういった点を検討しながら、今後とも検討していきたいと考えております。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"それは広域連合の話ですからということで、すぐに足を運べない方もいらっしゃるということを考えると、もう少しサービスの向上に努めたらどうかなと。それができ上がったらまた地域センターに配送して、本人確認をするとか、そういうことも考えられます。","respondent":"梶戸籍住民課長、諸石交通安全担当課長","answer":"申込みのときに、ご本人の確認等をさせていただいて、その次の回にお渡しするという形になってあります。ただ、地域センターでも受け付けできないかという方につきましては… エコライフ支援制度における住民基本台帳カードの申請状況ですが、そのうち２１３名が、住民基本台帳カードをご希望になっております。パーセンテージにして８３％ということで、平成２０年度より…","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"私は、成果報告書９３ページ、都支出金、教育費に関連して何点か伺いたいと思います。そういうところの考え方がどういうふうになるのか、聞きたいと思います。","respondent":"富田学務課長","answer":"国で行っておりますいわゆる４０人までを１学級の定員とするという内容に何ら変わりがあるものではございませんので、教員の給与等々についても、特段の扱い等々ということは全くございません。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、実際に、トータルで国の基準よりも多く教員を配置したのかどうなのか。例えば配置したとなると、その人件費は区が負担したのかということは、どうなんか尋ねました。","respondent":"冠木指導課長","answer":"品川区におきましては、国の標準法による基準どおりの教員配置をしています。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、昨年も、例えば大間窪小学校、戸越小学校等、２クラスということなので、１クラス３０人ということになるわけですよね。それが何人ぐらいあって、その人件費は東京都が持っているのか、どうなのかということを聞いたんです。","respondent":"富田学務課長","answer":"今年の４月の新入学に当たりまして、例えば６０人とした学校につきましても、実際にはそれを上回って入学している学校は多くあります。ということで、先ほど、指導課長が申し上げましたとおり、そのための教員の経費を、特段に別途必要とするということはございません。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"新年度は、そういう見通しはどういうふうになるんでしょうか。それでも増える見通しがない、増えないでもやりくりできるということなんか尋ねました。","respondent":"富田学務課長","answer":"今年の４月と来年の４月と、それぞれの学校ごとに、受け入れできる学級数というものがあります。中学校であれば３年間の間に、来年４月に向けても、従前と変わるところはございません。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"確認","question":"そういうことを確認しておきたい。１クラス３５人と、転入を考えて５人余裕を持っていますという説明なんですけれども、教員の配置はいくんだということなのか尋ねました。","respondent":"富田学務課長","answer":"東京都には、適切に学級編成の予定、また結果等々の届出をしており、それに基づき、東京都より教員配置がされております。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"決算なんですから、ちょっと答弁をお願いしたいと思います。１クラス、いわゆる４０人よりも少ない定員でやったんですけれども、どういうふうに受けとめていらっしゃるのか尋ねました。","respondent":"富田学務課長","answer":"区の教育委員会といたしましては、東京都に次年度の学級編成の予定というものを、学校ごとのクラス数を届け出しております。それに基づきまして、東京都は教員配置をしているものであり、これに全く変更はございません。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"それとも、２クラス６０人でも、これは東京都のほうの基準に合っているんでしょうか。少なくとも東京都は、今まで、１クラス４０人と変えていなかったと思うんですけれども、どうなんか尋ねました。","respondent":"富田学務課長","answer":"学校選択というもののご理解をどうされているのかわかりませんけれども、従前よりの学校ごとの通学区域というものは、現在も生きております。したがいまして、希望申請をしていただくといったようなことを行っていますものであり、従前より大きく変わるものは全くございません。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問・要望","question":"４０人という枠から少なくしている、しっかりと少人数学級の実施を求めるべきではないかと思うんですけれども、そこのところの考え方をお伺いしたい。ですから、３人の受入れ枠しかないということになると、そこの考え方はどういうふうにやってきたのか尋ねました。","respondent":"冠木指導課長、富田学務課長","answer":"そのような議論があったという情報も入ってありますので、今後の国の動向等を注視しつつ、東京都教育委員会とも調整をしてまいりたいと考えています。後半については、学務課長より答弁申し上げます。 受入れ可能学級数ごとに定めをしているものでありまして、受入れ可能学級数が、１学級の学校につきましては３５人です。１８０人ですので、２０人の転入生、転居者の想定をしても大丈夫ということで決めたものです。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問・要望","question":"少人数学級を求める声、一刻も早く、この制度を東京都全体で導入するというふうにしていただきたい。品川区も、これが先鞭となればいいなと考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"稲川委員","kind":"質問","question":"これはちょっと私もどう質問していいかわからないんですが、９０ページの国庫補助金、土木費補助金についてお伺いしたいと思います。８１ページ、その意味も教えてもらいたいんですが、なぜ単位がばらばらになっているのか。","respondent":"小野土木管理課長","answer":"それから、公園の占用については、それが１本という単位で課しておりますので、この辺の違いが出てきております。それに対しての料金を取るという形になっております。","id":"exchange-025"},{"speaker":"稲川委員","kind":"質問","question":"ロケーション、ほかの委員も以前に質問したと思うんですが、４４９万２,８８８円ということなんですが、これは、どういう算出で出したんですか。一瞬そこだけを使うカットがあると思うんですが、そういうのはどういう割合で入っているのか、説明を求めました。","respondent":"小野土木管理課長","answer":"例えば電柱１本なら何平米だとか、例えばここで電柱だとか、電らんだとかということについては単価を決めてまいります。ロケーションの場合は、各スチール写真だったら幾らだとか、フィルムだったら幾らだとか、こういうふうな形で定めているものです。","id":"exchange-026"},{"speaker":"稲川委員","kind":"質問","question":"撮影現場として出たり、さまざまな部分があると思うんですよ、一部だけ。そういうのは、ここでわかることなんか尋ねました。","respondent":"齋藤道路公園課長","answer":"したがいまして、どんなドラマをやるかは、把握しております。どんな写真撮影をするかも、把握しております。","id":"exchange-027"},{"speaker":"稲川委員","kind":"質問","question":"商業・観光課長にお伺いをしたときに、何が必要かと言ったときに、そういったフィルムコンテンツって非常に必要になってくると思うんですよ。ある意味、資源として必要なのではないかなと思って、部署と部署の間はどういう連絡になっているものなのか。","respondent":"齋藤道路公園課長","answer":"ＮＨＫのこういうもの、フジテレビのこういうドラマの１カット、あるいは女性誌などの雑誌のスチール撮影という形で来ます。認めないの判断をするだけでございまして、商業・観光課のほうへ、こういう撮影があるからということでご案内するといったことはしておりません。","id":"exchange-028"},{"speaker":"稲川委員","kind":"質問","question":"私は、したほうがいいのではないかなと思います。次に９０ページにある国庫補助金、何をもとに額が決められているのか、お願いします。","respondent":"吉川防災整備担当課長","answer":"例えば、密集住宅市街地総合整備事業の国庫補助基本額というのは、補助対象となる経費と考えていただければと思います。例えば工事費、それから用地費等のことを指しております。","id":"exchange-029"},{"speaker":"稲川委員","kind":"質問","question":"それが基本額になるんですか。これ自体は、どこが決めてくるのか、国が決めてくるのか、それとも、区が国の制度にのっとって、こういう事業をやりますからという中なのか。","respondent":"金子企画財政課長","answer":"これら国の補助に関しましては、国のほうで要綱を定めておりまして、その中で、さまざまな基準について項目を立てて、単価も設定しているです。","id":"exchange-030"},{"speaker":"原委員","kind":"意見","question":"８１ページ、ほかの区と比べてどうなのかという、その辺なんです。もし違いがあれば、特性とか、特徴とかあれば、お教えほしいと求めました。","respondent":"柏原住宅担当課長","answer":"区民住宅の考え方です。そういった方たちに入っていただくための制度ということで、区民住宅ということで設置、管理をしています。","id":"exchange-031"},{"speaker":"原委員","kind":"意見","question":"３年間見ても、プラス、プラスという形になっているんです。７５８戸、今後どういうふうになっていくのか、その辺のところもお教えほしいと求めました。","respondent":"柏原住宅担当課長","answer":"建設型をあわせまして１,０５６戸ということで、今後広げていくというような考えは、ございません。４３９戸ということで、一定程度効果を上げていると考えていますので、これから云々というところではないと考えています。","id":"exchange-032"},{"speaker":"原委員","kind":"質問・要望","question":"４２、４３ページを見ていきますと、残っていってしまうところの取り扱い。どこかで処理とか、何か考えがおありでしたら、お教えほしいと求めました。","respondent":"柏原住宅担当課長","answer":"ただ、私ども、例えば指定管理者も含めて、お支払いいただくように、収納していただくように努力しています。そういうことも考えますと、退去も含めてお話をするということで、強い姿勢で臨んでいきたいと思っているところです。","id":"exchange-033"},{"speaker":"原委員","kind":"質問・要望","question":"ただ、頑張っているからいいというものではなくて、１００％が目標というか、当然という形なので、ご努力を続けてほしいと求めました。要するにタイプ別の問題、それぞれの世帯数関係の個別のことについて、将来的な考えをお聞かせほしいと求めました。","respondent":"柏原住宅担当課長","answer":"今、工夫といいますか、検討しています。こういった方であれば入れるのではないかというようなところも、もう少し突っ込んだ形で、今、検討しております。","id":"exchange-034"},{"speaker":"金野委員","kind":"質問","question":"この交付金はどのようなものなのか、まずそこを１点目、具体的にお聞きしたいと思います。それから、入園者数から見て、これを受けた方の割合はどのぐらいだったのかという点を、お願いいたします。","respondent":"金子企画財政課長、吉岡保育課長","answer":"道路のカーブミラーといったものにつきまして、その設置、管理に要する費用に充てるものとなっております。本来、一般財源ですので、フリーに使えるという部類に入っていますが… 金額自体が、その対象となるご家庭の所得によって変更がありますので、その辺で若干の増減が出るものと考えおります。それから、割合につきましては、対象につきましては、おおよそですけれども、全園児に対しまして…","id":"exchange-035"},{"speaker":"金野委員","kind":"質問","question":"１００.８％となっておりますけれども、このような決算額になるのでしょうか、教えてください。こうした中で６割というのは、あるいは補助金を、どのように見ていきますか尋ねました。","respondent":"金子企画財政課長、吉岡保育課長","answer":"全体の枠が、交通反則金の総額になりますので、これの変動があるということが一つあります。あるいは、道路の改良がどのぐらい進んでいるのか、こういったものを係数化して算定するという構造になっております。 それなりのご苦労をされているものと考えていますので、今後、できるだけのご援助をさせていただきたいと考えているところです。","id":"exchange-036"},{"speaker":"金野委員","kind":"質問・要望","question":"信号機は、警視庁のほうと思いますが、品川区でも設置できるものなのでしょうか。毎年、アップしていただくように、区のほうでも働きかけていただきたいと要望いたします。","respondent":"諸石交通安全担当課長","answer":"したがいまして、交通管理者である警察のほうが、信号機は設置するということで、区のほうでは設置することはできません。カーブミラーにつきましては、道路管理者である区が設置することができます。","id":"exchange-037"},{"speaker":"金野委員","kind":"質問","question":"先ほども申しましたが、交通安全対策の交通安全というところでは、歳出のほうでもまた質問をする予告をしますが、品川区の道路交通安全というところで、しっかりお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"渡部委員","kind":"質問・要望","question":"当然、税制優遇があるわけですから、ふるさと納税の範疇に入って、区民の皆様は控除が受けられるわけですね。特別区税に入るべきものが、平成２０年度でどのぐらいあるのかを、わかれば教えてほしいと求めました。","respondent":"秋山協働・国際担当課長、武内税務課長","answer":"地域における社会貢献活動や公益の増進に寄与する活動を行っている団体を支援することよって、地域社会の振興を図るということを目的としております。その支援をするに当たって、そこに繰り入れるために… 昨年からふるさと納税の制度が始まりまして、私ども、住民税のほうで、確定申告を通じて寄附金の控除をされている方は１４９人でありまして、実際に、住民税の控除としては９００万円程度の金額の住民税が減になっているという制度です。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問","question":"もう一つ、今回、(1)、(2)と分かれていますけれども、聞き方を変えますが、指定寄附金の扱いは、どのような方が、どういうふうに寄付して、この指定寄附金になるのかを説明を求めました。","respondent":"金子企画財政課長","answer":"こういった分野に寄附したいというようなご指定がありまして、こういうふうな割り振り方を、今までしてきたわけであります。こちらのほうに入れていくという趣旨ですので、そういう趣旨の違いであることで、ご理解いただければと思います。","id":"exchange-040"},{"speaker":"渡部委員","kind":"確認","question":"もう１回、確認だけさせてください。私はどういうところに寄附をしたいと言った場合、こういう割り振りになるのか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"寄附の申し出があった際には、例えば、今ですと寄附の全体的な窓口は協働・国際担当のほうで受けております。障害者福祉とか社会教育のために使っていただきたいということであれば、その担当の窓口を紹介して、指定寄附金として受けているです。","id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"もしくは土地建物等を区に寄附しますというような場合は、お金に換金して寄附金として扱うのではなくて、いわゆる財産目録か何かに載せてあるのか。そのような什器物品等の寄附があった場合、どのような対応をされているのか、教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"物品の寄附等があった場合は、物品でありましても、その方の意志ということで、寄附をお受けしております。寄附の目録を総務課のほうでつくっておりますので、そちらのほうに掲載をして、そういう事務処理でやっているです。","id":"exchange-042"},{"speaker":"渡部委員","kind":"意見","question":"一つだけ、もう１点、そこのところなんですけれども、食べてなくなるようなものではなくて、結構大きな物をいただいてしまったりした場合、どういうふうになりますかとの意見を述べました。","respondent":"阿部経理課長","answer":"きちっと評価をして、寄附を受けて、所管のところの行政財産にする。その寄附された方の目的に沿うような形で使うという形になっています。","id":"exchange-043"},{"speaker":"渡部委員","kind":"確認","question":"寄附を受けた場合に、自動車何台とか書いてあるところに、ただ普通にプラス１の数字が入るだけで終わってしまうのか。いわゆる、お金には全くなっていないのかという確認だけ、すみません。","respondent":"久保田行財政改革担当課長","answer":"寄附をいただいた方につきましては、広報のほうで定期的に名前を公表しています。一定の基準額以上であれば、１０月１日の区長からの功労者表彰でも表彰しています。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"８１ページの自転車駐車場使用料について、お伺いします。なぜ全面有料化なのか、この辺をお答えください。","respondent":"諸石交通安全担当課長","answer":"駅をご利用になる方の駐輪場の設置に関しましては、鉄道事業者が独自に設置をしてもらいたいというのが、区の基本的な考え方です。平成１３年から、整備をした上で有料化していくという方針に基づいてやっておりまして、有料化整備が完了したという形になってあります。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"提案","question":"もっと発展的な考えが必要なのではないかと思って、３点、提案をするわけです。３点目においては、そういった整備も必要ではないかと思うんですが、この点はいかがか尋ねました。","respondent":"諸石交通安全担当課長","answer":"それから、啓発の関係ですけれども、現在も、さまざまな形で放置自転車について、これをやめてもらいたいという啓発活動は実施しております。駐輪場の整備を進めていくという考え方を否定するものではございませんけれども、敷地がないというところで…","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ敷地を探していただいて、快適に区内を乗り回せるようにしてほしいと求めましたが、その辺はいかがでしょうか。この辺も含めて、なぜ、定期利用をなくしていったのか、この点についてお答えください。","respondent":"久保田都市環境事業部長、諸石交通安全担当課長","answer":"非常に多くの経費もかかっているわけですから、それを利用する方に応分の負担をいただくというのは当然の考え方であろうと考えているものです。以下の質問については、担当からお話しします。 さらに利用者が減っておりまして、我々が見に行きますと、大体６割方の収容というのが現状です。今後も、各駐輪場の利用状況等をよく見させていただきまして、改善が必要なものについては…","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"長々とご答弁をいただいたんですが、なぜ定期利用がなくなったのかという点、肝心なところを答えてないんです。時間がないんです。","respondent":"諸石交通安全担当課長","answer":"では、下神明、戸越公園で定期利用をなくした理由ですけれども、これにつきましては、限られたスペースを有効に活用したいということで、一時利用のみということでやらせていただきました。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"７３ページの特別区民税について、まず３点一遍にいきますが、確認などをさせてほしいと求めました。特別徴収と普通徴収がどうなっていくのか、基本的なところを、まず確認させていただきたいと考えています。","respondent":"武内税務課長、矢部生活安全担当課長、中川原広報広聴課長","answer":"二つの企業で働いている方の対応はどうなっているのかというご質問だと思うんですけれども、毎月、原則的には納付をしていただくという形でやっております。 私のほうから、歩きたばこの過料について、ご説明します。実際に大井町駅だとか、五反田駅と同様の取り締まりは実施しているんですけれども… ホームページの公告料についてですが、この間、平成１８年度から２０年度にかけましてリニューアルに取り組みまして、一応、完成いたしました。…","id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"街歩きができる環境をつくっていただきたいという要望とともに、前の第１回定例会で要望させていただいて、簡単なコメントだけ。例えば鉄道事業者からの、ＪＲからの構内アナウンスについて協力体制については、今、検討がどうなっているか、一つ確認したい。","respondent":"武内税務課長、矢部生活安全担当課長","answer":"確定申告をされた場合、２社から給料がありますと、合計で総合課税されるわけですけれども、その際に、さまざまな控除があるわけです。もう１社のほうの税額についても特別徴収をしていただきたいという意思表示をしていただければ、本… 歩きたばこのキャンペーンにつきましては、今回、８月１９日から２１日につきまして、指定区域外の２０駅におきまして実施したところであります。今後も、計画的に、駅前の街頭キャンペーンを実施いたしまして…","id":"exchange-050"},{"speaker":"若林委員","kind":"質問・要望","question":"納税者に対してお知らせをするということはあってもいいのかなと考えていますので、要望させていただいて、一言ほしいと求めました。先ほどの要望とともに、こういうものは今すぐにでもできるかなと思っていますので、そこら辺についてのコメントをほしいと求めました。","respondent":"武内税務課長","answer":"検討の余地もあるかとは思うんですけれども、今一度検討するということで、よろしくお願いします。すぐにもう一度中身を確認して、修正方したいと思いますので、よろしくお願いします。","id":"exchange-051"},{"speaker":"井桁委員","kind":"確認","question":"そして、８１ページの５目土木使用料の中の、道路占用料の中のガス管について、お伺いいたします。８１ページのガス管の占用料ということになると思うんですけれども、確認で、区のほうと企業とでのやりとりということになるのか尋ねました。","respondent":"小野土木管理課長","answer":"これはガスの事業者が、道路管理者であります区の占用許可を受けまして、ガスを供給するために区道の中に埋設をしているガス管に対する占用料です。あるいは復旧工事につきましては、区が指導、監督をしているという関係です。","id":"exchange-052"},{"speaker":"井桁委員","kind":"意見","question":"あるガス会社を視察した際に、災害に対する高い意識であったり、幾つかの対策を見学させていただきました。何パーセントの切り換えであったりとか、工事の進捗状況などは聞いていらっしゃるのか、お願いいたしますとの意見を述べました。","respondent":"小野土木管理課長","answer":"ガス事業者のほうでも、２３区の課長会等で、これからそういう形で取り組んでいきますという説明は受けております。具体的なお話をいただいておりませんので、まだ品川区においては、そういう形での取り組みというものは進んでいないのかなと捉えております。","id":"exchange-053"},{"speaker":"井桁委員","kind":"質問","question":"企業の義務だとは思うんですけれども、品川区のほうからも、ぜひとも連携を取って行っていくということがかなり大切になってくると思うんです。事前にくい止めるという把握が必要だと思うんですけれども、そのあたり、いかがか尋ねました。","respondent":"小野土木管理課長","answer":"ちょっと説明が不足しておりまして、申しわけありませんでした。そういう点も含めて、協議がありましたら、十分に検討させていただきたいと考えております。","id":"exchange-054"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひ、今後、世代を超えて交流ができるような場所を考えていただきたいと思っています。今後のシルバーセンターのあり方というのでしょうか、そこのあたりのあり方というのを、ちょっと確認させていただけますか尋ねました。","respondent":"永尾高齢者いきがい課長","answer":"南品川のシルバーセンターにつきましては、現在、工事中ですが、来年８月に開設予定です。地域の方々の支え合いの場として、ほっとサロンを予定しておりまして、地域の町会長等に働きかけて、現在、進めているところです。","id":"exchange-055"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひ、地域の交流の場としてのシルバーセンターという位置づけを、今後、品川区としてとっていただきたいと考えています。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"藤原委員","kind":"質問","question":"７３ページ、特別区民税、１００ページ、財産貸付収入の、大崎再開発ビル株式会社ほかという、この２点を伺います。多分、平成２１年度、２２年度の、根幹である区民税は減るのではないかと思うんですけれども、まずは減るということで間違いないのか尋ねました。","respondent":"武内税務課長","answer":"委員言われるとおり、昨年秋以降、不景気ということで、平成２１年度の調定額も下がっております。ですから、そういった意味では、予断を許さないような税額になると考えております。","id":"exchange-057"},{"speaker":"藤原委員","kind":"質問","question":"個々の収入等は減っても、人口増で、税は増えてくるのではないかなという思いもあって伺ったんです。その辺については、平成２１年度、２２年度という形で予測はしていないのか尋ねました。","respondent":"武内税務課長","answer":"平成２０年度決算ということで話しますと、人口が４,５００人ほど増えておりまして、納税義務者が２,０００人ほど増えています。７００万円までの方は８.３％増、７００万円以上の方は３％増ということでありますので、税額が増えているという現状です。","id":"exchange-058"},{"speaker":"藤原委員","kind":"意見","question":"企画財政として、この辺についてどう考えていますかとの意見を述べました。","respondent":"金子企画財政課長","answer":"さまざまな施策で、品川区の人気が上がって人口がふえていく、また税収が上がっていくということは、非常に喜ばしいことだと考えています。大幅減の見込みがありますので、収入については、できる限り努力をしていきたいと思っているところです。","id":"exchange-059"},{"speaker":"藤原委員","kind":"質問","question":"午前中の説明で、財政健全化判断比率というのを説明していただきまして、品川区は、健全ですよというお話でしたけれども、他区の状況はどういうふうになっているんか尋ねました。","respondent":"金子企画財政課長","answer":"先ほど、財政健全化比率の２３区の状況ですけれども、他区もおおむね同じような傾向が強くて、若干数字の違いはありますけれども、どこも健全な財政状況であるということは聞いているところです。","id":"exchange-060"},{"speaker":"藤原委員","kind":"質問・要望","question":"区民へのサービスを十分にして、黒字に持っていくようにということを、必ずそういう思いでやってほしいと求めました。それから、次の財産貸付収入ですが、大崎の開発ビルほかとなっているんですけれども、それは具体的にどういうものなのか尋ねました。","respondent":"阿部経理課長","answer":"例えば旧総合体育館、これは今、フットサルのところに貸しております。あるいは、総合区民会館の駐車場、これはＪＲのアトレの付置義務の駐車場ですが、そういうものがここの中に入っております。","id":"exchange-061"},{"speaker":"藤原委員","kind":"質問・要望","question":"ほかとひとまとめにしないで、もっと具体的に載せるべきだと思うんです。そういう中で、貸し付けている理由は、幾つかあると思うんですけれども、明確にお答えほしいと求めました。","respondent":"阿部経理課長、金子企画財政課長","answer":"今般、再開発が始まるまでの間でも、公有財産の有効利用という観点から貸し付けているというものです。 ２３件ほどございまして、全部載せるとかなり分量を取りますので、代表的なところで収めているわけです。表記については、またわかりやすい実績調書ということで、工夫を検討してまいりたいと考えています。","id":"exchange-062"},{"speaker":"藤原委員","kind":"質問・要望","question":"やっぱり決算ですから、そういうのを知りたくて質問しているわけですから、説明のときはお願いしたいと思います。それから、やっぱり区民の財産ですから、賃貸しか方策はないのかということは、常日ごろ考えていただきたいと思っているんです。","respondent":"阿部経理課長","answer":"ですから、もう以降使わないということがはっきりしているものにつきましては、売り払いを進めております。話しましたけれども旧総合体育館とか、そういうふうに目的がはっきりしているものにつきましては、賃貸をしているという考えです。","id":"exchange-063"},{"speaker":"石田委員","kind":"質問","question":"成果報告書９０ページの国庫補助金、それから９８ページ、まとめてお伺いしたいと思います。そして、９９ページ、総合型地域スポーツクラブ設置委託金について、お伺いします。","respondent":"藤橋都市整備下水道課長、堀越文化スポーツ振興課長","answer":"国道および都道におきまして、それぞれ国、東京都が実施する電線類の地中化に対するものではございません。補助１８号線、補助１６３号線、補助２０５号線で事業をしております。 平成１９年度から３カ年、東京都のほうから委託金を受けまして、それを活用して、いろいろな普及啓発活動等の準備を進めているところです。準備を進めていただいておりますのが、発展的にクラブとしての設立に向け…","id":"exchange-064"},{"speaker":"石田委員","kind":"意見","question":"再開発とか大きい工事がある際に、その近隣の地中化等のお考えがあるのか、その点が１点。その辺の目指すところ、どういうことを総合的に地域スポーツクラブで行っていくのか、そのお考えを説明を求めました。","respondent":"青木都市開発課長、松代都市計画課長、堀越文化スポーツ振興課長","answer":"再開発等の開発に伴う電線の地中化について、お答え申し上げます。その道路の拡幅整備に当たっては地中化を進めておるんですけれども、地中化という点で… そういった意味では、補助１６３号線、補助２０５号線等々の道路で実施してまいります。次に、商店街の電線類地中化ということで、これは… 地域のスポーツ活動といたしましては、品川区のスポレクというのは大きな財産だと考えています。それは今…","id":"exchange-065"},{"speaker":"山路委員","kind":"質問","question":"１０２ページ、諸収入の東京臨海高速鉄道株式会社貸付金元利収入の１億４,０００万円の貸付金返還金に関連して、お伺いいたします。これから駐輪場、バイク駐車場を考えたらどうかと思いますが、いかがお考えか尋ねました。","respondent":"諸石交通安全担当課長","answer":"横断歩道橋の下に設置できないかというご提案ですが、国道、あるいは都道という大規模な幹線道路と感じております。総合的に判断をさせていただいて、設置をするかしないかという話になってこようかと思いますので、ご了解をいただきたいと思います。","id":"exchange-066"},{"speaker":"山路委員","kind":"質問・要望","question":"可能性を追って、調査をしていただきたいと要望しておきます。これは、区でつくっていただいたのか、あるいは下水道局か、あるいは請け負っている組合がつくったのか、お聞かせほしいと求めました。","respondent":"藤橋都市整備下水道課長","answer":"現在、なぎさ会館のところにある駐車場につきましては、鉄板と仮設の鋼材でつくっております。これは、いわゆる立会川幹線流域の浸水被害を軽減するために、下水道工事で設置したものです。","id":"exchange-067"},{"speaker":"山路委員","kind":"質問・要望","question":"区民から要望ありましたので、今後、整備を考えてほしいと求めました。臨海高速鉄道株式会社の返還金の１億４,０００万円、臨海高速鉄道の経営状況はどういうふうになっているのか、お聞かせほしいと求めました。","respondent":"松代都市計画課長","answer":"１億４,０００万円ということで、残りが３１億３,５００万円ほど残っておりまして、２１年間で返還をする予定となっています。平成１６年あたりは１３万人程度だったものが、約２０万人のご利用をいただいているというところで、さらに努めていくと聞いているところです。","id":"exchange-068"},{"speaker":"山路委員","kind":"質問・要望","question":"ところで、大井町駅のきゅりあん側に、臨海高速鉄道所有の土地がありますね。これは、今後、どういうふうに臨海高速鉄道が計画しているか、情報があったらお聞かせほしいと求めました。","respondent":"青木都市開発課長","answer":"委員のご指摘の土地は、大井銀座の前から、東口の駅前広場に通る道の横に、三角形の、現況でコインパーキングになっている土地だと思います。積極的に協力いただきまして、まちづくりのために貢献したいというように、品川区の要請に対して配慮いただいているという現状がありま…","id":"exchange-069"},{"speaker":"山路委員","kind":"質問","question":"貸付金と、また臨海高速鉄道の土地との関係で、きゅりあん周辺は、この土地を何とかすると、今後、非常ににぎやかな町の活性化につながると思うんですが、その辺について、区はどのように考えていらっしゃいますか、お伺いします。","respondent":"青木都市開発課長","answer":"委員ご指摘のとおり、大井町駅は、２０年以上前にきゅりあんの再開発がありましたけれども、それ以降、積極的なまちづくりが進んでおりません。新しい、また新たな付加価値をつけるべく、まちづくりを進めていくべきだということで考えていますので。","id":"exchange-070"},{"speaker":"渡辺委員","kind":"質問","question":"いま一度状況を伺いたいという点から、もちろん、厚生労働省の定める基準によった制度だということを踏まえた上で伺います。住宅の扶助で１８％、一番多いのが医療扶助で４８％ということで、医療扶助が多い背景を伺いたい。","respondent":"平澤生活福祉課長","answer":"前年同期ということで比べますと、おおむね１５０％ぐらいの増ということになっていると思います。保護人数が４,０００人をちょっと超えて４,２００人ほどになっておりますので、おおむね９％ぐらいの増加というところが、現在の数字です。","id":"exchange-071"},{"speaker":"渡辺委員","kind":"質問","question":"１点伺いたいのが、先ほど、高齢者の構成比が高いということの中で、ひとり暮らしの高齢者の比率などがわかれば、教えてください。今、どのような対応やサービスがあるのか、伺えればと思います。","respondent":"平澤生活福祉課長","answer":"次に、生活保護に至る前の方に対するサービスですけれども、例えば、去年の８月から行われております東京都の生活安定化事業があります。チャレンジ支援貸付事業というのがございまして、そのご子息に関しまして、塾代等を助成するといったような制度が準備されております。","id":"exchange-072"},{"speaker":"渡辺委員","kind":"質問・要望","question":"歳出のほうのページがちょうど１３４ページにもあったので関連して伺いますと、区内患者登録数が８７人とされていますが、この確認。あるいは、想定をされているのか、伺えればと思います。","respondent":"山岡健康課長、太田荏原保健センター所長","answer":"これが、品川区の場合は特に多いのか、少ないのかですけれども、特に多い、少ないという認識を持っているわけではございません。今後、啓発にも努めていく中で、十分に見守っていきたいと考えているところです。 高齢者については３０％、３５％という数字もありますので、高齢者から若い方にうつるという傾向が認められております。定期結核健診については、品川区では、国の指針に基づきまして、６５歳以上について行っております。","id":"exchange-073"},{"speaker":"渡辺委員","kind":"質問","question":"感染というものをどういうとらえ方をしたらいいかわからないんですが、あとは、どういうふうに情報を得ていったらいいのか。たまたまＣＭでインパクトが強かったもので、そういった安心を与える面と、自分でどのように認識したらいいのか、もう１回伺えればと思います。","respondent":"太田荏原保健センター所長","answer":"結核の場合は、感染しても、発病する方は一、二割と言われておりますので、感染したから、すぐにほとんどの方が発症するというわけでございません。","id":"exchange-074"},{"speaker":"井上委員","kind":"質問・要望","question":"私は、７９ページの１２款行政財産の使用料、そして決算全体について、資料などについてお伺いをしたいと思います。改めて、今後、行政評価について、どのように取り組んでいかれるのか、お伺いをしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"区役所として評価をしまして、改善すべき点とか、さらに拡大していくべき点を見極めていかなければならないと認識しています。さらに効率的な仕組みを構築していかなければならないということもありますので、引き続き検討していきたいと考えているところです。","id":"exchange-075"},{"speaker":"井上委員","kind":"質問・要望","question":"区民にとってどういうふうに感じるのかということも含めて、区民は、Ｄランクの評価をしていないというようなこともあると思います。そういった取り組みを具体的に示していただきたいと思うんですが、その辺の見解はいかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"今回、長期基本計画の中で策定する中で、将来的な課題として検討するというふうに位置づけているところです。議会の審議等に予算案をかけまして、そうした中で明らかにいたしまして、事務事業の見直し等も行っているといったところです。","id":"exchange-076"},{"speaker":"井上委員","kind":"提案","question":"その前に確認なんですが、５６ページまでが主要施策の成果報告書ということで、付属資料となっています。議員必携でうたわれているような、提出を義務づけられている成果報告書というのは、この前の部分でいいのか尋ねました。","respondent":"金子企画財政課長","answer":"ご指摘のところで、前半の主要施策の成果報告書は、本体は５６ページまでのものです。５７ページ以下につきましては、そういう意味では、これもあわせて一体として成果報告書であるというふうな性格のものです。","id":"exchange-077"},{"speaker":"井上委員","kind":"提案","question":"それは提案したいことなので、お考えをお伺いしたい。予算に合わせてどういう実績があったということを書いていただけると、２点について、お伺いをいたしますとの意見を述べました。","respondent":"金子企画財政課長","answer":"区民も含めて、よりわかりやすいように改善の指向性は持っておりますので、そういう方向で進めていきたいとは考えております。まだまだ不十分であるとすれば、その辺も、今後も検討しながら工夫していきたいと考えているところです。","id":"exchange-078"},{"speaker":"井上委員","kind":"質問・要望","question":"行政財産の企業への使用許可による収入が、どういう状況で計上されているのか、なかなか見えなかったのでお伺いしたいと思います。そして３点目は、許可基準として統一された見解があるのか、お伺いいたします。","respondent":"阿部経理課長","answer":"８点目が八潮地域センターです。それに伴いまして、公有財産の管理規則、あるいは行政財産の使用料条例等々を決めて、それに基づいて執行しているという状況です。","id":"exchange-079"},{"speaker":"井上委員","kind":"質問","question":"昨年６月に、人体への影響を示す研究が報告されて、ＷＨＯの新基準を公表したりしているわけです。先ほど伺った中で、最終的には撤去をする方向で検討してほしいと思っているわけですが、お伺いいたします。","respondent":"吉岡保育課長","answer":"直ちに今、健康被害が生じるとか、そのような認識は持っておりません。当面、すぐに直ちに撤去をするというような判断にはならないのではないかと考えているところです。","id":"exchange-080"},{"speaker":"井上委員","kind":"質問・要望","question":"施設使用許可、今回もどういったところにありますかということで、経理課長にお伺いして、それぞれのところでいろいろな聞き取りをしたわけです。区民から何らかそういう相談があった場合には、必要だと思いますけれども、その辺の見解をお伺いしたいと思います。","respondent":"阿部経理課長","answer":"先ほども答弁いたしましたけれども、行政財産の使用許可につきましては、公有財産の管理規則の中で、どういう場合に貸すかというのを決めてありますので、今後も、それにのっとって適正な貸付けをしていくという考えです。","id":"exchange-081"},{"speaker":"井上委員","kind":"質問","question":"次に、文化センターと歴史館の使用料についてなんですけれども、ちょっと簡単に大枠だけお伺いしたいと思っています。大体のざっくりとしたところなんですが、この二つの経費と、運営内容について、区はどのように評価をされているのか、その辺だけお伺いいたします。","respondent":"堀越文化スポーツ振興課長","answer":"見直し等には努めてまいりたいと思いますが、現在のところ、適正な執行体制にあると考えています。利用しておりますので、そういった文化の発展という意味からも、この施設の目的を十分に果たしていると考えているところです。","id":"exchange-082"},{"speaker":"高橋委員","kind":"確認","question":"１００ページの財産貸付収入のところの、あるいは阪急にお貸しした駐車場の件について、ちょっとお尋ねしたいんです。この中に含まれるかどうか、まず確認したいんです。","respondent":"青木都市開発課長","answer":"歳入項目といたしましては、８１ページの一番下です、使用料及び手数料の土木使用料のうちの土地建物使用料です。このうち広町はらっぱ公園の貸付けにつきましては、年額５,４００万円ほどの貸付料がそちらに入っております。","id":"exchange-083"},{"speaker":"高橋委員","kind":"質問","question":"もともとの経緯をお聞きしたところ、経理課長からお話があったように、行政財産の目的外使用という形だと思うんです。こちらは公有財産、行政財産として貸し付けていたと思うんですが、条例上等は、どのような形で適用されているのか尋ねました。","respondent":"阿部経理課長","answer":"それに基づきまして、金額を決めまして、貸しているというものです。先ほど申し上げましたけれども、行政財産の用途に支障がない場合に限って、目的外使用をやるということになっております。","id":"exchange-084"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、公有財産の貸付けの例として、先ほども幾つかあったんですが、一つの例として、そこの駐車場は、劇団四季にお貸しする形になるんですが、これも、駐車場として貸したときと、同じような形で貸し付けることになるのか尋ねました。","respondent":"阿部経理課長","answer":"普通財産にしまして、私ども経理課所管にしまして、四季に貸し出すという形をとっております。なお、この場合には、貸し出すに当たっては、財産価格審議会を経て、委員に適正な価格を協議していただいて、貸付金額を出しているというものです。","id":"exchange-085"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、普通財産で貸し付けることになるので、民法上の借地法というのでしょうか、そちらが適用されると思うんですが、それを適用することによって、行政がすぐに何かにしたいと思ったときに、なかなかできなくなるというような点があると思うんですが、その点はどうか尋ねました。","respondent":"阿部経理課長","answer":"今回の四季に貸し出すに当たりましては、１０年間経ちましたら、四季のほうから区に返還をするという形になっております。ちなみに、その場合、今、委員言われたような借地借家法の適用はないです。","id":"exchange-086"},{"speaker":"高橋委員","kind":"質問","question":"例えば１０年の間に、公共用として必要になった場合には、どうなんでしょうか。その１０年の契約というのは解除できるんか尋ねました。","respondent":"阿部経理課長","answer":"基本的には、そういうものが、１０年の間には想定されないということで、１０年間の定期借地という形にしております。今のところは、そういうことは想定されないので、１０年間の期間を限った定期借地にしているです。","id":"exchange-087"},{"speaker":"高橋委員","kind":"質問・要望","question":"議会が関与できるのはどこまでなんでしょうかと聞くのはあれですけれども、結局、どれぐらいかということになるかと思うんです。ぜひして、連絡を密にしていただきたいと思うんですが、その辺はいかがか尋ねました。","respondent":"阿部経理課長","answer":"議会の関与の件ですけれども、委員会での報告は別にいたしまして、議決する場合は決まっております。議会に議案として出すということはございませんけれども、時期に応じて委員会に報告するということは、当然のことだと考えています。","id":"exchange-088"},{"speaker":"高橋委員","kind":"質問","question":"庁内に自動販売機がたくさんありまして、区有施設にも自動販売機があるが、どれぐらいの数があるか知りたいんです。もし今、わからなかったら、どのような仕組みで業者が入っていくのか、入札等があるのか、お聞きしたいのですが。","respondent":"阿部経理課長","answer":"基本的には、例えば、設置するのは母子寡婦連合会とか、あるいは、肢体不自由者父母の会、そういう団体に設置の許可を出しております。無料で置いていただいて、実費相当分だけもらうという形になっています。","id":"exchange-089"},{"speaker":"高橋委員","kind":"質問・要望","question":"これは経済的な支援を含めてやられているとお聞きしているので、私はよろしいと思うので、支援の形で続けていってほしいと求めました。ほかに売店もそうだとお聞きしたのですが、そうか尋ねました。","respondent":"阿部経理課長","answer":"これは、職員互助会のほうに使用許可を出しておりまして、職員互助会のほうから、母子寡婦連合会に貸し出しをしているという形です。それについても、光熱費等については、ある一定額をいただいているです。","id":"exchange-090"},{"speaker":"菊地委員","kind":"質問","question":"私は、６５ページ、株式関係の交付金について、お聞きしたいと思います。７５.６％減と、その辺の理由と影響について、まずお聞かせ願いたいと思います。","respondent":"武内税務課長","answer":"この数字を見ますと、明らかに昨年の株の取引の衰退というような状況が生れているのは事実ではないかと考えております。もちろん、見てのとおり、マイナスになっておりますので、歳入としては、区としては非常に厳しい歳入状況だと考えております。","id":"exchange-091"},{"speaker":"菊地委員","kind":"質問","question":"当然計算をしていくのでしょうから、そことの情報交換とか、そうしたことは実際には行われないのでしょうかね。ちょっとその辺を、お聞きしたいと思います。","respondent":"武内税務課長","answer":"平成１９年度が２,２８７人ですから、約３８８件マイナスになっているという形です。平成１９年度は５億５,３００万円という金額ですので、それほど、平成１９年度と２０年度の差はないと言えるのかなと思います。","id":"exchange-092"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっともう少し伺いたいんですけれども、株式を売り買いして得られる利益とか、配当にかかる税金というのは、０２年までは２６％だった。やっぱり、そもそもこういうのは正していくべき中身なのではないかなと思うんですけれども、その辺もちょっとお聞きします。","respondent":"武内税務課長","answer":"平成２１年度に、３年間軽減税率を行う、これは地方税法の改正に基づいて特別区税条例を改正させていただいた。その趣旨としては、やはり株の取引の活性化という趣旨のほうで行われているということで考えております。","id":"exchange-093"},{"speaker":"菊地委員","kind":"質問","question":"これは、国全体の問題というよりも、区民生活に直結をする部分ですから、私はここに思いをはせるということが、何よりも必要だと思うんですね。もう一度、その辺の考え方をお聞きさせてください。","respondent":"武内税務課長","answer":"税収が上がる、イコール経済の活性化という視点で、特例の税率で軽減策というのはあるのかなと考えております。品川区の施策のほうで、いい施策をすれば、区民生活も安定するのではないかと考えています。","id":"exchange-094"},{"speaker":"菊地委員","kind":"質問・要望","question":"区民の暮らしに負担をかける一因になっているわけですから、このことを認識すべきだと、私は申し上げているんです。ちょっとしつこいようですけれども、もう一度やっぱりそこを、お考えを聞かせてほしいと求めました。","respondent":"武内税務課長","answer":"それによって、膨大な金額が動くことによって損をする方も、確かにいらっしゃいます。こういう証券取引を活性化させるということが、それぞれの企業の活性化につながるという視点で行われていると、私は考えております。","id":"exchange-095"},{"speaker":"菊地委員","kind":"意見","question":"地方自治体として、やっぱりこういう問題について声を挙げていくべきだと思います。終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"堺委員","kind":"質問・要望","question":"成果報告書８１ページの区営住宅使用料、時間内で何点か、確認をさせてほしいと求めました。それから区民住宅については１８件で、１８４万３,５４１円と、ご説明ほしいと求めました。","respondent":"柏原住宅担当課長","answer":"私のほうから、不納欠損、それから収入未済のほうの内訳について、ご説明いたします。やはり３％ずつ家賃が上昇するということも関連して、若干、金額が上がっているということであろうと考えております。","id":"exchange-097"},{"speaker":"堺委員","kind":"確認","question":"今年１月２０日の建設委員会でご報告いただいているようなんですが、今回、今年４月１日から行われるということを聞いているんです。それに伴って、区の住宅にどのような影響が出てくるのかということについて、ちょっと確認の意味で教えてほしいと求めました。","respondent":"柏原住宅担当課長","answer":"東京都のほうが、平成２１年度に関しましては、そういった方は家賃を上げないという方針を出しております。そういう状態で方針が出されましたので、平成２１年度につきましては、東京都の計算方式と合わせながら家賃を計算しています。","id":"exchange-098"},{"speaker":"堺委員","kind":"質問","question":"２２年度といったらいいんでしょうか、もう１回ちょっと、ご説明いただければと思うんです。この人たちについては、今の話だと、１年間延期する、据え置くという理解でいいんか尋ねました。","respondent":"柏原住宅担当課長","answer":"値上げを１年間据え置くというお話でしたので、品川区の区営住宅につきましても、１年間据え置くということにしております。品川区も同じような形で据え置きをしておりますので、そういったところにあわせながらやっていくことになろうかと考えています。","id":"exchange-099"},{"speaker":"堺委員","kind":"質問","question":"根拠法令というのですか、区営住宅というものであって、いわゆる区民住宅はその対象外ということなのでしょうか。その辺の兼ね合いも含めまして、ちょっと教えていただけますか。","respondent":"柏原住宅担当課長","answer":"家賃の区分が、新しく入る方については、平成２１年から若干の影響が出るというふうになっております。建設型は、これから入る方については、若干の影響が出てくるです。","id":"exchange-100"},{"speaker":"堺委員","kind":"質問","question":"借上型は対象外だけれども、建設型は対象になるということですか。ただし、４月１日からだから、これから入居する人が、その対象になると理解していいんか尋ねました。","respondent":"柏原住宅担当課長","answer":"平成２１年４月、実際の募集が６月に行っておりますので、そこの分から影響が出る。借上型区民住宅については対象外です。","id":"exchange-101"},{"speaker":"堺委員","kind":"意見","question":"これは平成９年に改正されましたが、あれからもう１０年経つんですが。あわせまして、あと１分しかないので申しわけないんですが、その中でご答弁いただければ幸いですとの意見を述べました。","respondent":"柏原住宅担当課長","answer":"それでも、今まで３％ずつ上がってきている状況の中ですので、家賃が上がった中で、やっぱり空き家が増えているという状況が、今出ております。区としましても、そういった中で空き家の対策であるとかは、独自にいろいろなことを考えていきたいと考えているところです。","id":"exchange-102"},{"speaker":"阿部委員","kind":"提案","question":"もっと後ということでお考えかもしれませんが、そういったことを何らの形で振り返るご予定があるかどうかということを、お伺いしたいと思います。２回区役所に来なければいけない申請手続の中で、最初の１回は…","respondent":"金子企画財政課長、梶戸籍住民課長","answer":"今年の１月に打ちましたときに、四つの柱でご説明をしているかと思います。３点目が雇用創出につながる委託事業等の新設、４点目が… １回目の申請につきましては、２回目に実際に受け取るときには、ご本人にきていただくような制度もとっております。それが１回にならないかとか、今… 一般財源ではありますけれども、品川区におきましては、リサイクル活動推進事業に充当するという形をとってあります。…","id":"exchange-103"},{"speaker":"阿部委員","kind":"提案","question":"ですから、個人情報の保護と、行政としてのコストのバランスとして非常にいいのではないかという提案をさせていただきました。それから、宝くじのほうなんですけれども、リサイクル活動に全額充てているということで、よろしいか尋ねました。","respondent":"金子企画財政課長、梶戸籍住民課長","answer":"２点の質問にお答えします。１０７億６,３６０万円が融資金額となっておりますので、相当大きな支援になってきているということは、私どもとしても承知しています。 戸籍の謄抄本の交付につきまして、年間１４万件ぐらいございまして、なかなか多うあります。その中で、そういった形で出せるかどうかというところは、ちょっと他の自治体等も調べながら検討してまいりたいと思います。","id":"exchange-104"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただ、これは大切なことだと考えていますので、また機会を改めてじっくりお話をしたいと思うんです。最後は要望になりますが、ぜひそういった視点も、今後持ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"},{"speaker":"山内委員","kind":"質問・要望","question":"１台あたり幾らというのは言えないと思うんですが、収入が上がっているのではないかと思うんですが、その辺の金額を教えてほしいと求めました。これは教育に関しての財団からの助成金だと思うんですけれども、民間から助成を受けるに当たっての経緯というのですか、どういう形でされているのか。","respondent":"富田学務課長、諸石交通安全担当課長、金子企画財政課長、吉岡保育課長","answer":"品川小学校で、ＩＴを活用した教育研究活動を展開しようという取り組みに対しまして、当該の財団より助成金があったものです。… 二つ考え方がございまして、今現在、売却ということでやっています。バイクもありますが、ちょっと長くなりますので、自転車だけでよろしいでしょう… これは、ミスプリントではございませんで、予算書の番号に対応して、番号を振っている関係で、(2)がなくなっております。… 宝くじ等助成金収入のうちのソニー教育財団助成金について、ご答弁申し上げます。…","id":"exchange-106"},{"speaker":"山内委員","kind":"質問・要望","question":"これは、その品川小学校の場合は、どういう形で申請したんですか。その申請の仕方はどういう形になっているんか尋ねました。","respondent":"富田学務課長、吉岡保育課長","answer":"松下教育研究財団のほうにつきましては、今回は、品川小学校がみずから手を挙げまして、決定をした後で、教育委員会で歳入するという形をとったものです。 それぞれの保育園で取り組みをしている幼児教育の実践を、保育課のほうでも当然承知をする中で、組織として応募しているというものです。","id":"exchange-107"},{"speaker":"山内委員","kind":"確認","question":"そうすると、ソニーのほうにお願いをするときも、もう一度確認なんですが、保育課を通じてということではなく、直接ということでよろしいんですか。もう１回。","respondent":"吉岡保育課長","answer":"当然、応募するに当たっては、組織として応募しておりますので、保育課も承知をした中で提出をしているです。","id":"exchange-108"},{"speaker":"山内委員","kind":"質問","question":"そうすると、去年、保育園、もしくは幼稚園で何件ほどの申請があったのか。それから、どんな内容なのか、最後にちょっとそれをお伺いしたい。","respondent":"吉岡保育課長","answer":"応募としては、西大井保育園、品川保育園、源氏前保育園、小山台保育園の４園という認識です。","id":"exchange-109"},{"speaker":"山内委員","kind":"質問","question":"内容的には、各４園、同じような内容での助成の申請だったのか尋ねました。","respondent":"吉岡保育課長","answer":"６年ほど前から、若干の違いはありますけれども、それぞれの園での幼児教育の取り組みという内容です。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"もう一つは、成果報告書の中の、９６ページの認定子ども園だけではないんですが、認可保育園等々の国、都の補助金との関係をお聞きしたいと思います。これはどういう関係になっていて、どのように見ていけばよろしいのか尋ねました。","respondent":"武内税務課長","answer":"決算書の３０ページの区民税の関係で説明しますと、６月に当初賦課ということで、税をかけするわけです。あるいは、当初、１０万円の金額が、税額変更にして５万円になるという場合もあるんです。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"収入済額というのは、もう入ったお金になるわけですから、そこを見ていくのか。収入済額のところで見ていけば、平成２０年度の決算という意味では、そこを見ればいいのかと思うんですが、いかがか尋ねました。","respondent":"福田会計管理者","answer":"つまり見込み予定がこうであった、実際に入ってきた、これが収入済額です。この原則は、決算書に一貫して貫かれているものです。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"認可保育園とかの設立がいろいろあると思うんですけれども、そのときの、国とか都からの補助金の考え方はどうなんでしょうか。その現状を説明を求めました。","respondent":"吉岡保育課長","answer":"東京都が４分の１の補助が入っておりますし、９６ページに記載していますように、東京都の一定の補助金が入っております。公立のものについては、ないと考えております。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問","question":"そうすると、これから公立幼稚園のところに認可保育園を、０、１、２という形で設置していくという場合には、どういう項目で補助金があるんですか。ないという形で考えていくべきなのか尋ねました。","respondent":"吉岡保育課長","answer":"ただ単に、既存の幼稚園を幼保一体施設にするとかいう場合については、補助の対象にならないと考えています。","id":"exchange-114"},{"speaker":"須貝委員","kind":"質問","question":"私は、６１ページの決算の概況と、７２ページの国庫支出金について、お伺いいたします。品川区は、実質収支を一定額確保するように支出調整をしているのか尋ねました。","respondent":"金子企画財政課長","answer":"各種の補助金が、思ったよりも入ってきた場合等々で、最終的に最終補正で調整するという部分があります。基金に積み増していくというような考え方も、結果として、こういうことです。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問","question":"今後に対して、どのような予測、把握をしているでしょうか。その辺、ご見解を説明を求めました。","respondent":"金子企画財政課長","answer":"最前から申し上げているとおり、この経済状況を反映して、非常に大きく変動する部分があります。見通しの精度を高めて、予算編成に臨んで、先ほど申し上げた目標を達成すべく努力をしていこうというのが基本的な考えです。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問・要望","question":"次に、７２ページの国庫支出金、予算現額が約１９９億円、決算額が１４１億円となっておりますが、約５８億円の差があります。これはどういうことなんか尋ねました。","respondent":"金子企画財政課長","answer":"平成２０年度の歳入で予定したものが、結果として平成２１年度の歳入になった関係で、平成２０年度としては減になっているというようなものです。結果としては、入ってきておりますので、これがまた平成２１年度のほうには、それなりの形で反映するです。","id":"exchange-117"},{"speaker":"須貝委員","kind":"意見","question":"これも約３４億円減額しております。これは、予定としては、使うべきところを使えなかったのか、次年度に回ったのか、その辺、説明を求めました。","respondent":"金子企画財政課長","answer":"先ほど申し上げましたとおり、事業の成果を上げつつ、見直しをして不用額が出てきている。あるいは、補助等の関係で、基金の取り崩しを、当初より少なくて済んだということの結果が、この反映です。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"今回、補正もそうだったのですが、緊急にいろいろ対応された。今回のこういう場合はできないのか尋ねました。","respondent":"金子企画財政課長","answer":"年度末という非常に短い期間で、一定程度、予定した事業で成果を上げている。新年度、あるいは新年度の補正の中で、さらに地域の活性化等々に予算を振り向けていくということで考えております。","id":"exchange-119"},{"speaker":"武内委員","kind":"確認","question":"一応、その事実関係を、もう１回確認させてください。その辺をもう１回、ちょっと確認させてください。","respondent":"吉岡保育課長","answer":"ご指摘がありましたように５万円ということで、源氏前保育園、それから小山台保育園の３園です。優良園が２０万円で、努力園が、１園５万円で、３園で１５万円、合わせて３５万円という助成金をいただいたです。","id":"exchange-120"},{"speaker":"武内委員","kind":"質問","question":"そうなると、金額が４５万円かなと思って、合わないと思ったのですが、それはまたで結構です。お聞きしたいのは、幼稚園に、そのままお渡しするということでよろしいのか尋ねました。","respondent":"吉岡保育課長","answer":"平成２０年度の決算でございまして、納付していただいたのが３月２７日になっておりまして、年度末ぎりぎりに頂戴したという形になっております。その分、反映していただければ、園としても大変励みになるのではないかなとは考えているところです。","id":"exchange-121"},{"speaker":"武内委員","kind":"確認","question":"金額が５０万円ということで、非常に高いんでしょうけれども、学校を挙げて、多分子どもたちも協力したりしながら、品川小学校のほうではやっている。もうちょっと検証する意味で、そういうところに振り向けられないのかなと思っているんですけれども、その辺を確認させてください。","respondent":"富田学務課長、吉岡保育課長","answer":"機器のリース料それぞれについて歳出をしているというものでございまして、品川小学校における研究発表等のリース料等々に、その歳入は充てているものです。 先ほど説明申し上げたとおりなんですけれども、デジタルカメラですとか、園の業務の中で使えるようなものをいただいております。一定、すぐに役に立つようなものをあわせていただいておりますので…","id":"exchange-122"},{"speaker":"武内委員","kind":"質問・要望","question":"毎年のように３年か４年ぐらい続けてやっているみたいなので、なるべく反映してもらえるような取り組みを、これは要望させてほしいと求めました。たまたま新聞で、渋谷区の公衆トイレの記事が出ていまして、最近の新聞なんですけれども、今年の５月ぐらいに決まったんか尋ねました。","respondent":"金子企画財政課長","answer":"最近の状況を見ますと、どうもこの経済状況の中で、ネーミングライツの利用から、企業は消極的になりつつあるということも把握しております。この件に関しては、研究しながら、そういうような機会が得られるように進めていきたいと考えているところです。","id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問","question":"私は、成果報告書の８８ページ、国庫補助金に関連してと、１０４ページの庁舎駐車場利用料に関連して質問します。どうしても区役所に来ざるを得ない時期があるわけですから、さらに発展的な対応をしていく必要があると思うんですが、ご答弁をお願いいたします。","respondent":"阿部経理課長","answer":"それについてのＰＲもしておりますけれども、また重ねてＰＲしながら、そちらの利用を図っていくということに努めてまいりたいと考えています。臨機応変の対応をするようにということで、今、申し上げたような駐車場も利用できますというような案内もするようにはしております。","id":"exchange-124"},{"speaker":"伊藤委員","kind":"質問・要望","question":"駐車場を管理している業者があるわけでしょうから、例えば満車の際には、そういうことをはっきりと取り決めしたらいかがですか。区民に割ける駐車スペースができる可能性もあるわけですから、立体的な考え方を含めての答弁を、改めてお願いいたします。","respondent":"阿部経理課長","answer":"庁有車の件ですけれども、今、総数で６０台弱ございまして、そのうち３０台分を国文学研究資料館のほうに持っていっております。区民になるべくご迷惑をかけないような駐車場の管理をしていきたいと考えていますので、ご理解のほどをよろしくお願いいたします。","id":"exchange-125"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、さまざまな区の計画があって、将来にわたって品川区の区民生活の向上を図っていくことを考えている。これは、予算特別委員会では間に合いませんので、ここではっきりとお伺いしたいと思いますが、まずいかがか尋ねました。","respondent":"金子企画財政課長","answer":"私どもも熱心に収集しているところでありますが、正式な通知、あるいはその内容の正式なものは一切きておりません。はっきりした対応は、あるいは他の大都市などとも連携して、取り組みをする必要がある場面も出てくるかなと考えているところです。","id":"exchange-126"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確かに、今の時点で、きのうか一昨日ぐらいでしょうか、すべての省庁の予算をゼロベースで検討する話も聞こえてきます。これはほんとうに２３区、地方交付税不交付団体が非常に不利になる可能性があるわけですから、いかがか尋ねました。","respondent":"金子企画財政課長","answer":"さまざまに連携をしながら、さまざまな影響について、品川区に対して非常にマイナスの影響がないような形で活動していきたいとは考えております。まずは情報収集をしながら、連携の道を探っていくというようなところが、現在の段階ではないかと考えております。","id":"exchange-127"},{"speaker":"伊藤委員","kind":"質問","question":"そういう中で、いろいろな思いを掲げながら質問しています。ですから、最後に大括りの答弁で結構なんですけれども、ご答弁計いただければと考えています。","respondent":"濱野区長","answer":"それによって政策の変更が行われる、これは当然のことだろうと思いますけれども、地方自治体の切実な願いでもあります。私どもも、これと同様の考えですし、また大都市特有の問題につきましても、区長会等で十分に議論して行動していく必要があると認識しております。","id":"exchange-128"},{"speaker":"土井委員","kind":"質問・要望","question":"ここ３年ぐらいですか、どうも国の特定財源という話と、もう１回確かめなきゃいけないなと。利息をくださいと言われないのかとか、そういう問題等があるものですから、それをお伺いしておきたいと思います。","respondent":"金子企画財政課長","answer":"そういったものはほとんどありませんが、やはりそういう意味では、そういった法人から入ってくるという部分の一つであるということが言えます。多くは概算払いという形で区のほうにまいりまして、翌年度精算をするということで…","id":"exchange-129"},{"speaker":"土井委員","kind":"質問","question":"もう１回、どうしてこの費目だけにこれが多いのかというと、そのほかのところは後渡しということで理解してよろしいのでしょうか。これが一番わからなかったんですけれども、これはだれが払ったお金がどこにあって、それからいただけるんですかというのが全くわからないんです。","respondent":"金子企画財政課長、福田会計管理者","answer":"これも先ほどちょっとご説明したとおりなんですけれども、継続して行われているものが多いですから、当然。それが最終的には、総務省のほうから、私どものほうへ交付金という形で交付をされるという形になっております。 それから「小中一貫教育理科－創造－」、「市民科、漢字ステージ１００」であります。それぞれ財産収入として、額は少のうありますけれども、収入されているというものです。","id":"exchange-130"},{"speaker":"土井委員","kind":"質問・要望","question":"委託金は全部国がやるべきもの、一般的に補助ですから、そうでない大きいものが入ったわけですよね。これからこんなものが出てくるかどうかわかりませんけれども、ちゃんとやるべきではないかと思いますので、お願いをしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-131"},{"speaker":"中塚委員","kind":"質問・要望","question":"７６ページの特別区財政調整交付金について、伺いたいと思います。品川区の積立基金の関係で伺ったんですけれども、まず数字のほうを教えていただきたいのは、算定時の品川区職員定数を教えてほしいと求めました。","respondent":"榎本人事課長、金子企画財政課長","answer":"財政調整交付金の算定人員ですけれども、平成２０年４月が２,９１２名です。実際の区の職員の現員数が２,５８０人、比べるのは２,６２２人と、財政調整交付金の算定の２,９１２名を比べるという形で比較をしております。 あるいは事業費のトータルという数字は、ちょっと持っておりませんので、ご容赦いただきたいと思います。","id":"exchange-132"},{"speaker":"中塚委員","kind":"質問","question":"決算額４１２億円の財政調整交付金、よく主なものを伺いますと、人件費だ、事業費だという話を伺うので、どのぐらいの割合なのかなと思ったんです。基金の関係で、区の主体的な取り組みがどういう形なのか、ご説明いただけますか。","respondent":"金子企画財政課長","answer":"基金と財政調整交付金との関係というお話でありますが、委員、ご指摘のとおり、平成２０年度末では７４３億円ほどたまっております。学校等の改築等々を進めておりますが、今後の財政運営を安定化させようと考えている中で、このような額で積み立てたものです。","id":"exchange-133"},{"speaker":"中塚委員","kind":"質問・要望","question":"どうして金がたまるのかという仕組みが、それがなぜ、その仕組みをご説明ほしいと求めました。そう例えてお話し伺いますけれども、その差となっている３００人、どの事業が大きなウエートを占めているのか。","respondent":"榎本人事課長、金子企画財政課長","answer":"土木費が２３７名、教育費が４０６名という形で、あわせて２,９１２名です。大体、１５％から１３％ぐらいの差が大きくなっているというものです。 そういったところは、その趣旨どおり積み立てていくということもやっております、ということをつけ加えします。","id":"exchange-134"},{"speaker":"中塚委員","kind":"質問・要望","question":"３分の１に当たるわけですから、そのウエートが多い事業がどうなのか、教えていただきたい。ここがどのような関係があるのか、これまでの説明だと、その関係が見えてこないので、その仕組みを教えていただけますか。","respondent":"榎本人事課長","answer":"品川区の場合には、給食調理は給食調理代行ということで、職員を置いておりませんので、その分だけで、７８人の差が出るという形です。ですから、１０７人のうち７８人は、そういうところから生み出してきていると考えているものです。","id":"exchange-135"},{"speaker":"中塚委員","kind":"質問・要望","question":"一緒にもう一つ伺いたいのは、お金の流れを逆から見ますと、平成２０年度決算で、新たな基金の積み増し額というのは１０８億８,０００万円なんです。逆から伺ったんですけれども、歳入の財調との関係で、行財政改革の仕組みをご説明いただけますか。","respondent":"金子企画財政課長","answer":"基金の積立ということで、少し詳しくご説明させていただければと思います。先ほどから、ご質問いただいております、二十何億円という数字というお話がありますけれども、その件については、直接関係はございません。","id":"exchange-136"},{"speaker":"中塚委員","kind":"質問・要望","question":"義務教育だ、いろいろが原資だというお話はありましたけれども、そこの原資はどこから生れてくるのかというのをお伺いしたいと思います。そのお金がたまる仕組みが、入口が見えてこないので、ぜひご説明ほしいと求めました。","respondent":"金子企画財政課長","answer":"繰り返しの説明になってしまう部分が多いので、先ほど申しました以外にも、一般財源から充当していく部分はあります。そういう意味では、先ほど、申し上げました契約落差であるとか、事業の不用額の部分であるとか、そういったものも含めて積み立てているところです。","id":"exchange-137"},{"speaker":"中塚委員","kind":"質問","question":"保育園のほうでは、低賃金、官製ワーキングプアの問題もありますけれども、短時間非常勤職員のつぎはぎで安定した保育ができないという話も伺います。安定財源をつくるというのも間違っていると思いますけれども、いかがか尋ねました。","respondent":"金子企画財政課長","answer":"私ども、前提としてご理解いただきたいのは、事業の成果をなくしてまで節約するということは一切ございませんので、ご理解いただきたいと思います。","id":"exchange-138"},{"speaker":"三上委員","kind":"質問","question":"昨年、同じようなことで質問したときに、団塊の世代の退職する人たちのピークは過ぎたととらえていいんでしょうか。ここらあたり、ちょっとお伺いしたい。","respondent":"榎本人事課長、武内税務課長、阿部経理課長","answer":"退職の人数、確かに平成１９年度が、定年退職１１２名、平成２０年度、この決算で９８名ということで、若干落ちております。… 滞納の関係で、住民税を滞納している方と、他の公金の滞納の連携ということですけれども、実際のところは、やっておりません。… 庁舎耐震の関係ですけれども、平成２３年３月竣工予定です。それが終わりましたら、できるだけ速やかに第一駐車場を開放していきたいと思っています。","id":"exchange-139"},{"speaker":"三上委員","kind":"提案","question":"昨年の第３回定例会のときに、いろいろ質問をし、提案もしてきたわけです。しっかりと品川区も、そういう考え方のもとでの取り組みを行っていってもいいのではないかと思いますが、いかがか尋ねました。","respondent":"武内税務課長、阿部経理課長","answer":"もちろん、多重債務などの相談がある場合については、法テラス等のチラシとパンフレットを差し上げて、そういうところに相談に行くように。東京都で行っている事業等のご案内はしっかりしていますので、そういう意味では… 立体化については検討いたしましたけれども、立体化するには、また閉めなきゃいけないという時期が出てまいります。ですから、それについてはなかなか難しいかなと思っています。","id":"exchange-140"},{"speaker":"林委員","kind":"質問","question":"明日から１０月、今年からこの庁舎の中に保健所長もおられるようになったわけですから、よろしくお願いしておきます。どうぞ、首を振ってわからないようですから、そういう資料をしっかりと国民に役立たせるということをお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-141"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/842680?Template=document&Id=1308#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":114127,"voices":358}},{"id":"h21-20091002-4","meetingId":"h21-c-settlement","date":"2009年10月2日","dateIso":"2009-10-02","committee":"決算特別委員会","time":"午前１０時０２分～午後５時１２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を116件整理しています。","topics":[{"id":"topic-01","title":"◯大沢委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２０年度品川区一般会計歳入歳出決算","agenda":"◯大沢委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２０年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"安定した件数、そして安定した契約金額というんでしょうか、区内の中小の事業者にとってはこの公共事業は大変に頼りになるのだと考えています。もう１点は、先ほどの入札参加登録についても大変に配慮されているというお話を伺っておりますので、この点についてもお伺いしたい。","respondent":"阿部経理課長、中川原広報広聴課長","answer":"空調工事、こういう工事のものについては、入札参加をして格付けを行うという形をとっております。Ａ、Ｂ、Ｃ、Ｄというような格付けを行わないで、順番だけを定めているというようなやり方をとっているです。 区民相談のうちの毎日行っています一般相談について、３,０００件の内訳のお尋ねです。親子関係の相談が３,０００件のうちの主な内容を占めておりますが、不況の影響が出ておりまして、労働相談の関係も若干増えているという傾向です。","id":"exchange-001"},{"speaker":"若林委員","kind":"提案","question":"そういう大型工事の際には、いわゆる元請会社にそういうご案内をもう少し力強くするとかという工夫についてお知らせほしいと求めました。提案させていただきましたけれども、ぜひとももう１回、常設なり定期的な開設ということについてお答えほしいと求めました。","respondent":"阿部経理課長、中川原広報広聴課長","answer":"登録の関係ですけれども、それはなかなか登録は難しいとは思いますけれども、これは個人の事業者の方も登録している例があります。登録については、私どももできるだけわかりやすく丁寧な説明していって、できるだけ登録していただきた… その相談の強化も考えているようですので、また労働相談にもこたえられるように、検討してまいりたいと考えています。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"１つは１０７ページのオリンピックムーブメント事業についてお聞きしたいんですけれども、その辺がわかりましたら教えてほしいと求めました。１０８ページの非核平和都市品川宣言事業について伺いたいんですけれども、今、この点をお聞かせ願いたいと思います。","respondent":"久保田行財政改革担当課長、伊勢総務課長","answer":"その中で、両方合わせまして約７５０万円の事業費がかかっております。後ほど実績報告をした際に認められまして、そちらのほうは約１４０万円ほどオリンピックムーブメント事業として行わせていただいたです。 これを地道に継続することが必要です。それから２５周年に関しましては、あるいはコンサート等を予定しておりまして、区民の方に平和の大切さを普及していきたいと考えています。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"オリンピックムーブメントのほうは総額で８９０万円ぐらいですかね。その辺をお聞きしたので、これからの展開についてお聞かせ願いたいと思います。","respondent":"久保田行財政改革担当課長、伊勢総務課長","answer":"運動施設、スポーツ施設のほうに飾ったりということで、品川区としてご協力はしてまいりました。それ以外に、東京都のほうから商店街に直接そういうお話がありまして、東京都の負担で事業を行っていると聞いております。 これまでもずっと継続的にやってきたわけなんですけれども、確かにおっしゃるように、世界の状況が変わってあります。毎年、普及等に関してどういう形がいいのか検討しながら進めてきておりますし…","id":"exchange-004"},{"speaker":"菊地委員","kind":"提案","question":"今、大きく世界中の流れが変わろうとしているわけですから、区長のご答弁の核廃絶に向けて世界中が努力する必要があるんだと。少し提案させてもらいたいんですけれども、例えば核兵器廃絶を求めるような区民の活動を支援することや、シンポジウムをやるだとかとの意見を述べました。","respondent":"伊勢総務課長","answer":"この非核平和事業に関しましては、区は主体的に、そして自主的に事業等を検討して、ずっと継続してきたものです。そういう面でも、団体に入るということではなくて、品川区は品川区として主体的に事業等を進めていきたいと考えております。","id":"exchange-005"},{"speaker":"菊地委員","kind":"提案","question":"は区として、先ほど提案しましたけれども、あるいは世界大会なんかに世代を問わずに派遣をしていくという問題についてはどうなんでしょうか。あくまでも区がやっている今の事業に固執をしていくんだよという話なんでしょうかねとの意見を述べました。","respondent":"伊勢総務課長","answer":"どこの団体に支援をするとかということじゃなくて、支援をするとかということじゃなくて、その方々の主体的な活動にお任せするというのが区としてはいいと考えています。","id":"exchange-006"},{"speaker":"菊地委員","kind":"提案","question":"私はその点を今、聞いたんじゃなくて、ほかの提案の部分はどうですかということをお聞きしたんです。幾つか提案をさせてもらいましたけれども、その点についてお聞きしたんですとの意見を述べました。","respondent":"伊勢総務課長","answer":"その方々のお考えでやられるというのが一番いいと考えてございまして、これについて区がどうこうということは考えてございません。コメントするということはございません。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問・要望","question":"コメントを求めているわけではなくて、今の流れをしっかりつかまえてほしいということを私は言っているんです。本当に世論と行動が核廃絶の流れを強めることになりますので、ぜひその辺の努力をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"稲川委員","kind":"質問・要望","question":"ページ数で１１２ページ、１１４ページ、１１７ページの住宅・土地統計調査についてお伺いいたします。要するに検索で品川区を調べてそこから入ってきたのか、もしくは違うところから飛んで入ってきたのかという部分の詳細を教えていただきたい。","respondent":"中川原広報広聴課長","answer":"リンクをされて入ってきたかどうかというのは、ちょっと今のシステムではわからないんですね。ただ検索エンジンをグーグルに変えておりますので、かなりいろいろなところからつながって入ってきている可能性はあります。","id":"exchange-009"},{"speaker":"稲川委員","kind":"質問","question":"となるとこの１６２万３,２３３件というのは、要するに今、その内訳というのはわかりますか。どこからアクセスがあったとか、そういうのがわかるような気がするんですが、いかがか尋ねました。","respondent":"中川原広報広聴課長","answer":"訪問者数と、それからトップ１００までどのようなページを見ていただいているかということと、あと１,０００ページまでのアクセス数なんです。庁内なのかというのは、ホームページのシステムとしては、なかなかそこまでは分析はしかねるところです。","id":"exchange-010"},{"speaker":"稲川委員","kind":"質問","question":"今、ご答弁いただいた中で、トップ３、どこが一番訪問するのが多いか説明を求めました。","respondent":"中川原広報広聴課長","answer":"Ｗｅｂ写真館が意外にも２位なんです。３位以下は、季節によって変動するんですけれども、そういった状況になっております。","id":"exchange-011"},{"speaker":"稲川委員","kind":"質問","question":"このホームページに関しての見やすさについてちょっとお伺いしたいんですが、また今後そういうお考えがあるのかどうなのか。そういったわかりやすいホームページを今後つくっていくというのは早急にやるべきだと思うんですが、その辺、お考えを説明を求めました。","respondent":"中川原広報広聴課長","answer":"音声対応するためにはあまりいろいろなものを張ったりしますと、障害者の方が音声で聞いていたときにちょっと不ぐあいが出ます。ただしトップページの見やすさについては追求してまいりまして、来年の３月までにはもう少し工夫したものを出したいと考えています。","id":"exchange-012"},{"speaker":"稲川委員","kind":"質問","question":"次に１１４ページの防災関係なんですが、この中を見ると、区民消火隊というのはどこの予算に属しているのかをまず１点お伺いしたいです。消防団というのは指示系統が消防署から出火報が出るんですが、そういった部分で指示系統がどういうふうになっているかというのを説明を求めました。","respondent":"中山防災課長","answer":"命令指示系統ですけれども、防災区民組織標準図というのがございまして、これは１３地区全体のですね。本部長につきましては、それは消防団なり消防署からの要請に基づいて指示を行うということになろうかと思います。","id":"exchange-013"},{"speaker":"稲川委員","kind":"質問・要望","question":"いつ災害が起きるかわからないので、その辺は徹底してご連絡を密にしてやってほしいと求めました。消防団の運営経費の中で予算がついてはいるんですが、具体的にどういったことに使われているのか、お伺いします。","respondent":"佐藤防災安全担当課長","answer":"今、ご質問があった消防団運営費につきましては、品川区消防団補助金要綱で定められています。平成２０年度につきましては、災害現場用の手袋と無線機、５６５万円を補助しております。","id":"exchange-014"},{"speaker":"原委員","kind":"質問","question":"私のほうは成果報告書の１１１ページ、それからあとは１０９ページ、水と緑の市町村との交流事業に関して伺ってまいりたいと思います。初めに、まずざっくりと３億２,０００万円というものについてのある種の考え方を１点お伺いさせていただければということと、約３００万円か尋ねました。","respondent":"中川原広報広聴課長","answer":"それから事業部がそれぞれ周知に努めているチラシ、一生懸命やっている周知活動を支援する、大きな２つの側面があります。区民の方とのコミュニケーションの道具として２０年間使ってきたものについて、そういったデザインの経費として使わせていただいたものです。","id":"exchange-015"},{"speaker":"原委員","kind":"質問・要望","question":"有料でお売りになっているんでしょうけれども、残った版とか、その辺のところについて、今、状況をお聞きできればというのが１点です。これは住まわれている方だけではなくて、観光という意味もあるので、その辺についてご意見をちょうだいできればと思います。","respondent":"中川原広報広聴課長","answer":"どこでどう配るのかを考えまして必要部数をやっていますので、そんなにむだな量は出ないように考えてやっているところです。外国人の方向けのガイドにつきましては、そういった意味では人を通じてのご案内というのも今、充実を図っているところです。","id":"exchange-016"},{"speaker":"原委員","kind":"質問・要望","question":"白図というんですか、その辺のところで、紙類が余ってくるとどうしても効率が悪くなるんですね。ストックルームもお金がかかったり、ですからその辺をご注意いただきたい、これはお願い事ということで。","respondent":"中山地域活動課長","answer":"市町村交流につきましては、昭和６３年の山北町、それから平成２年の早川町と、それぞれふるさと交流協定を結んで交流を続けているところです。そういう中でいろいろ事業の工夫を図りながら進めていく、そういう意味のある事業だと考えております。","id":"exchange-017"},{"speaker":"原委員","kind":"質問・要望","question":"年間ベースでどういうという形をお聞かせいただきたい。それプラス効果の出し方というお話をちょうだいできればと思います。","respondent":"中山地域活動課長","answer":"そういう参加者の声、あるいはアンケートなんかも踏まえて、工夫する余地があれば考えていく。それから事業の効率化というものも、できる限りむだなくやっていく意識を持ちながら進めていきたいと考えております。","id":"exchange-018"},{"speaker":"浅野委員","kind":"質問","question":"平成２０年度の予算につくるということが入っていたのか、その件を１点と、それぞれ何件ぐらい登録をされているのかというのをまずお伺いします。１０月になってみたらもう消えていたので、大体１カ月ぐらい残しておくのかなと思うんですけれども、それについてお伺いします。","respondent":"中川原広報広聴課長","answer":"この間もメール配信とＲＳＳを比較検討する等々、研究はしてまいりまして、現在のメールマガジンは試行です。確実にきちんとできるというところが担保できなくなりますので、きちんとできる範囲で緊急情報については対応してまいりたいと考えています。","id":"exchange-019"},{"speaker":"浅野委員","kind":"質問・要望","question":"この検討状況はどうなのかということと、これはだめだなとは思っていますけれども、この防災の関係についてお伺いします。これも質問させていただきましたけれども、皆様にこういう状況はどう避難してくださいということはやったのか、お伺いします。","respondent":"佐藤防災安全担当課長","answer":"ご存じのとおり、とりあえず１０月に内定額基準と交付基準が出てきた段階において、Ｊアラートの設置について検討してまいりたいと考えております。それとサイレンについては、今回の地域総合防災訓練については、現在のところ、流す予定はございません。","id":"exchange-020"},{"speaker":"浅野委員","kind":"質問・要望","question":"１～２ｍ浸水する危険性があると私は指摘させていただきましたけれども、そして今回はそれの効果があらわれているのかどうか、お伺いします。それともう１点ですけれども、地方自治体で平成２０年度までに作成するということになっていたわけでありますけれども、お伺いします。","respondent":"中山防災課長","answer":"２００万円から３００万円程度でできるようですけれども、この作成については前向きに検討してまいりたいと思います。それから１問目の浸水ハザードマップの関係ですけれども、あのときは土のうで処理したと聞いてあります。","id":"exchange-021"},{"speaker":"浅野委員","kind":"質問・要望","question":"どのメーカーがやってくれるかという課題はあるかと思いますけれども、この点について区の見解をお伺いします。この状況についてお伺いします。","respondent":"中山防災課長、久保田行財政改革担当課長","answer":"今後、もうちょっと大きなものを、ただご案内のとおり、取りに来るのが業者の方ばかりなんですね。その辺のことがありますので、大きなものをつくって対応してまいりたいと思ってあります。 地上デジタル放送についてですけれども、ケーブルテレビにおきましても、セットトップボックスを使わずに回線使用料だけでできるサービスというものも利用していると聞いております。","id":"exchange-022"},{"speaker":"渡部委員","kind":"質問","question":"現状の進みぐあいをまず１回お伺いしたいのと、６年生で回収という形になると思うんですが、協力員がいますよね。その辺の状況とあわせて説明を求めました。","respondent":"矢部生活安全担当課長","answer":"現在、各種試験を実施しているところで、ソフトバンクテレコム社からは順調に試験は実施されているということで報告を受けております。今後、今月の中旬ぐらいになりますが、今年度中には間違いなく全数交換を行いたいと考えています。","id":"exchange-023"},{"speaker":"渡部委員","kind":"質問・要望","question":"震災等があった場合、どのような形で活用されていくべきなのか、望ましいのかというところをお伺いできればと思います。防災訓練になりますが、地域の企業ですとか、なるべく参加してもらえるようにどのように話しかけをしているのかというところを説明を求めました。","respondent":"中山防災課長","answer":"そのうち訓練を実施したのが１９校あります。それから配備してもどのように使うかですけれども、実際に中学校の生徒がＤ級ポンプを使ってポンプ操作訓練を実施しています。","id":"exchange-024"},{"speaker":"渡部委員","kind":"意見","question":"毎年やれというわけではないんですけれども、何年かに１度、本当に大きな防災訓練が必要なんじゃないかなと思っています。お願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"職員互助会についてお伺いしますけれども、互助会から事業主のほうにどのぐらいのお金が行っているのかということをお伺いします。理念の中に区民ＮＰＯ、品川区という行政がお金を出してそういうことをするのかということがどうしてもわからないので、その辺についてお伺いします。","respondent":"榎本人事課長、中山地域活動課長","answer":"それから２点目の金額につきましては、場所代は無償という形で貸し付けをしておりまして、その中でやってもらっている。実際に食堂のメニューの金額を改定するときには、互助会のほうと協議をした上で… 認識はしているけれども、そういうものについて安心して参加していくかということについては二の足を踏んでいる、こういう方がいらっしゃる。区としての連携をとりながら…","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問・要望","question":"どういう選定で選ばれたのかということを教えていただきたいのと、少子化だったら、もっとほかの施策がいっぱいあるじゃないですか。ぜひここもお伺いしたいんですけれども、こういう意味において、この結婚サポートについてはどういうふうに思われるかもお伺いしたいと思っています。","respondent":"濱野区長、榎本人事課長","answer":"そして区民の皆さんにそれをご提供申し上げるということになると、大体１０分の１ぐらいのことで事が済むということも大体わかってまいりました。そういう意味では、あるいは今回も５組ぐらいが交際を継続させているとか… その後、平成６年に防災センターができまして、そちらのほうに移転をしているという形です。それから職員と区民の割合ですけれども、７～８割が職員の利用、残りの２～３割が区民の利用という形の利用者数になっております。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"なのに何でずっと競争させないで、１つの業者にずっと長くなっているのか、やっているのか。競争させないといけないと思うんですけれども、今後のお考えをお伺いします。","respondent":"榎本人事課長","answer":"今後の考えですけれども、今回こういう事故を起こしましたので、プロポーザルをかけてまたやっていきたいと。ただし立地条件としては決していい状況ではありませんので、複数の方からプロポーザルをいただいて、契約の更新をしていきたいと考えています。","id":"exchange-028"},{"speaker":"金野委員","kind":"質問","question":"私のほうからは、１２ページの近隣セキュリティシステムの運用、そして１０８ページの職員被服貸与費をお伺いします。もう１つの職員被服貸与費のほうですけれども、この職員というのは、庁舎内だけの職員を指すのか尋ねました。","respondent":"矢部生活安全担当課長、榎本人事課長","answer":"ただ内容に応じましては、保護者の方が１１０番通報を独自にされたという内容もお聞きしております。ただし現在、生活安全サポート隊または学校関係者… それから保育園につきましては破損時対応ということで、保育園につきましては破損時対応という形に切りかえをしまして、平成２０年度ですと４０８点。… １点抜けておりました。件数の内訳ですけれども、平成２０年度は１万１,６３４件のうち誤報が１万１,６１１件…","id":"exchange-029"},{"speaker":"金野委員","kind":"質問・要望","question":"要望も含めてお話をしたいんですけれども、我が子も使わせていただいている１人なんですけれども、これは無料で貸与してくださっている。２年生は使っているわけではないんですが、保証期間というんでしょうか、そういったものの考え方はどうなのか説明を求めました。","respondent":"矢部生活安全担当課長","answer":"水没、風塵等の故障ということがありましたので、今回、３Ｇ化に向けまして、防水、防塵の対策強化に努めたところです。２回線という話ですけれども、３回線にする予定です。","id":"exchange-030"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それと１１０ページの生活安全サポート隊活動費と地域食事サービス経費について伺ってまいりたいと思います。この辺を確認の意味で伺いたいと思うのと、大きな事態にならない、未然に防げたという主たる事例があったら説明を求めました。","respondent":"伊勢危機管理室長、矢部生活安全担当課長","answer":"どのような事態に対応するのかですけれども、例えば新型インフルエンザのように全庁的な対応をとる場合には本部を設置する。この辺につきましては、管理職が泊まって、何かあればすぐ対応できるようにです。 車両については５台、パトロール時間につきましては、午前７時３０分から午後８時、これを朝晩、早番、遅番の２交代という交代制でとっております。先ほどの近隣セキュリティシステムの緊急対応ということで…","id":"exchange-031"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういう中で改めて伺いますが、二年だけでも感じてはいるので、その辺のお考えを聞きたいのがあります。やみくもに要望とか拡大ではないんですが、午後８時という時間以降の、もうちょっと拡大してもいいのかなという思いがあります。","respondent":"伊勢危機管理室長、矢部生活安全担当課長","answer":"こういうような事例の対応だとか、消防署あるいは防災課と連携をとりまして、情報収集しています。いずれにいたしましても、私のほうに情報が来まして、それに基づいて対応をとっているです。 基本的には子どもの見守りということで運用していますので、現在までは２０時まででいいのかなと考えております。威圧的な色とかよりも、やはり優しい色といいますか、緑色にしたです。","id":"exchange-032"},{"speaker":"渡辺委員","kind":"確認","question":"それと週２回、火曜日と木曜日という中で、調理をする側、最近は個店でも、祝日のことで伺っていくんですが、営業されている。特に配食の部分で結構苦労するのかなという想像があったので、考慮が必要なのかどうか、どんな対応をされているのか伺えればと思います。","respondent":"秋山協働・国際担当課長","answer":"火・木ということで、祝日の手配はですけれども、現在のところ、商店街連合会にこの食事サービスは委託をしています。配食を実施している業者の中には、祝日についてもなるべく年間を通じて配食ができるように考えているところです。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"運営助成金の中身について内訳を教えてほしいと求めました。そのほかにもしあったらどんなのがあるか教えていただきたいし、選管としてどういうふうにとっておられるのかを紹介してほしいと求めました。","respondent":"中山地域活動課長、早津選挙管理委員会事務局長","answer":"運営協議会への助成の主な中身ですけれども、受付あるいは事業の人件費と申しますか、事務局とボランティアの経費、これが約３４０万円です。それから事務費が約１４０万円、これが約１,２００万円… それからもう一つは、病院等に入院されている方のための、指定施設と申しておりますけれども、その病院等で投票するという制度があります。主にはそういった制度です。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"国民の権利という点でどういうふうに考えておられるのか、改めて認識を伺ったんですけど、そこは改めて伺っておきたいと思います。もうない、十分にやり切れているんだという見解なのかどうかも含めて、実態がどうなのかを伺いたいと思います。","respondent":"中山地域活動課長、早津選挙管理委員会事務局長","answer":"１年間を振り返ってです。１年の中で一つの形が大分整ってきているのかなと考えていますが、区としてもまた支援をしながら進めていきたいと考えております。 引き続き課題であるというふうに考えてあります。周知については大体行っているというふうに認識しています。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"今回は自主的な運営をしていこうというところで設定したことですから、この人件費のところが１,９９０万円の助成金のうちの６分の１ぐらいですよね。果たして３４０万円で本当にいいのかどうかというところがあるので、費用も含めてどういうふうに考えるのか、お願いしたいと思います。","respondent":"早津選挙管理委員会事務局長、中山地域活動課長","answer":"制度自体を拡大するということは、これは法令上のことでありますので、区独自ということでは困難であろうと考えています。周知のＰＲの方法については、引き続きよりよい方法を検討して参ります。 事務局職員として一定の時間単価をかけている部分と、今回は有償ボランティアを活用するという中できちんとやっていただいていると思います。ただし…","id":"exchange-036"},{"speaker":"阿部委員","kind":"質問","question":"それから１１３ページ、事業部支援プロジェクト、そして１１７ページの選挙費についてお伺いしたいと思います。そういった位置づけの変更を伴って食堂というのをこの機会にとらえ直すこともできるのではないかと思いますが、お考えをお伺いします。","respondent":"吉岡保育課長、榎本人事課長、久保田行財政改革担当課長、早津選挙管理委員会事務局長","answer":"所得制限の撤廃について検討しているかですけれども、今現在、全体のバランス等を見ながら考えているです。 それから位置づけの変更ですけれども、実際にあそこの食堂で出る食数が、大体１日４００食ぐらいです。先ほど午前中も申しましたように… これの主な中身につきましては、それと昨年設置いたしました区民と区との協働を進める懇話会の正副委員長に対する謝礼というものが主なものです。… １人は書く役目、１人はそれを確認する役目ということで…","id":"exchange-037"},{"speaker":"阿部委員","kind":"質問","question":"ちょっと額が大きいものですから、それからサーバー、懇話会。２３区の中でもごくごく少数ということから考えまして、その７３０万円のところで、これについて再度お考えを伺いたいと思います。","respondent":"久保田行財政改革担当課長、吉岡保育課長","answer":"ボランティア総合情報システムサーバーの賃借料ということで約２００万円。昨年度から実施いたしました協働事業提案制度の審査会への謝礼というもの、それをあわせますと約６０万円程度の金額になるです。 所得制限を設けているところ、いないところというのは、おっしゃるとおりかと認識しています。そのように様々な補助的な施策に取り組んでおりますので、全体的に、総合的に考える中で考えていくべきものなのかなと考えているところです。","id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"このコンサルティング費用の出てきたもの、それのバランスがどうかなというのは、今後また見ていろいろと伺っていきたいと考えています。オリンピック、スペシャルオリンピックスにかかわるような事業をなさったか、あるいはこれから計画されているかということを説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"変わりなくオリンピックの精神というものは共通にあるということでお答えをさせていただいたところでございまして、オリンピックの精神に基づきまして、そういった思いも持ちながら事業を展開させていただいたです。","id":"exchange-039"},{"speaker":"山路委員","kind":"質問","question":"３点目は１１２ページ、ホームページ等経費についてお伺いいたします。ふれあいサポート推進事業のふれあいサポート活動費は約９３３万円余ほど計上してありますが、この活動の展開についてお伺いをいたします。","respondent":"秋山協働・国際担当課長","answer":"１３地区のふれあいサポート活動会議等の費用、地域の活性化に寄与する団体に感謝状等を贈呈して、地域の活性化を図り相互支援を図るというものです。それからふれあいサポート活動の、これは高齢者懇談会の保険の費用というような三つの事業の中で展開しているものです。","id":"exchange-040"},{"speaker":"山路委員","kind":"質問・要望","question":"この事業は、地域のおひとり暮らしの高齢者の方とかを守っていく、困った人にとっては非常に助かるのかなと私も思っておりましたが、この中にボランティア登録制の事業も入っているのかどうかお聞かせほしいと求めました。","respondent":"秋山協働・国際担当課長","answer":"ボランティアの登録ですけれども、地域センターの方にふれあいサポート担当があります。社会福祉協議会のボランティアセンターともつながっておりますので、その中での登録の制度というのは持ってあります。","id":"exchange-041"},{"speaker":"山路委員","kind":"質問","question":"こういうのが非常に少ないという話をお伺いしまして、こういう手伝ってもらいたい人の内容を掌握されているかどうか、お伺いいたします。","respondent":"秋山協働・国際担当課長","answer":"地域センターにも入ってきているとは認識しておりますけれども、そのマッチングというのがなかなかうまくいっていないというのも認識しています。社会福祉協議会、ボランティアの活用…","id":"exchange-042"},{"speaker":"山路委員","kind":"質問","question":"前半は大分少なくなったかなと思っていましたが、７月に警視庁で大々的にキャンペーンをやられまして、またこのところ増えてきたと。エクスパックですか、品川の実態はどうか、お伺いいたします。","respondent":"矢部生活安全担当課長","answer":"暗証番号は何番でしょうか」と聞く手口。さらに「担当の者がご自宅に通帳を取りに行きますので、いまだ、先ほど懸念するような発生件数にはなっていないと聞いております。","id":"exchange-043"},{"speaker":"山路委員","kind":"質問・要望","question":"昨年お伺いしたときに、この２点が非常に重要だということなんですが、高齢者のいる家庭を全家庭訪問して趣旨を徹底していく。こういうところもあるみたいですが、踏み切ってほしいと求めましたけど、この辺の対策については今後どのように考えていらっしゃいますか。","respondent":"矢部生活安全担当課長","answer":"現在のところも生活安全パトロールカーでの広報、またはわがまちパトロールによる合同パトロール等で実施しているところであります。今月の１１日から全国地域安全運動が始まりまして、これからも新たな手口が発生した場合には区民の皆さんに情報提供していきたいと考えておりま…","id":"exchange-044"},{"speaker":"山路委員","kind":"質問・要望","question":"そういう中に、なかなか趣旨徹底できないから新たに考えていただきたいということを要望しておきます。お伺いいたします。","respondent":"中川原広報広聴課長","answer":"若者支援のウェブサイト、イメージがちょっと沸かないんですが、今、公式ホームページとしましては、区からの情報をお知らせすることを旨として、公の情報をお知らせするツールとして使わせていただいております。","id":"exchange-045"},{"speaker":"市川委員","kind":"質問","question":"それから１０８ページの国際友好都市交流事業、１１３ページの防災対策費、１１２ページの情報公開事務費より伺います。民間に委託できる仕事と委託できない仕事ということについてはどんな判断基準を持っているのか、この辺のことについて区のお考えを説明を求めました。","respondent":"安井子育て支援課長、榎本人事課長","answer":"児童センターの方の職員の今後の採用の関係ですけれども、保育士等、児童厚生の関係で採用をしていって、こちらの事業の継続の方で対応して参りたいと考えております。 今までは職種を細分化してきたものをある程度統合して、複数の職場に配置できる人材を育成していきたいという大きな方向があります。すまいるスクール、そういうところで児童を相手にする人材という形…","id":"exchange-046"},{"speaker":"市川委員","kind":"質問","question":"次に１０８ページの国際友好都市交流事業について伺います。そこの使用料というのはどういうふうに区の方に入ってくるのかどうか、その辺を伺います。","respondent":"秋山協働・国際担当課長、阿部経理課長","answer":"昨年平成２０年度の場合は、オークランドの公式訪問団がございまして、その派遣ということで区の執行額として６０８万円何がしです。友好協会への補助金が９,５４３万円となっております。 友好協会の使用料ですけれども、あそこは行政財産の使用許可ということをやっておりまして、使用料は免除という形になっております。","id":"exchange-047"},{"speaker":"市川委員","kind":"質問","question":"特に展示室の使用というところがどういう考え方の中で行われているのかということをお聞かせください。それからもう１点は、組織改正を行って半年がたったんですけれども、協働・国際担当との連携というところでは何かあるのか、その辺をお聞きします。","respondent":"秋山協働・国際担当課長","answer":"４階フロアの展示室ですけれども、３都市との交換で、友好協会の方で管理をしています。国際担当が今年の４月に地域活動課にできまして、４月以降、地域の国際化に一緒に取り組んでいるところです。","id":"exchange-048"},{"speaker":"市川委員","kind":"質問","question":"１１２ページの情報公開事務費というところから伺いますけれども、例えば次世代育成支援行動計画、それから区長の諮問を受けた廃棄物等減量審議会。ここで出る資料とか議事録というのは、行政文書というふうに言えるのか言えないのか、その辺をちょっとお聞きしたいんですけれども。","respondent":"中川原広報広聴課長","answer":"情報公開制度でいう、行政が保有する文書に当たります。","id":"exchange-049"},{"speaker":"市川委員","kind":"質問","question":"行政が保有する文書というのは、行政文書というふうに受けとらせていただいてよろしいんか尋ねました。","respondent":"中川原広報広聴課長","answer":"委員がおっしゃる言葉のその先にある意味によって、同じかどうかというのはちょっとあるかと思いますので、もう少し聞かせていただけますでしょうか。","id":"exchange-050"},{"speaker":"市川委員","kind":"質問","question":"長期基本計画の第３章で区民との協働に必要不可欠なものとして情報の公開というのを挙げていらっしゃいますので、このことにどうやって具体的に取り組んでいくのかなということもあわせてお聞かせほしいと求めました。","respondent":"中川原広報広聴課長","answer":"はなから検討経過を開いて、傍聴も入れて運営していく会議もあれば、それは会議の自主性に任せて運営をさせていただいているところです。本当に十分に審議を尽くすという目的に合わせた資料の公開ということで、私どもは協力するということで運営しておりますので、ご理解くださ…","id":"exchange-051"},{"speaker":"市川委員","kind":"質問","question":"区民との協働を進めていく上では、今後とも情報公開については前向きに検討してほしいと求めました。２００６年度から２００８年度までの３年間の小学校、中学校、それぞれの学校避難所連絡会議の開催状況を伺いたいんですけれども。","respondent":"中山防災課長","answer":"ここ３年でよろしゅうありますか。平成１８年度は学校避難所連絡会議が３７回、それから平成１９年度は３９回、平成２０年度は３３回となっています。","id":"exchange-052"},{"speaker":"市川委員","kind":"質問","question":"この成果報告書のところを見ると３３回というふうには書かれていないので、その差が何なのかということを伺います。全校開催に至らない原因というのはどんなふうに把握をされているのか説明を求めました。","respondent":"中山防災課長","answer":"区職員が避難所運営について計画を立てて検討するものですということはもうご案内かと思いますけれども、その中に議長がおりまして。ただ、３年間を比較しますと全然開いていないというところは数校だです。","id":"exchange-053"},{"speaker":"市川委員","kind":"質問","question":"そうしますと、この成果報告の４５ページに書かれている学校避難所連絡会議の小学校１８校、中学校８校で開催というのは、これはあわせて３３校で開催されたというふうに受けとってよろしいんか尋ねました。","respondent":"中山防災課長","answer":"そのようにとっていただいて結構です。","id":"exchange-054"},{"speaker":"市川委員","kind":"質問・要望","question":"先ほど午前中の答弁の中で、開いたことがないような学校が１校もないように、積極的に開催されるように力を尽くしていただきたいと思っています。学校のことで、統合で避難所が変わる地域に対してはどんな対応をしているのか、対応策について。","respondent":"中山防災課長","answer":"一貫校になったり、建て替えだとか統合だとかという学校につきましては、私どもはその避難所連絡会議等に赴きまして、どこどこに一時的に避難をしてください、工事中はここに避難をしてくださいというような説明を個々にさせていただいてあります。","id":"exchange-055"},{"speaker":"市川委員","kind":"質問・要望","question":"災害はいつ起こるのか本当にわかりませんので、やっていないという学校がないようにぜひ頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"山内委員","kind":"提案","question":"それから、先ほどもほかの委員から質問がございました私立幼稚園の補助金について、まずこの２点お伺いをいたします。そうしますと、その加算金の金額のパーセンテージというんですか、もしそれがわかれば教えてほしいと求めました。","respondent":"武内税務課長、吉岡保育課長、榎本人事課長","answer":"おのずと住民税もそれにあわせて１カ月後に課税するということなんですが、そういう経過の中、このような高額の還付加算金が発生したという経過です。… 私立幼稚園の保護者への補助金の件です。入園料の補助ですとか、支援の枠組みの中で考えていくべきものと考えていますけれども… 午前中そういう形で制約条件があるというふうに説明しましたが、複数の事業者の中から一番区の要望に沿える形の事業者を選んでいきたいと考えております。","id":"exchange-057"},{"speaker":"山内委員","kind":"意見","question":"これ、率が高いかどうかというのは銀行のいろいろな状況というのを見ますと、そんなに高くはないのかなとは思います。だけれども、加算金が発生しないようなしっかりとしたシステムの構築というものをお願いできればと思いますとの意見を述べました。","respondent":"武内税務課長","answer":"ですから、区税につきましても平成１４年６月から平成２０年４月までの部分については法令的な部分で支払わなければいけない部分なんです。その辺の手続きが品川税務署から渋谷税務署のほうに移り変わったという手続きの関係の中で、金額的に多くなってしまったということです。","id":"exchange-058"},{"speaker":"高橋委員","kind":"質問","question":"それから１０９ページの品川文化振興事業団、時間があれば１１６ページの戸籍事務費をお伺いします。重なりとかそういうのがもしあるなら、どうしてあえて似たような講座をつくっているのかとか、その辺のことをちょっとお伺いしたいんですが。","respondent":"堀越文化スポーツ振興課長","answer":"そういったものを勘案いたしまして、財団の部分での実施、それから区のほうでの実施という形になってまいります。昨年度で言いますと生涯学習課で実施をしておりました区民作品展、相乗効果という形で文化、それから生涯学習の振興を図っているところです。","id":"exchange-059"},{"speaker":"高橋委員","kind":"質問","question":"そうなると、今、連携をとっていろいろ精査というか調整をしながらやられている。区のやっている事業はすべて直営、つまり区の中でやられているんですが、委託等もされているんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"区内のいろいろな自主的な活動をなさっている団体、そういう方たちの企画を募って、そういう方たちに委託をしておこなうような形もあります。そのコーディネートを文化スポーツ振興課の職員がやっているという形です。","id":"exchange-060"},{"speaker":"高橋委員","kind":"質問","question":"そうでない形で委託をするんでしたらば、こちらの文化振興事業団のほうに委託をするという方法はないでしょうか。あるいは専門的に文化事業のほうで、趣味と違うというふうな考え方はあるのかもしれませんが、その点は調節しながらできるのではないか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"鑑賞型の事業ですとか、文化振興事業団のほうと役割分担をしておりますので、既に一定程度役割分担がされていると認識しております。文化芸術・スポーツのまちづくり条例等の趣旨も生かしながら、さらに連携をしながら文化の振興について努めていきたいと考えているところです。","id":"exchange-061"},{"speaker":"高橋委員","kind":"質問","question":"では次に１０８ページのほうの職員研修。管理職の試験についてお尋ねしたいんですが、まずは人事課長にお伺いしたいんですが、なぜ課長になろうと思われたんか尋ねました。","respondent":"榎本人事課長","answer":"試験があったから受けたです。","id":"exchange-062"},{"speaker":"高橋委員","kind":"意見","question":"品川区の職員の方々の管理職試験を受けることのできる有資格の方の人数と、その中で受験をされた方の人数で、その点での受験率と合格者数を、平成２０年度は四つ言っていただいて、あとはここ３年の有資格者数と受験者での受験率、お願いしますとの意見を述べました。","respondent":"榎本人事課長","answer":"まず費目的にはこの職員研修ではなくて、人事厚生事務組合の分担金で、特別区人事委員会が２３区共同で管理職選考を実施しております。平成１９年度７人、平成２０年度７人ということで、合格者の人数は増えているという形です。","id":"exchange-063"},{"speaker":"高橋委員","kind":"質問","question":"受験率というところを見て、有資格者の方が受験したということですね。ほかの２３区と比べてどのような感じなんか尋ねました。","respondent":"榎本人事課長","answer":"２３区共通で試験をしておりますけれども、全体的な傾向としては、品川区の傾向と似たような形になっております。ただし、活力を生み出すという形にならないということですので、自前の中できちんと人材を確保して育成していくという形だと認識しております。","id":"exchange-064"},{"speaker":"高橋委員","kind":"意見","question":"品川区ではＩ類のほうの受験率２.３％で、２３区の中では１８位なんですね。それで、この状態をどうお考えになるのかということと、あと試験があるからというだけではなくて、受験率を高めるための手立てを何かお願いしますとの意見を述べました。","respondent":"榎本人事課長","answer":"その中で今の係長級、それから主任主事の中から受験者を選び出しまして、個別に進めているところです。中でも短期、どの時期に管理職になろうかというのはその人の人生設計とも絡みますので、それも見極めながら一生懸命進めているところです。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問","question":"職員の健康、特にメンタルヘルスの関係について伺います。８０時間を超える人数、４５時間を超える人数の、まず数字を説明を求めました。","respondent":"榎本人事課長","answer":"平成１８年はありませんけれども、平成１９年度が３人、平成２０年度が６人というものです。年間平均４５時間を超える者が５４人、５２人、７５人という人数です。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"メンタル系のご病気だったのかどうか、その辺を教えていただきたいのと、過重労働の方の中に心の病になった方がいらっしゃったらどのぐらいなのか。わかったら説明を求めました。","respondent":"榎本人事課長","answer":"残り２人の中でメンタル系と認識しているのはお１人です。超過勤務者の中でですが、超過勤務の多い方の中でメンタル系の方は、今言った人数の中にはございません。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"とても残念というか、治らないでおやめになるというとても残念なことであるので、改めて病気を生み出さない職場づくりの努力が求められると思います。こういった面で、適切な職員配置が求められると思うんですが、この点はいかがか尋ねました。","respondent":"榎本人事課長","answer":"過労死ラインという部分では認識をしていますけれども、職員の所属によって、それをなるべく平準化するような努力はしていきたいと考えています。合わせて平均でも２３４時間ということで、国と区…","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この仕組みのところをぜひお伺いしたいのが３点目です。権限があるのかどうか、この点を説明を求めました。","respondent":"榎本人事課長","answer":"ただ、度重なる人格を壊すような言動、行動という形での認識を持っております。それは私のほうへ連絡をいただいて、どういう職場の状況なのかということをきちんと解明をして、対応に当たっていきたいというふうに考えております。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"同じ方と何回も面談をしている中で、そういう状況はないのでしょうか。改めて伺います。","respondent":"榎本人事課長","answer":"メンタルヘルスでも窓口を定めていますけれども、メンタルヘルスの部分の窓口も兼ねながら、そちらのほうで対応窓口を図っているです。その辺はもしそういう訴えがあれば、両方から、双方から申し出の内容を聞いて対応を図っていきたいというふうに思っています。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"労災認定のところでも、精神障害のところが年々増加をしていて、２００７年度で申請が９５２件で２８％が労災認定を認められている。研修を充実強化をさせていただきたいということと、防止の仕組みづくりを急いでいただきたいんですが、いかがか尋ねました。","respondent":"榎本人事課長","answer":"今年度もまた１２月に管理職研修等をして、現状がどうなっているのか、そういうものをきちんと認識した上で対応できるように研修をやる予定です。パワハラの仕組みにつきましては、まだそこまで、こうやれば防げるというような仕組みづくりは、まだ聞いておりません。","id":"exchange-071"},{"speaker":"堺委員","kind":"確認","question":"１１３ページの防災対策費に関連して何点かお伺いいたしますが、災害時優先電話回線設置工事２９カ所ですか、避難者確認システムサーバー使用料等。その成果報告書の中身について簡単で結構ですので、ちょっと教えていただけますか尋ねました。","respondent":"中山防災課長","answer":"内訳ですけれども、災害時優先電話回線の設置工事費が３３６万円。こういう、この成果報告書については、財政のほうでまとめて書いてありますので、ひとつよろしくどうぞ。","id":"exchange-072"},{"speaker":"堺委員","kind":"提案","question":"何点かご提案を申し上げたんですけれども、まず平成１５年の９月、五丁目の３町会合同によります初めての学校避難所防災訓練が行われたわけですね。ぜひ積極的にそういうことを実施されるように支援していただきたいと、こう思うんですが…","respondent":"中山防災課長","answer":"ここ３年で、先ほども申し上げましたけれども、全然実施していないというところは、約８校ぐらいだと思います。副校長、それから地元町会長と会いまして、積極的に避難所連絡会議を開くように働きかけてまいりたいと思ってあります。","id":"exchange-073"},{"speaker":"堺委員","kind":"質問・要望","question":"もう１回確認をしておきたいと思うんですが、総括質問の中で、荏原第四中学校で行われた荏原第五地区の総合防災訓練を引用いたしました。このことについて、どのような視点でもって取り組んでいこうとしているのか、その辺をちょっと確認をしておきたいと思います。","respondent":"冠木指導課長、濱野区長","answer":"なお、校長、副校長、教職員につきましては、延べ２９４名の参加を今のところ予定していると。子どもたちについても、各町会の協力を得ながら、多くの児童生徒に参加していただけるように呼びかけているところです。 積極的に進めていることでございまして、教職員はこういう役割というのを決めておいていただきたいというようなこともお願い申し上げました。子どもたちを防災のあれに駆り出すということではありませんけれども…","id":"exchange-074"},{"speaker":"堺委員","kind":"質問・要望","question":"あわせて、これも平成２０年の第１回定例会の代表質問のときに申し上げたわけですが、中学生を対象にしたＡＥＤの講習です。これも、１人でも多くの生徒さんたちがＡＥＤの使用方法を学べるようにしていただきたいと思うんですが、確認の意味で教えてほしいと求めました。","respondent":"中山防災課長","answer":"３年生についても救急医療訓練を行うなど、救護に関する取り組みの向上を図っております。今後も荏原四中、八潮学園、日野学園などでもＡＥＤを実施する、訓練時にＡＥＤを実施する予定です。","id":"exchange-075"},{"speaker":"川西委員","kind":"質問・要望","question":"それから、子どもたちが行ける昆虫類の巣箱づくりというのは心がけなかったかどうか、伺います。それから、自前の施設を維持管理していくのに、どういう組織的なやり方でやっていらっしゃるのか伺います。","respondent":"中山地域活動課長、秋山協働・国際担当課長、久保田行財政改革担当課長","answer":"例えば難しい作業ができないような天候のときは、巣箱づくりをやってみようということで、鳥の巣箱もつくりました。… 委員ご指摘のとおり、昼食に関しましても地域商店を活用した配食に切りかえていく方向で検討しています。コミュニケーションをよくするということで開始時… 私からは、区政アドバイザー会議についてお答えいたします。平成２０年度は３回行いまして、昨年は「組織」「長期基本計画」「人材育成」といった３点のテ…","id":"exchange-076"},{"speaker":"川西委員","kind":"質問・要望","question":"それから保養所のことですけれど、平成２０年度は何も小破修繕をしないという、これだけ大勢の人が参加するところで、それでいいんでしょうか。人材育成についてはどのような提言をいただいて参考にされたか、ここだけちょっと教えてほしいと求めました。","respondent":"中山地域活動課長、久保田行財政改革担当課長","answer":"２０年度はいわゆる壁紙の一部張りかえであるとか、敷居の傷んだところを直すとか、このようなものは毎年きちんとやっていきたいと考えております。現地の視察は毎年、担当課長も必ず自分の目で見て… 人材育成についてのお尋ねですけれども、例を紹介しますと、職員のモチベーションをいかに持たせるかといったところでご意見をいただいたところです。顕彰制度とか研修を手厚くやることで職員の能力を上げて…","id":"exchange-077"},{"speaker":"伊藤委員","kind":"質問・要望","question":"成果報告書の１１０ページ、地域環境整備等助成金に関連してと、１１３ページ、防災センター展示に関連して質問します。環境整備のほうでありますけれども、町会・自治会の現状をどういうふうにとらえているかということをまずご答弁ください。","respondent":"中山地域活動課長","answer":"いろいろな自治体の中でも品川区の町会・自治会というのは、誇るべきしっかりした組織として活動していただいていると考えています。ただ、こういう点では区もしっかりと支援をしながら、町会活動がさらに活発になるようなお手伝いをしていきたいと考えております。","id":"exchange-078"},{"speaker":"伊藤委員","kind":"質問・要望","question":"Ｂ町会は７３３万円でありまして、これは会社でいいますと週休２日の会社で８時間勤務の社員４人が働く時間に相当するということで、無償であります。改めてこういう数字に対する品川区の感想と、できましたら町会・自治会に対する感謝のお気持ちをいただきたいと思うんですが、いかがか尋ねました。","respondent":"中山地域活動課長","answer":"包括的な町会支援を継続的に行っているわけですけれども、この助成経費の見直しを行っております。区がご支援申し上げる部分がそのうちどうなのか、支援すべき妥当な額というのは難しいところですが、２３区トップレベルのいろいろな意味での支援を。","id":"exchange-079"},{"speaker":"伊藤委員","kind":"質問","question":"町会を科学するといったらいいんでしょうか立体的に、例えば今日いただいたしながわガイド、これには町会のことが書かれておりません。立体的に町会・自治体活動に今どういうものが足りないか、それに対して品川区としてどう対処できるか調査することを検討してみたらどうか尋ねました。","respondent":"中山地域活動課長","answer":"今のお尋ねは、より体系的な把握というんでしょうか、そういう形も検討しないかです。直接お声を聞く以外の形でも把握が必要だと認識されるようでありましたら、今のご提案のようなことも今後の研究課題としていきたいと考えています。","id":"exchange-080"},{"speaker":"伊藤委員","kind":"質問","question":"どういうものが自分たちに返ってくるかとか、本当にむなしさを実感する中にあって、それに対して町会・自治会の自主努力では対処できないわけです。だから、具体的に対処していく仕組みを考えたらどうですかということでありますので、もう１回答弁をお願いいたします。","respondent":"山田副区長","answer":"大型マンションの方々の加入等、地域の町会長にお話を伺うと、本当に大変なんだと伺っております。今の町会活動の中で困っていることを含めてどういう実態にあるのかという把握を、今後区としてもしっかりとらえていきたいと考えています。","id":"exchange-081"},{"speaker":"伊藤委員","kind":"質問・要望","question":"約１,４００万円のお金をかけているわけですね、決算上は。それからイベントの協力をやっているようですけれど、もう少し具体的な対処をしていく必要があると思うんですが、いかがか尋ねました。","respondent":"中山防災課長","answer":"ですから平成２２年度に私どもでちょっと基本計画を練って、平成２３年にリニューアルをしていきたいと。リニューアルして、新しいものを２３年度から皆様に見ていただきたいという考えもありますので、よろしくお願いします。","id":"exchange-082"},{"speaker":"伊藤委員","kind":"提案","question":"あくまで予算の議決はこちらでするわけですので、それは提案していただいたとき私どもも判断していきたいと思います。リースで使われているわけですから、多くの区民に活用していただけますように、お願いしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"西本委員","kind":"確認","question":"私からは、１１０ページの生活安全推進事業になるんでしょうか、テロ対策についてお聞きします。パラリンピック、スペシャルオリンピックスというのは考え方も組織も違うということを知った上でのご答弁だったのか、確認だけしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"オリンピック、スペシャルオリンピックスというのはＮＰＯ団体が取り組んでいるものだというふうには認識しております。そうした上で、障害のある方、ない方にとってオリンピックの精神というものは平等だという意味でご答弁させていただいたものです。","id":"exchange-084"},{"speaker":"西本委員","kind":"質問・要望","question":"これに対する区の認識、区にとっての役割、今後のかかわり方についてお聞きしたいと思います。それから備蓄物資の件ですけれども、目標値と達成率が今どんな状況になっているのか、このスケジュールもお聞きしたいと思います。","respondent":"佐藤防災安全担当課長、中山防災課長","answer":"合同訓練の実施、検討会、研究会の実施を行っています。なお９月２７日ですが、品川警察署と区の我が町パトロール隊が連携して、テロの未然防止のキャンペーンを実施しております。 備蓄物資の目標値ですけれども、災害想定による避難者数の３日分の物資を確保しているです。区内の米穀商とのランニングストック分を合わせて９０万食、これを目標値として、今も９０万食は確保しているです。","id":"exchange-085"},{"speaker":"西本委員","kind":"提案","question":"ですから、その辺でどういう防犯システムをつくっていったらいいのかということは、それを利用するという形をぜひとっていただきたいと考えています。今は皆さん水洗トイレですから、ぜひ私が提案させていただいた凝固剤とか別の方法もありますので、いかがか尋ねました。","respondent":"中山防災課長、伊勢危機管理室長","answer":"平成２０年度も購入いたしましたけれども引き続き今年度も、少しずつではありますが簡易トイレを購入してまいりたいと考えています。マスクについてはインフルエンザ対策で買うということで、私のほうには備蓄はございません。 今、危機管理室で持っているのは６０万枚ですが、なかなか今は入手できないという状況です。ダブルパンチといいますか、それからそういう危機が重なった場合にも対応できるように、そういう面でも検討する必要があるのかなと考えていま…","id":"exchange-086"},{"speaker":"西本委員","kind":"質問・要望","question":"トイレはやはり非常に深刻な問題ですので、ちょっと認識を強めていただいて、早急に対応をお願いしたいと思います。それからマスクの件は、そういう時点ではそちらに流用するとかいう形で使っていただきたいと考えていますので、検討のほど。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"須貝委員","kind":"質問","question":"私は１１３ページの企画調整費、１１５ページの地域センター等管理運営費について質問します。品川区と区民とのかかわり方にちょっと目を向けますと、区民から見て果たして楽になっているんでしょうか、と私は思うんですね。","respondent":"久保田行財政改革担当課長","answer":"税金等、国民健康保険ではコンビニ納付とか、そういった民間との連携も図りながら、皆様への向上に努めているところです。どうしても足を運んでもらわなければいけない事務もありますが、できるだけ向上に努めているところです。","id":"exchange-088"},{"speaker":"須貝委員","kind":"質問","question":"「地域センターでやれないんですか」と言うと、「いや、それはできません」という話を聞きます。「今、やっています」というお話でしたが、どうか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"私ども区役所も、先ほど言いましたけれどもコンビニ納付とか、銀行での納付ができるような形で利便性というものも取り入れているところです。例えば福祉の問題等につきましては…","id":"exchange-089"},{"speaker":"須貝委員","kind":"提案","question":"では、品川区ではどうなんでしょうか。区民の利便性を考える、区役所に来なくてもいいような仕組みづくりを私は提案しているんですが、その辺についてご見解を説明を求めました。","respondent":"原情報システム課長","answer":"委員ご案内のとおり、やはりインターネットを活用して申請ができないかとか、そういったことが一番多うあります。使える方の年齢層はいろいろありますので、そういったことを踏まえながら、今後の施策に生かしていきたいと考えているところです。","id":"exchange-090"},{"speaker":"武内委員","kind":"質問・要望","question":"私も平成１９年の第三回定例会でこの件を取り上げさせていただいて、今、ほかにどこかついているところがあれば教えてほしいと求めました。この３点を説明を求めました。","respondent":"榎本人事課長、中山地域活動課長、阿部経理課長","answer":"通勤手当の関係で、自転車通勤の人数ですけれども、本庁舎、出先事業所含めて４６６人で、率にすると大体１８％ぐらいが自転車で通っているという形です。 荏原第五地域センターの敷地につけた自販機は、本年７月に機種を切りかえる際に災害ベンダー機能を持ったものに切りかえたです。そのほか… 庁舎の駐輪場の件ですけれども、先週の２４日木曜日、２５日金曜日で調査をいたしました。もうしばらく、１週間ぐらい様子を見ながら不必要なものについて…","id":"exchange-091"},{"speaker":"武内委員","kind":"質問・要望","question":"防犯登録を確認して連絡を入れているのかどうか教えていただきたいのと、ＡＥＤはわかりましたので、また研究してほしいと求めました。それから自転車通勤はまたぜひ積極的に、環境という視点も取り入れた考え方をぜひやっていただきたいと、これは要望にします。","respondent":"諸石交通安全担当課長","answer":"土木管理課で撤去した自転車につきましては、警視庁と区が協定を結んでおりまして、防犯登録の照会をして所有者の情報をいただいているという形で進めております。","id":"exchange-092"},{"speaker":"林委員","kind":"質問・要望","question":"何点かお聞きしていきますけれども、１１０ページのふれあいサポート推進事業ということで、昨日から始まった赤い羽根募金というのはご存じですかね。僕でも怖いぐらいですから、ちょっとその辺、どういうふうに彼らに指示が出ているのかを聞かせてください。","respondent":"榎本人事課長、阿部経理課長、中山地域活動課長、矢部生活安全担当課長、中山防災課長","answer":"職員が羽根をつけていないのかですけれども、募金したかしないかにかかわらず、特に職員がつけないとか何とかという決まりはありません。ただし… 交通安全につきましては、研修という形で安全運転の講習会をやっております。当然のことながらアルコール検知をして… したがって全体像というところの計画は、確かにまだ確固たるものはつくっておりません。ある意味では力を入れながら現場と連携してやっていくのかを… 大崎、五反田の３地区につきましては６人で…","id":"exchange-093"},{"speaker":"林委員","kind":"質問・要望","question":"赤い羽根のほうは、優しい心で品川のまちがにぎわっているという意味からも、羽根ぐらいはつける心になってほしいなと。ある程度段階的に考えて、部長が非常に立腹をしているようですけれどきちんとしたお答えをほしいと求めました。","respondent":"岩田防災まちづくり事業部長","answer":"このマニュアルに沿って、実際には５年とか１０年かかるかもしれませんが、仮設住宅での面倒をみたりという民生部門でお金がかかってまいります。ここら辺は十分慎重に、まだ東京２３区でこれを始めている区はございませんが…","id":"exchange-094"},{"speaker":"土井委員","kind":"質問・要望","question":"私からは、やりとりの中で議員側とご説明のほうとがどうも違っているところを１点伺うこと、それから１１３ページのＣＡＴＶ絡みでお伺いすること。あるいはそういうことが起こらないようにする方法をやっておかないと、相談がふえちゃったりすると困るので、その辺をお伺いしたいと。","respondent":"福田会計管理者、伊勢総務課長、久保田行財政改革担当課長","answer":"ご説明の際に、こちらの決算書にはそういう言葉はありませんけれども、成果報告書のＣＡＴＶ事業にこの款はこのように使われておりますと。… 諮問する場合は２回なんですが、その前も諮問してございませんので、年１回だけということになってあります。それで… 基本的には総務省の説明でもケーブルテレビを接続すればその端末機で、基本的にはケーブルテレビでも地上デジタル放送を受信することができるです。…","id":"exchange-095"},{"speaker":"土井委員","kind":"質問","question":"例えば先ほど言った政務調査費の問題等も入ったわけですから、この時期にあってもよかったと思うものですから、特にお伺いしたわけです。場合によっては議長が呼ばれていって説明することが必要になるかどうか、だろうなと思いますので、お伺いをしたところです。","respondent":"伊勢総務課長","answer":"昨年も１回だけ勉強会的な形で開いたわけですけれども、政務調査費の見直し状況についても報告をいたしています。","id":"exchange-096"},{"speaker":"宮崎委員","kind":"質問・要望","question":"品川区議会も４年前、法整備を含めて実行ある対策を求めるということで意見書が提出されております。こうした動きも出てきていますが、品川区もぜひ条例化したらどうかと思うんですけれども、そこのところをまず伺いたいと思います。","respondent":"阿部経理課長","answer":"今、議員がご指摘のとおり、野田市で公契約条例を決めまして、この９月３０日に公布されたということは承知しております。基本的には、委員からも出ましたけれど公契約法という法の問題ですので、まずこれは国が取り組むべき課題だと考えています。","id":"exchange-097"},{"speaker":"宮崎委員","kind":"質問・要望","question":"予定価格と落札額との差というのは実態としてどうなっているか伺いたいんですけれども、そういう資料があれば教えていただきたいんですが。それともどういうふうに認識しているのか、あるとすればどういうふうになっているのか、そこら辺の認識があったらお聞かせほしいと求めました。","respondent":"阿部経理課長","answer":"制限付き一般競争入札につきましては、平成２０年度の落札率としては９２.７％、指名競争入札については９０.１％です。もう一点、当然企業の側は利潤というものを考えていると思いますので、そういうことがあるというふうには認識しております。","id":"exchange-098"},{"speaker":"宮崎委員","kind":"確認","question":"制限付きで９２.７％、実際の予定価格と落札との差はどういうところで埋められているのかということも、あわせて伺いたいと思います。私はここが低賃金構造になってくると考えるんですけれど、区の認識はどうか尋ねました。","respondent":"阿部経理課長","answer":"それが労務単価の切り下げにつながっているという認識は持ってございません。もう一つ落札率の問題ですけれども、９２.７％というのは非常に良好な落札率だと考えています。","id":"exchange-099"},{"speaker":"宮崎委員","kind":"質問","question":"ある意味で業者の方々と一番近いはずの区が、国のほうはどういう認識で調査をやっているのかということもあわせて、認識をお伺いしたいと思います。建設４組合等は非常に大変な実態だと訴えているんですけれども、ぜひ調査してほしいと思うんですけれど、どうか尋ねました。","respondent":"阿部経理課長","answer":"先ほど申し上げましたとおり、区では平均落札率が９０％を超えておりますので、傾向として低価格入札があるという認識はございません。国の動向ですけれども、国でも今、委員がおっしゃったような低入札の動向を注視しているというふうには認識しております。","id":"exchange-100"},{"speaker":"宮崎委員","kind":"質問・要望","question":"だから、一番近い区のところでもうちょっと実態を調査してほしいと要望したわけです。安ければいいという風潮が非常に強いと思うんですけれども、先ほどの実態とは別に、そもそも論のところでどういうふうにお考えか尋ねました。","respondent":"阿部経理課長","answer":"ですから品川区でも１件施行しておりますけれども、一方では品質の確保を図っていくということで、努めているところです。そういうことを図りながら、法の適切な範囲内の中での公共工事に努めているです。","id":"exchange-101"},{"speaker":"宮崎委員","kind":"質問","question":"要するに、福祉の増進に努めているという工事で低賃金で働かされているという実態があるとすれば、それは許されるのかどうか。ここをちょっと聞いているんですけれど、どうか尋ねました。","respondent":"阿部経理課長","answer":"公共工事だからこそ区民の貴重な税金でやっていますので、それを適正に使っていくということも求められると考えています。私どものところには現在そういう状況の話は入ってきてございませんので、今そういう事例がないんだろうと考えています。","id":"exchange-102"},{"speaker":"宮崎委員","kind":"質問","question":"下請のところまでそういう調査をやっているのかどうか。そこを調査するのであれば下請のほうだと思うんですけれど、そこのところはどうか尋ねました。","respondent":"阿部経理課長","answer":"使用者と使われる方、それは契約ですので、そこまで私どもが立ち入って調査をすることが果たして妥当なのかどうか。そういう面もありますので、私どもとしては調査をしていないという状況です。","id":"exchange-103"},{"speaker":"宮崎委員","kind":"質問・要望","question":"公共工事における建設労働者の適正な労働条件を確保する、関係法の整備を図るということを、平成１７年６月に全国市長会で確認しているんですよね。改善を求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"},{"speaker":"三上委員","kind":"質問・要望","question":"１０９ページの庁舎管理、１１１ページの広報費に関しまして、少々お伺いしたいと思います。お伺いする前に委員長にお願いしたいのですが、質疑がわかりやすいという意味で、品物をちょっと提示することをご了解ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"},{"speaker":"三上委員","kind":"質問・要望","question":"台数がどれぐらいあって、充電設備的な部分はどういうふうになっているのか、お伺いしたいと思います。それから広報費のところでは、平成１９年の決算特別委員会のときに私が質問をさせていただいたんですけれども、そこら辺をお伺いしたいと思います。","respondent":"阿部経理課長、中川原広報広聴課長","answer":"次に、電気自動車はございませんので電動自転車の件ですけれども、今約２０台を所有しておりまして、職員に貸し出しを行っております。充電につきましては、現在は第２庁舎で充電をしているという状況です。 そのほかの媒体について障害者の方の対応を充実させるということで、ＣＡＴＶにつきましてもテロップの充実などを図りましてやってきたところです。ただし、今ちょっと確認しておりますが…","id":"exchange-106"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから器具そのものの値段も、通常、非常に器具そのものも高い。前の２点についてご答弁いただきたい。","respondent":"阿部経理課長","answer":"一方で、電気自動車につきましては、今後当然区としても導入を検討していく必要があるだろうと考えています。そのときに合わせまして急速充電器のあり方についても同じように、電気自動車の導入と同じようなことで検討の課題だと考えています。","id":"exchange-107"},{"speaker":"三上委員","kind":"質問・要望","question":"この１個が点灯しなくたって問題ないんですから。そういうことまで含めて検討していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-108"},{"speaker":"鈴木委員","kind":"確認","question":"先ほど５,０９０万円を還付加算金ということでお支払いしたということですが、この辺をもう一度確認させてください。５,０９０万円は品川区が払わなきゃいけないお金なのかどうか、その辺の確認をさせてください。","respondent":"武内税務課長、金子企画財政課長、阿部経理課長、中川原広報広聴課長","answer":"本税１億９,０００万円に対して加算金が５,０９０万円と先ほどご説明させていただきましたけれども、国税のほうにつきましては３月に精算したと。… 金額的には、平成１９年度が１億４,５００万円余ということで若干、微増という形であまり変わらない数字になってあります。内容としましては… そこについては許可をして張らせているということで、基本的に掲示物についてはそこに張るという方針を持っております。… それにつきましては、皆さん昼休みで１２時半から１２時５０分の間なんですが…","id":"exchange-109"},{"speaker":"鈴木委員","kind":"質問・要望","question":"還付加算金の関係ですけれど、５２０万円入ったというのはどこか、区税に入ってきているんでしょうか。ぜひこれからも、現在の品川はこんなことをやっているということを理解しておいてもらいたいなということを要望しまして、終わります。","respondent":"武内税務課長","answer":"委員が言われるとおりです。","id":"exchange-110"},{"speaker":"中塚委員","kind":"質問","question":"１７時１５分の閉会までまだ時間がありますので、質問を通告したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"中塚委員","kind":"質問","question":"１１２ページの情報公開事務費について、その手数料についてお伺いしたいと思います。まずお伺いしたいのは、２３区の中でいまだに有料を貫いているのは何区あるのか、この手数料でお金を取る理由は何かということをご説明ください。","respondent":"中川原広報広聴課長","answer":"地方自治法の第２２７条で手数料を徴収することができるというのがありまして、品川区の手数料条例で手数料をいただくということになっております。品川区全体の考え方として特定の方のためにする事務につきましては手数料をいただくということで…","id":"exchange-112"},{"speaker":"中塚委員","kind":"質問","question":"情報公開が特定の者の利益だから、いわゆる法律に基づく、できる規定ですけれども区が取っているんだというお話ですけれど、その長期計画の中でも区民の区政への参加を位置づけておりますが、住民の区政への参加、この目的は何なのかということをお伺いしたいと思います。","respondent":"中川原広報広聴課長","answer":"それにつきましては、品川区としましても区政資料コーナーをはじめとして各窓口で適切に対応しております。それについては手数料という形でいただくという、区全体の手数料に対する考え方として、この制度も運営させていただいているです。","id":"exchange-113"},{"speaker":"中塚委員","kind":"質問","question":"そこでお伺いしたいのは、区民にとっては情報がなければ意見が言えない。区政への参加を保障するためには情報がなければ参加ができないと思うんですけれど、その視点は一緒か尋ねました。","respondent":"中川原広報広聴課長","answer":"手数料は１件３００円なんです。ということで、適正な料金を設定した上で制度運営をするということでやってあります。","id":"exchange-114"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう住民参加を拒む姿勢は改めるべきだと考えています。しっかりと情報公開の手数料を無料とし、住民参加の入り口を広げてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"鈴木委員","kind":"質問","question":"その上で、この中で言うと１０番「質問者数または質問時間を調整のうえ、前段の時間の縛りということはよろしいんでしょうか。その辺ちょっと理事会の中で、今後の問題もあるので検討ほしいと求めましたが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-116"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/842680?Template=document&Id=1310#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":101954,"voices":305}},{"id":"h21-20091005-4","meetingId":"h21-c-settlement","date":"2009年10月5日","dateIso":"2009-10-05","committee":"決算特別委員会","time":"午前１０時０２分～午後５時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を132件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"そういう中で、２級取得に対する希望ですとか需要がどれだけあって、どんな見込みに沿ったものだったのかどうかの状況を伺えればと思います。そういう中での背景と経緯を伺えればと思います。","respondent":"冨岡高齢者福祉課長、安井子育て支援課長","answer":"２級になりますと、施設等で身体介護も含めて介護ができるということで非常に多くの需要があるということで今回対応させていただいた部分です。火災警報器の設置の全体の件数ですが、推計をするしかないということで… その関係で、平成２０年度のほうは、当初の見込みはなかなか立てづらいという中で、１５億３,０００万円ぐらいの当初予算を組ませていただきました。昨年の場合は、そこの段階ではまだ全体の見込みが十分に立たなかったということで…","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それとも応募というか、要望が多かったのか、もう１点伺えればと思います。その中でよく質問されるのが、当然１カ所では足りないのかなと、区としてどのようなガイドをされているのか伺えればと思います。","respondent":"冨岡高齢者福祉課長","answer":"人材確保ということとセットで１００万円、具体的には４５人、最終的に今の段階では決まっているです。それから、個数につきましては、２個ということでご案内をしています。","id":"exchange-002"},{"speaker":"武内委員","kind":"質問・要望","question":"私は１２２ページの障害者福祉費に関連してお伺いしたいと思います。この中で、大まかで結構ですので、そうしたものがどういったものがあるのかというのをお示しほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"先天的な障害ということで、医療的行為が必要なものということで、国が一貫した子どものときから大人にかけてということの役割を進めてきたものです。したがいまして、医療行為がない方についての重度の方については、私どもではすべて事業展開をさせていただいているところです。","id":"exchange-003"},{"speaker":"武内委員","kind":"質問","question":"重複ですか、おそらく城南特別支援学校ですか、残念ながら区内にはないんですと。こういうご相談をいただいたんですけれども、これについてはどのようにお考えか尋ねました。","respondent":"高橋障害者福祉課長","answer":"その方々については週１回程度ということであります。私どもでも、今後この辺の障害児の問題については重要な課題ということで考えております。","id":"exchange-004"},{"speaker":"武内委員","kind":"質問・要望","question":"障害者福祉においても、地域の自立した生活を実現していくことが求められており、新しい長期基本計画の中でもうたっていただいております。これについてはどのような検討をされるのか、もしわかっている範囲でありましたら、教えてほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"重度重複障害の療育体制の今後の検討ですが、知的障害と身体障害の手帳を両方持っている方については、２５０名程度つかんでおります。ただ、それぞれの方の状況をつかんだ上で今後重度重複の障害についても検討していくというような状況ですので、今後の課題と考えております。","id":"exchange-005"},{"speaker":"武内委員","kind":"質問・要望","question":"教えていただきたいんですけれども、その療育支援体制とあるんですけれども、この療育というのは基本的には児童なんですか。例えば今私が申し上げた１８歳以上の方については、この中で例えばそういう検討もされる可能性があるのかどうか、これを説明を求めました。","respondent":"高橋障害者福祉課長","answer":"療育というところでは、療養と教育が一緒になったという言葉で、ずっとこれは続けていく課題かと思います。ずっと生涯の対応ということで考えておりますので、障害児、者も含めまして療育支援体制ということで考えております。","id":"exchange-006"},{"speaker":"武内委員","kind":"質問","question":"そういったものについてのさまざまな委託を行うものですから、これについて２,９００万円ですか、この点について説明を求めました。","respondent":"高橋障害者福祉課長","answer":"実際上平成２１年度に行われる施設を見ますと、それぞれケアする看護師の状況とか、支援をできる方の社会的支援が重要かと思います。この辺についても、今後私どもでも可能であればこういうところも検討の１つとして考えていく必要があるかと思います。","id":"exchange-007"},{"speaker":"武内委員","kind":"質問・要望","question":"それとも先どうなっていくのかちょっとわかりませんけれども、３年間という、ぜひ積極的に取り入れていただきたいなと考えています。いわゆる居宅での介護派遣といいますか、こうしたものも可能になってくるのかなと思うんですけど、これについても見解をお願いいたします。","respondent":"高橋障害者福祉課長","answer":"居宅における重症心身障害児の対応ですが、そういう方については、現在も在宅で生活しております。支援につきましては、生活支援センターを含めまして、私どもが今後も支援していきたいと考えております。","id":"exchange-008"},{"speaker":"武内委員","kind":"質問・要望","question":"まだ結論が出てないかもしれませんけれども、いずれにしても、都から区におりてくる可能性もあります。こういった方を抱えている方たちのことをケアできる自治体で品川区があっていただきたい、このことを最後にお願いして終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前回部長が３９５人、課長は６月に４４３人と答えられているので、正確なところを教えていただきたい。この子どもたちに対する責任を持ってほしいんですが、責任に対してどうお考えか、ここを説明を求めました。","respondent":"吉岡保育課長","answer":"待機児につきましては、４月の時点で１２３名ということでお話をしたところですけれども、先ほど委員おっしゃられた数字のとおりです。再々お答えをしているところではありますが、あるいはまた、保育園入園希望者の方をお受けをしているということもあります。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"私は、認可保育園に入園できなかったお子さんへの区の責任をどう考えているのかというのをお聞きしたので、もう１回そこをお聞きしたいと思います。認証保育園が今あふれていて、私は子どもたちによりよい環境で育ってほしいなというところでは、この辺の責任に関してお答えください。","respondent":"吉岡保育課長","answer":"保育園に入所を希望されている方に対しましては、さまざまな形での保育のサービスの提供を図る中で、そのご要望にお答えするということで区としての責任を果たしているというところかなと考えています。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひもうちょっと踏み込んで考えていただきたいんですが、２３区のところ、ちょっと調べてみました。そういった面では、ぜひ品川区にも努力をお願いしたいと思うんですが、いかがか尋ねました。","respondent":"吉岡保育課長","answer":"一定の保育の水準を保たれている保育所と認識しておりますけれども、平成２０年の４月１日から認証保育所の保育料の助成制度を始めているところです。区立保育園の定員の増も図ってまいりますので、認証保育所…","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"板橋区は平成２０年から４年間で、私立の認可保育園６園増設という、今の実態をしっかり把握して先が見える計画を立ててほしいと求めました。特にきょうは４４３人、立てていただきたいんですが、もう一度お願いします。","respondent":"古川子ども未来事業部長","answer":"さまざまな施策を総合的に実施していく中で、少なくとも来年度の待機児の解消に少しでも前進していきたい、このように考えております。先ほどご説明しましたように、待機児の解消に努めている、こういうことです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一般質問で取り上げましたけれども、例として、月３万３,０００円の工賃の方が８,２００円の交通費を自己負担して施設に通っている。私はぜひ、自己負担をさせない、これ以上負担をかけない、品川区もぜひ検討していただきたい、強く求めますが、いかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"通所施設利用促進支援金という制度で昨年の７月から３,０００円プラス３,０００円ということで、６,０００円の支援金を出しています。今のところ、グループホームについては出ておりませんが、さらに把握しまして、今後検討していかざるを得ない状況かと思います。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひここに支援をしてほしいと求めました。もう１回お答えお願いします。","respondent":"高橋障害者福祉課長","answer":"今グループホームに通っている方は１３人おられます。一般就労になればというステップを踏んでいく中で、この辺についてもさらに生活の状況を把握する中で進めてまいりたいと思います。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"そして、１２８ページのＡＥＤ設置について、そして、１３１ページ、生活保護費についてお伺いします。教えていただきたいのと、空きスペースの活用について区のお考えをお伺いさせていただきたいのと、もし幾つかあったらお答えをください。","respondent":"吉岡保育課長、安井子育て支援課長、冨岡高齢者福祉課長","answer":"行政目的に沿って活用されておりますので、どのような部分で活用ができるのかも含めまして、今後の検討かなと思ってあります。… あるいは、ぷりすくーる西五反田と一体となっております地域の子育て支援センターの子育てひろばですとか。急にどうしてもいつもお子さんと２人きりでとい… 高齢者施設のＡＥＤと火災警報器の設置状況ですけれども、直営の高齢者住宅等については、すべて両方とも付いているです。…","id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"時間がなくなってしまったので、また違うところで、いろいろ質問させてほしいと求めました。１点だけ、専門調査員等報酬というのが１３１ページに記載されているんですが、そこだけ説明を求めました。","respondent":"平澤生活福祉課長","answer":"１つが就労自立支援、働き方の支援ということで、そういったことでもって就労支援をしています。資産・扶養につきましては、生活保護開始時の資産・扶養につきましての調査をさせております。","id":"exchange-017"},{"speaker":"原委員","kind":"質問・要望","question":"１２８ページ、１３０ページ、この辺についてお教えほしいと求めました。１２８ページ、１３０ページに６園と書いてあるんですけれども、これについて具体的にお教えほしいと求めました。","respondent":"宍戸施設整備課長、吉岡保育課長、安井子育て支援課長","answer":"区有施設につきましても、民間の建物につきましても、区内のすべからく建物については耐震化を図っていくというのが基本的な考え方です。… １２８ページ、耐震改修費６園の内訳ですけれども、以上の６園です。 昨年６館行いまして、一本橋児童センター、それから旗の台児童センターのほうの耐震改修を行いました。その他、施設整備ですが… 園庭の整備改修が３園、あるいはトイレ改修が２園、外壁の防水塗装等が１園というのが主な内容です。","id":"exchange-018"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、平成２０年度決算ということではないんですが、平成２０年度という考え方でもいいんですけれども、本庁舎も耐震工事をスタートしている。これが数社なのか、またある特定のところなのか、その辺をお教えほしいと求めました。","respondent":"宍戸施設整備課長","answer":"その際、評定を取得することを義務づけておりまして、したがいまして、第三者機関のチェックというのもきちんと働いていると考えています。これは、庁舎の耐震工事でも同じで、庁舎については大臣認定を取得しているものです。","id":"exchange-019"},{"speaker":"原委員","kind":"意見","question":"ずれちゃったのかもわかりません。不具合があったのか、また不法行為等が、そういう心配なものがあったか、なかったかだけで結構なので、お答えほしいと求めました。","respondent":"宍戸施設整備課長","answer":"その辺はきちっとした工事をしております。入札という形で行っておりますが、構造事務所ということで、資格を持ったところの中で選んでいるものです。","id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"それもまた私の聞き方が悪かったのかもしれませんが、数社か１社かとお聞きしたんですけれども。","respondent":"宍戸施設整備課長","answer":"数社です。","id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"私はやっぱり区の立場ですから、費用を削るということではないんですけれども、妥当性のある数字で依頼をかけているかどうか。我々はチェック機関ですから、圧力だったりとかいうことがあっては困るので、その辺についてのご意見をもう１回ほしいと求めました。","respondent":"宍戸施設整備課長","answer":"財務局のほうの基本的な経費の出し方がございまして、それに基づきましてこちらで算出したもので請け負ってもらっております。したがいまして、適正な金額でお願いしていると考えております。","id":"exchange-022"},{"speaker":"原委員","kind":"意見","question":"では、そうしますと、今後について財務局はまた考え方、その辺の路線というのは、はっきり申し上げて、診断単価ですとか、その辺、今、出てこようかと思うんですけれども、その辺の今後についてお教えほしいと求めました。","respondent":"宍戸施設整備課長","answer":"これからまた平成２２年度予算の審議の中でいろいろあろうかと思いますけれども、設計料、基本的には上がるという方向で告示が出ております。したがいまして、これまでよりは平成２２年度の委託費等については上がっていくのではないかなと考えているところです。","id":"exchange-023"},{"speaker":"浅野委員","kind":"質問","question":"１９３ページ、２０９ページ、保健事業費の健康診査費についてお伺いします。平成２１年度に入っておりますけれども、持ち越しの分ですけれども、教えてほしいと求めました。","respondent":"永尾高齢者いきがい課長","answer":"４８件のうち、１０件に助成したという状況になっております。今年度につきましては、現在のところ１７件申請がございまして、１１件が助成になっているという状況になっております。","id":"exchange-024"},{"speaker":"浅野委員","kind":"質問・要望","question":"区民の方から話を伺いまして、数字だけでは追えない部分があるかと思いますけれども、まだ残っていらっしゃる方も多分おられると思います。引き続き成立するようにしてほしいと求めましたけれども、大体高齢者向けの物件というのは何軒ぐらいあるのか、おわかりであれば説明を求めました。","respondent":"永尾高齢者いきがい課長","answer":"宅建が扱っている不動産業者の数ですが、約９０件です。情報の提供ですが、月に２回宅建のほうから区役所のほうに情報を提供するようになっております。","id":"exchange-025"},{"speaker":"浅野委員","kind":"質問","question":"窓口に来てお伺いするのか、情報源は主に何だったのかということ、このようなことを分析したことはあるでしょうか。多分広報しながわとか、いろいろあるかと思いますけれども、主な情報源を教えてほしいと求めました。","respondent":"永尾高齢者いきがい課長","answer":"は、高齢者住宅を申請された方の結果通知をお送りするときに、パンフレットと説明文書を入れているという状況です。もし入れない方につきましては、住宅あっせんの制度があるのでご紹介をいただきたいということで、ＰＲのお願いもしています。","id":"exchange-026"},{"speaker":"浅野委員","kind":"質問・要望","question":"これは要望です。後期高齢者の健診の受診率、３３.７％、計算すると出てきますけれども、同様に自己評価をしてほしいと求めました。","respondent":"本城国保医療年金課長","answer":"誕生月によって２回に分けて受診券を送ったところですが、受診をまだしていないということで、個別に未受診のご案内をしたところです。そういったものを通じて、以前よりも少しずつ受診率が向上してきているところがあると考えています。","id":"exchange-027"},{"speaker":"浅野委員","kind":"質問","question":"受診を前半でしてない人には受診券を再度発行したらどうかという質問もさせていただきまして、後半の方は、未受診の方には再発行をされたのかどうか。今年度は受診率４０％、３０％の目標になっていると思いますけれども、これに対しての方策等をお願いします。","respondent":"本城国保医療年金課長","answer":"昨年度、平成２０年度後半の方についても、未受診者の勧奨をしたかということにつきましては、それについては実施いたしております。それから、受診機会の拡大のために、受診しやすい環境づくりということで、休日健診等もあわせてやっていく予定です。","id":"exchange-028"},{"speaker":"渡部委員","kind":"質問・要望","question":"１２１ページの高齢福祉費の中で、１２２ページに移りまして、住宅用火災警報器給付事業について伺いたいと思います。今現在登録者数、どれぐらいいるのかというのを数字的な部分で教えていただきたいのと、平成２０年度１年間でどれぐらいの事業を行っていったのか。","respondent":"福島ものづくり・経営支援課長","answer":"それと、分配金ですが、こちらは１１億円余です。コーディネーターがいますので、そのコーディネーターによりまして、適格な人を探して紹介するという形を行っております。","id":"exchange-029"},{"speaker":"渡部委員","kind":"質問","question":"７,８００万円、わかりました。そこを説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"シルバー人材センターの中で行っております。そういうふうに聞いてあります。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問","question":"僕もそうなのかななんて思うんですが、実際これから先、１つ聞きたいのが、義務化されます。まだ遅々として進んでないような気がするんですが、火災警報器をつけなきゃいけないんですよというような広報をされる予定は今後ありますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"火災警報器の設置につきましては、高齢者の方が非常に火災等で被害が多いというところから、平成１９年から事業を始めたというところでございました。公営住宅につきましても、そういう形でお住まいの方はおつけになっているですので、考えていないところです。","id":"exchange-031"},{"speaker":"渡部委員","kind":"質問・要望","question":"進んでないような気がします。ぜひいま一度どこか広報を使っていただいて、告知をもう１回していただければと思いまして、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"というのがまず１点と、今まで待機児といってずっとお伺いしているんですが、入れないというご相談が本当に多く出てきたなという。今までも出てきたんですけれども、より一層出てきたということで、品川区の今後の待機児の推移をどういうふうにとらえているのかをまずお伺いします。","respondent":"吉岡保育課長、本城国保医療年金課長","answer":"今後の推移の見込みですけれども、それに伴って保育園の入園を希望される方は、一定増加傾向にあるんだろうと考えています。それを考えあわせますと、先ほど来申し上げているように… 特定健診の実施に当たりましての健康課との連携関係についてですが、まずは、どういう検診があるかということをあわせてご案内しています。特定健診のＰＲだけではなくて、あわせてがん検診のチラシを配布したり…","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、今まで私も１０年間議員をさせていただいて、保育園の増設というのはあまりなかった。もっともっと健康課と、せっかく医療のデータという形で上がってくるわけですから、いかがか尋ねました。","respondent":"吉岡保育課長、本城国保医療年金課長","answer":"待機児の解消のための取り組みですけれども、部長も答弁してまいりましたし、私も委員会等でそういうふうにお話をさせていただきました。さまざま、いろいろな施策の組み合わせの中で待機児の解消を図ってまいりましたし… 健康課のほうのお答えもあるかもしれませんけれども、先ほどの連携はあくまでも本当に入り口での連携ということでありましたので、将来的には疾病の関係のデータとして生かしていくということが必要だと思います。","id":"exchange-034"},{"speaker":"金野委員","kind":"質問","question":"順番的には高齢者等住宅運営費をお伺いいたします。細かくて恐縮ですが、ここに「高齢者等」と書いてありますけれども、高齢者住宅のほかに何か運営費が入っていますか尋ねました。","respondent":"永尾高齢者いきがい課長","answer":"建設型の３つの住宅につきましては、あとは建物の構造上の大きい工事については、直接区のほうで支出をしています。借上型につきましては、管理人への報酬と、あとは借上げの賃料について、あと、小破修理について計上しています。","id":"exchange-035"},{"speaker":"金野委員","kind":"質問・要望","question":"そこを１点確認させてほしいと求めました。借上げのほうは、管理の方がしていくというところで、見守りというところではどのように業務が行われているのか、確認をいたします。","respondent":"永尾高齢者いきがい課長","answer":"借上型住宅の見守りについてですが、ぐあいが悪くなったときにお住まいの方がブザーを押すと管理人が駆けつけるというような状況になっています。そのブザーが押されない場合につきましても、毎日の新聞やごみ出し等の状況を管理人が見るということで…","id":"exchange-036"},{"speaker":"金野委員","kind":"質問","question":"どうやら、例えば金銭的な面のところはどうかとかいう、どこら辺までなのでしょうか。線引きは難しいと思うんですけど。","respondent":"永尾高齢者いきがい課長","answer":"民生委員や在宅介護支援センターのほうにつなげたりという、また区役所のほうにご連絡があったりと、そういうような状況もあります。連絡していただけるように、こちらのほうとしても管理人に対してお話をしていきたいと考えております。","id":"exchange-037"},{"speaker":"金野委員","kind":"質問","question":"そうすると、そういった管理人との連絡協議会みたいなものというのはあるのか尋ねました。","respondent":"永尾高齢者いきがい課長","answer":"連絡会というのは現在ありますけれども、ただ、最近やったのでは、２月ごろに行っております。全員が集まるのは大体年１回から２回というところで、あとは、個々にこちらのほうに連絡をいただくというような形をとっております。","id":"exchange-038"},{"speaker":"金野委員","kind":"質問・要望","question":"年１回から２回ということで、主にこういった高齢者の方々の見守りということが話の中であるかどうかわかりませんけれども、お知らせください。そうであるならば、管理人はもっと動きやすいような状況があるのかなと思いますけれども、その点はいかがか尋ねました。","respondent":"永尾高齢者いきがい課長","answer":"現在住んでいらっしゃる方の中には部屋の片づけができないとか、においがするとか、そういうような情報も入ってきております。個人個人の状況にあわせて、区のほうで、高齢者福祉のほうにつなげるものはつなげるような対応をしております。","id":"exchange-039"},{"speaker":"金野委員","kind":"意見","question":"次に移ります。３２ページのほうにモデルケースとして大森駅前住宅、どのような形で実施されているのか、お知らせくださいとの意見を述べました。","respondent":"冨岡高齢者福祉課長","answer":"各回２０人から３０人程度、月２回の開催ということになっておりまして、今後も引き続き平成２１年度も取り組んでいっていただくと。今度は別の切り口で取り組んでいただくようになるかと考えています。","id":"exchange-040"},{"speaker":"山内委員","kind":"質問・要望","question":"まずは、私もいろいろなところでお話を伺うんですけれども、外に行くのが億劫になってしまうというようなことをよく町場でお伺いするんですけれども。ここで１つお伺いしたいのが、これの内容的な違いというんですか、まずその辺をお尋ねします。","respondent":"永尾高齢者いきがい課長","answer":"マシーンじゃなくても、チューブとか、そういう器具を使って筋力の向上を行うものです。いきいきうんどう教室のほうですが、こちらは、屋外に高齢者用の運動の器具を設置いたしまして、そこで運動をするというようなものです。","id":"exchange-041"},{"speaker":"山内委員","kind":"質問","question":"いきいきうんどう教室というのは、屋外ですか、簡単な運動ということなんですかね。ロイヤルサニーでも、やはりそういう施設を外で何か、狭いところでやっているんか尋ねました。","respondent":"永尾高齢者いきがい課長","answer":"ロイヤルサニーのほうですけれども、やはり屋外なんですけれども、屋上の高齢者用の専用の運動器具を使ってやっているということで、器具については、鈴ケ森公園と同じようなものを使っているところです。","id":"exchange-042"},{"speaker":"山内委員","kind":"意見","question":"今、大井地区ですよね、２カ所ね。それからあと荏原地区にそういう形で普及するということをお考えで、今後この事業を進めていかれるのかということをお尋ねしますとの意見を述べました。","respondent":"永尾高齢者いきがい課長","answer":"両方ともかなり好評ですので、これからも公園の改修等にあわせて設置をしていきたいと考えております。指導員の養成講座もございまして、将来的には指導員が地域のほうに出ていって、そういう運動を広めていただけるように指導しています。","id":"exchange-043"},{"speaker":"山内委員","kind":"質問・要望","question":"続きまして、１２２ページのほうなんですが、安否確認事業のことについてお伺いします。先ほど約４,５００件の家屋を対象にこの事業を進めているということで、これが１つの安否確認の何かのきっかけになるのではないかなと思うんですね。","respondent":"冨岡高齢者福祉課長","answer":"ひとり暮らし高齢者の方は、民生委員に把握していただいた部分と、それとあと住民票上の部分と２つございまして、民生委員でかかわって、高齢者相談員としてかかわっている件数で申し上げますと、７,５１９件、７,５００件強です。","id":"exchange-044"},{"speaker":"山内委員","kind":"質問","question":"そういうところに、自分に興味のあるというか、そういう興味のあるものに対しては高齢者の方って出ていかれて話を聞いたりする方が結構多いんですね。こういう事業があるんですよというのも一緒にしていくということも大事なのかなという考えで質問しますけれども、その辺はどうか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"地域で見守りネットワークと、今度それぞれの地域で取り組んでいただくところをことしは１２地域、手を挙げていただきましたけれども。そういうようなことも続けて、さらにご理解いただけるように努めてまいりたいと考えています。","id":"exchange-045"},{"speaker":"山内委員","kind":"意見","question":"それからあと１つ、１３１ページの生活保護費のことで触れさせてください。その辺のチェック体制というのをもうちょっとしっかりとやっていくべきではないかなと思うんですけれども、これを最後にお尋ねしますとの意見を述べました。","respondent":"平澤生活福祉課長","answer":"おおむね３カ月に一遍以内の方が半分ぐらいはいらっしゃいます。そういう場合には、健康問題も含めてきちんと指導させていただいているです。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問","question":"１１９ページのホームレス対策事業および生活困窮者をねらった貧困ビジネスについて幾つか伺いたいと思います。まず伺いたいのは、品川区はハウジングプアというのをご存じなのか。","respondent":"平澤生活福祉課長","answer":"これに対応するということで、この５月、政府の緊急経済対策ということで１４兆円の補正がございました。住宅手当ということで、言ってみれば生活保護費の中の住宅扶助費分を切り出して支給する、そういったような対策をこれから始めるです。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"最近の傾向としていろいろご説明を伺ったんですけれども、そして、この施設そのものが満員状態だというお話も伺ってきました。繰り返させないための対応策、抜本的な仕組みが必要ではないかと思うんですけれども、その点についてはいかがか尋ねました。","respondent":"平澤生活福祉課長","answer":"委員ご指摘の世田谷寮、こちらは、緊急一時保護施設ということで、年間で３,０００人ほどの方を受け入れています。品川区におきましては毎年５０名程度の方をお願いしているですが、簡易宿泊所等を含めまして、私どものほうでご案内しています。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問","question":"厚生部というんですか、年越し派遣村の状態を招きかねないんじゃないかと心配するんですけれども、その点はどうなのかということ。１０月４日の朝日新聞の１面に出ておりましたけれども、どういう状況なのか、ご説明いただけますか。","respondent":"平澤生活福祉課長","answer":"昨年度、派遣村ということで、１２月に５００人ほどの方が集まられて、品川区で派遣村に絡んでの申請はありませんでした。東京都が所管する、現在品川区内には４カ所の登録施設がございまして、大体１００人ぐらいの品川区の方が入っていらっしゃいます。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"今、４カ所で１００名の方というお話がありましたけれども、品川区もこうした宿泊ビジネスに紹介をしているのかどうか。品川区民の生活保護者がどういう状況で生活をされているのか、区内の様子を具体的にお伺いできますか。","respondent":"平澤生活福祉課長","answer":"一定の指導員のような方がいらっしゃるような施設、施設とまでは言わないんですけれども、そういったところにお入りいただく。私ども職員は年中行っているというのは語弊がありますけれども、よくお伺いして、ご様子等をお伺いしている次第です。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"具体的にお話を伺いましたのは、どういう部屋の状況なのか、お伺いしたいと思います。そういったお話も伺うんですけれども、あと銀行口座の管理など、状況をご説明いただけますか。","respondent":"平澤生活福祉課長","answer":"３点にわたるお尋ねです。施設のほうに送らせていただいて、それ以外のものについては、保護を受けていらっしゃる方に現金で送らせていただくということになっております。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問","question":"さくらハウスの様子を伺いますと、六人なんでしょうか、カーテンだという話も伺いました。さくらハウスの実態をお伺いしますと、生存権に照らして私は問題があるのではないかと思うんですけれども、品川区はどのようにお考えなのか。","respondent":"平澤生活福祉課長","answer":"初めにご説明しなければならないことは、緊急一時保護施設と宿泊所の違いです。そういうことになりますと、そういったことで、基本的な性格が違うということをまずお断りさせていただきたいと思います。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"お伺いしたのは、生存権に照らしても問題があるのではないのか、区はどう思っているのか。新規の住宅手当、いろいろあるわけですけれども、今のさくらハウスの状況は、望ましい施設なのか、そこをご説明いただけますか尋ねました。","respondent":"平澤生活福祉課長","answer":"そういったよい面もあると私どもは認識しております。ただ、まち中にある施設というのも、これはこれでとても大切な施設であると考えています。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問","question":"しっかりとした体制がないところにこうした、いわゆる貧困ビジネスがはびこっている。ゼロゼロ物件の実態、こうした貧困ビジネスを生み出している背景を区はどうお考えになっているのか、最後にお伺いしたいと思います。","respondent":"木下健康福祉事業部長","answer":"多方面からのご指摘ございましたけれども、この問題は一区段階で解決できる問題ではないと考えております。","id":"exchange-054"},{"speaker":"阿部委員","kind":"質問・要望","question":"そこを確認させてほしいと求めました。なぜ児童センターのみが３地域で割らずにこのままの組織になっているのか、理由を説明を求めました。","respondent":"高橋障害者福祉課長、吉岡保育課長、安井子育て支援課長","answer":"区役所の中での雇用ということで、実習という形で、そういうことを活用しながら知的障害者等の雇用については再度支援をしてまいりたいと思います。実際上… 品川区では、平成１９年度に「のびのび育つしながわっこ」という基本的な保幼小の連携を考えた乳幼児教育を目指した手引きをつくりまして。… 児童センターのほうも、こちらのほうは検討して、来年の４月に向けて３地区制にしていくという方向性で今進めているところです。…","id":"exchange-055"},{"speaker":"阿部委員","kind":"確認","question":"それから、保育園についてなんですけれども、先ほどの確認をさせてください。これは将来的にはそういったことも可能性があるという意味での答弁と受け取らせていただいてよろしいのでしょうか、もし何かあればご答弁ください。","respondent":"高橋障害者福祉課長、吉岡保育課長","answer":"８時間が適切なのかということにつきましては、個々人の状況に応じてケアマネジメントする中で自立を促すという時間数を支給決定をするというのが区の考え方かと思いますので、よろしくお願いいたします。 保育園の件についてお答えをいたします。将来のことですので、不確定な要素が残るかとは思うんですけれども、現在のところでは、幼保一体施設の整備にあわせて認可保育園を整備するです。","id":"exchange-056"},{"speaker":"阿部委員","kind":"確認","question":"ちょっとしつこいんですけれども、確認させてください。これはケアマネジメントの結果１８時間ということが出れば、上限をどこかで決めているわけではないということでよろしいか尋ねました。","respondent":"高橋障害者福祉課長","answer":"品川区の場合、重度訪問介護のところにつきましては、基本は１日８時間ということにしております。しかし、個々人の状況に応じてということになりますので、ケアマネジメントの中で支給決定をするという状況です。","id":"exchange-057"},{"speaker":"市川委員","kind":"質問・要望","question":"それと１２６ページ、ひとり親家庭の事業について伺います。それから、２００８年度に認定された方が何人で、されなかった方が何人いるのか、その辺を説明を求めました。","respondent":"高橋障害者福祉課長","answer":"１つが、知的障害者を対象とした児童デイサービス。２００８年度、昨年度に受付して、支給決定しなかったという件数は、今のところございません。","id":"exchange-058"},{"speaker":"市川委員","kind":"確認","question":"申請に行っても、申請書がもらえないで、審査のステージに乗せてもらえないというような、そういう相談があるんですけれども、今のお話だと、受付のところで受給者証を出すとか、出さないとかということが決められるというようなことなんでしょうか、その辺をもう一度確認したいんですけど。","respondent":"高橋障害者福祉課長","answer":"ご本人の状況を十分に把握した中で、ご家族の方、ご本人の状況を含めまして相談を受ける中で申請が出されるというような状況です。それが重複している場合もありますので、申請の受付というところもありますので、それぞれの相談の中で進めさせていただいているという状況です。","id":"exchange-059"},{"speaker":"市川委員","kind":"質問","question":"申請書にどうしてほしいのかとか、受給者証を発行するとか、しないとかということが決まるということか尋ねました。","respondent":"高橋障害者福祉課長","answer":"受付けないかですので、いきなり申請書が出てきて、拒否するということではございません。ですので、相談の中での申請書の受付となってきます。","id":"exchange-060"},{"speaker":"市川委員","kind":"質問・要望","question":"次の質問は、高齢者が集う場所がどういうものがいいのかということで、引きこもりを防ぐという点でも意味があるかなということを確認してきました。どういう理由があって、使用がされてないのか、その辺をお聞きします。","respondent":"永尾高齢者いきがい課長、高橋障害者福祉課長","answer":"例えば平塚橋シルバーセンターのように、もともと保健所があった施設を活用したということで、そのまま設置されたままという場所もあります。調理器具等を使っているという事業がございませんが、今後地域の高齢者の方の集う場として… 審査会というのがありますので、審査会の中で決定していくということになります。どの選択が一番いいのかということで相談の中で決めていくということが多うありますので、その辺を十分今後も進めさせていただきたいと考えています。","id":"exchange-061"},{"speaker":"市川委員","kind":"質問・要望","question":"児童デイサービスの受付のことは、申請に行った人が納得できる形をもう一度再検討していただきたいということを強く要望しておきます。それから、だれでも気軽に集えるサロンというところでの活用もどうでしょうかと思うんですけれども、考え方をお知らせください。","respondent":"永尾高齢者いきがい課長","answer":"ただし、その１部屋は、先ほどの委員のご要望のようなサロン的なものになれないというところがあります。私どものほうでも、そういうような地域のつながりができるようにこれからも支援してまいりたいと考えております。","id":"exchange-062"},{"speaker":"市川委員","kind":"質問・要望","question":"それから、保育園運営費から、短時間就労のための保育について伺います。予約制をとっているのか、また予約待ちの方がいるのか、その辺の状況を知りたいので教えていただきたいという質問です。","respondent":"吉岡保育課長","answer":"なお、１歳児から５歳児まで平成２０年は実施したところなんですけれども、５歳児については残念ながらお申し込みはありませんでした。今年度２園に拡大した形で実施をしているところですので、今年度の状況を踏まえながら、今後検討していく課題かなと考えているところです。","id":"exchange-063"},{"speaker":"市川委員","kind":"質問","question":"認証保育園では、保育料の助成を行っているんですけれども、短時間就労保育については助成が行われていないということですよね。認可保育園の短時間就労保育の保育料は収入に応じて算定されているわけですから、この辺はいかがか尋ねました。","respondent":"吉岡保育課長","answer":"こちらの短時間保育サービスについては、通常の認可保育園の保育料と同様の扱いをしています。","id":"exchange-064"},{"speaker":"市川委員","kind":"質問","question":"私の質問の仕方が悪かったのかなと思うんですけれども、認証保育園に入られている短期就労の方の保育には補助はしてないですよね。認証保育園の方の補助ということで伺ったんですけど。","respondent":"吉岡保育課長","answer":"認証保育所の件につきましては、平成２０年度から所得、収入に応じまして１万円から４万円までの補助を開始したところですけれども、短時間就労というのは、認証保育所のどの部分を指しておっしゃっているのか、よくわからないのですが。","id":"exchange-065"},{"speaker":"市川委員","kind":"質問","question":"短時間就労の方というのは認可保育園へ入れるということはないわけですよね。認証保育園に入っている、短時間じゃない方と同じように補助という考え方はできないものでしょうかということを伺ったんですけれど。","respondent":"吉岡保育課長","answer":"認証保育所に入っておられる方については、就労形態を問わず入所していらっしゃるということで、補助はさせていただいているところです。短時間保育室については、短時間就労という就労形態の多様化に対応した保育ニーズにこたえるということで実施してございまして。","id":"exchange-066"},{"speaker":"市川委員","kind":"質問","question":"その推移というんですか、増えているのか、減っているのか、その辺、お聞きしたい。それから、父子家庭からの相談というのはどういうものがあるのか、説明を求めました。","respondent":"安井子育て支援課長","answer":"父子家庭の数ということなんですけれども、ひとり親家庭の医療費助成事業のほうをやっておりますので、そちらの関係でいいますと、５１世帯７１人というような形で把握しています。","id":"exchange-067"},{"speaker":"若林委員","kind":"質問・要望","question":"ここら辺の数と主なものを教えていただきたいのと、または共通商品券とこの２つの選択なんですが、これの内訳について伺います。登録の人数が当初の１,０００人から６２９人の登録ということで、ここら辺、評価について伺いたいと思います。","respondent":"高橋障害者福祉課長、永尾高齢者いきがい課長、冨岡高齢者福祉課長","answer":"１２０ページの５つの品川総合福祉センターから三徳会の間の５つですが、１つ目の品川総合福祉センターについては、私のほうでお答えします。高温水… ５０ポイントの達成者の人数ですが、１１６人でございまして、商品券にかえた枚数ですが、１,８９４枚です。… 各種助成金の品川総合福祉センターを除く部分です。それから三徳会につきましては、在宅サービスセンターの送迎車の車両購入費の部分の助成というところで…","id":"exchange-068"},{"speaker":"若林委員","kind":"質問","question":"今後の発展についてぜひお話を伺いたいんですが、当初平成２０年度においては、介護予防ということを主に置いておりました。今後の展開、発展の仕方についてお考えを、現時点での評価をもとに伺いたいと思います。","respondent":"永尾高齢者いきがい課長、冨岡高齢者福祉課長","answer":"まだあまり浸透していない部分もありますので、今年度は２年目になっておりますので、いろいろな場所でＰＲをしていきたいと考えております。介護保険の地域支援事業ということで、都… 法人につきましては、施設建設のときに、国等の補助金をもらい、あわせて福祉医療機構から借り入れをした。社会福祉法人の基盤を安定させて、区民に良好なサービスを提供していただく、そういう趣旨で対応しているものです。","id":"exchange-069"},{"speaker":"若林委員","kind":"質問・要望","question":"社会福祉法人の在宅介護支援センターが赤字の運営が続いているという確認をひとつさせていただいて、そのほかの４カ所がいわゆる株式会社立。そこはぜひ地域の高齢者のサービスのためにもご一考いただきたいなという意味で、そこら辺の質問をさせてほしいと求めました。","respondent":"永尾高齢者いきがい課長、冨岡高齢者福祉課長","answer":"昨年度から始めまして、各自治体から視察等もたくさん来ておりまして、先進的な事業だと各自治体からも評価をいただいているところです。一応制度の中では、今後ボランティア活動をさらに広げるよう… 在宅介護支援センターにつきましては、予防の支援でありますとか、今の運営費につきましてもう一度見てまいりたいと考えています。","id":"exchange-070"},{"speaker":"若林委員","kind":"意見","question":"では、運営費については、また見直し、これは常に見直していくということだと思いますので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"伊藤委員","kind":"確認","question":"改めて品川区に確認しておきたいのが、行政がさまざまな形で介入することで、ご本人の自立を促す。この両方があると思っているんですが、その入り口の確認をまずお願いいたします。","respondent":"平澤生活福祉課長","answer":"委員ご指摘のとおり、生活保護法の目的のところに、まず初めに国民としての憲法に保障された生存権の保障、それと自立の支援、これが２つの車の両輪です。","id":"exchange-072"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そういう方が果たしてどれぐらいいらっしゃるかということをわかれば教えていただきたいのと、就労、社会生活。そういう目標を持って、全く違う観点で行政も展開していく必要があると思うんですが、いかがか尋ねました。","respondent":"平澤生活福祉課長","answer":"委員ご指摘のとおり、私どもといたしましても、さまざまなチャンネルを通じて就労の支援をしています。午前中にご答弁させていただきました就労支援に関する専門員等の活用によりまして、平成２０年度、就労を開始したものが１０３世帯で１８０人。","id":"exchange-073"},{"speaker":"伊藤委員","kind":"質問・要望","question":"こういう方々は本当に頑張って自立されたわけですから、皆さん頑張ったんですよということをぜひＰＲしていっていただきたいなと思います。当然担当部署としてお伺いしたいのが、そのことに対する改めてのお考えと、実質の資産等の確認の内容について説明を求めました。","respondent":"平澤生活福祉課長","answer":"その説明責任と申しましょうか、区民の方のご理解を得られなければ、制度そのものが危うくなってしまう。例えば社会福祉協議会で実施しておりますさまざまな資金、障害者の手当を受けていただくとか、そういったことをご案内申し上げています。","id":"exchange-074"},{"speaker":"伊藤委員","kind":"質問","question":"こういう１つの成功例があるわけですから、例えば品川区が１つのチームなりで対処していただいて、当然あるわけでしょう。そういう構想をしてみてはいかがでしょうかということで質問します。","respondent":"平澤生活福祉課長","answer":"委員ご指摘のとおり、ホームレス、路上生活者の方の居所を定めていただくということは、私どもの課題として十分に認識しています。私どもといたしまして対応しているというのが現状でございまして、平成２０年度につきましては、平成１９年度と比べまして少し減りまして。","id":"exchange-075"},{"speaker":"高橋委員","kind":"質問","question":"数字をお聞きしたので、それからあと平成１８年、平成１９年の今の３カ所の施設に入っている方の人数をお尋ねしたい。区外に１８０人、今年度入られているわけですが、この現状をどのようにお考えか尋ねました。","respondent":"高橋障害者福祉課長","answer":"ここの方についても、安定した生活を崩すということもなかなか難しいので、そのまま継続して区外施設を利用していただいているという状況です。したがいまして、それぞれのご本人、またご家族の状況に応じて、それぞれ施設のご案内を申し上げている状況です。","id":"exchange-076"},{"speaker":"高橋委員","kind":"質問","question":"とすると、品川区の方が他区の施設に入られていることがあるんですが、逆に品川区にある知的障害者の方の入居施設に品川区以外の他区の方がいらっしゃるという状況であるとすると、どのぐらいいらっしゃるのか尋ねました。","respondent":"高橋障害者福祉課長","answer":"知的障害者の施設で他区から来ている方は２人です。はすべて区内に住所がある方です。","id":"exchange-077"},{"speaker":"高橋委員","kind":"質問・要望","question":"今２名の方が、そういったご要望等あると思うんですが、何とか区内でそういった施設に入っていただけるような状況をとっていけるのか尋ねました。","respondent":"高橋障害者福祉課長","answer":"この方については、どこの施設とか、まだ将来があるんですけど、利用したいというご希望の方で、相談を継続しているというような状況です。外から私どもの区内の利用をしたいという状況につきましては、今のところ、ご相談は私のほうには聞いておりません。","id":"exchange-078"},{"speaker":"高橋委員","kind":"意見","question":"そういう評価を踏まえて、このような公設民営の形態についての今後についてどのようにお考えになっているか、ご答弁をお願いいたしますとの意見を述べました。","respondent":"吉岡保育課長","answer":"十分な貢献をしていただけるように、こちらから区としてもお話をするとともに、ぷりすくーる西五反田側にも努力をしていただきたいと考えているところです。","id":"exchange-079"},{"speaker":"高橋委員","kind":"質問","question":"ぷりすくーる西五反田の成果を踏まえてほかのそういった施設に生かして行ってというか、施設をどうするかということをお聞きしたいのですが、時間がないので、これで、次回に回したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"宮崎委員","kind":"質問","question":"私は成果報告書１７９ページの国民健康保険と２１３ページ、あと時間がありましたら２０５ページ、この３つの特別会計で伺いたいと思います。そこら辺のところはどうなっているのか、今、国民健康保険がこういうふうな状況になっているというのを説明ほしいと求めました。","respondent":"本城国保医療年金課長","answer":"国民健康保険の加入者７５歳以上の方については、従来９８％程度の高い収納率の方でございましたので、その分の低下だと見ておるところです。現時点におきましては、失業に伴って大きな国保への移行までは現時点ではまだ認められていないと考えているところです。","id":"exchange-081"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この扱いをどういうふうにやっているのかというのを伺いたいと思います。社会保険から国民健康保険に入ってきている、そういう傾向が引き続き強いのかどうなのか、そこら辺のところをお伺いしたいと思います。","respondent":"本城国保医療年金課長","answer":"２３区共通で保険料について検討していますが、平成２３年度に旧ただし書き方式に移行するということで、検討を進めているところです。それに伴って急激に変動することがないように、経過措置等について今検討して、最後の調整をしています。","id":"exchange-082"},{"speaker":"宮崎委員","kind":"質問・要望","question":"５割減免とか、どういうふうに運用しているのかなというふうに聞いたつもりなんですけれども、そこのところをお伺いしたいと思います。夫婦２人に子ども２人の４人で、例えば４００万円ぐらいの収入の方だとどのぐらい増える、そういう試算というのはされているのか尋ねました。","respondent":"本城国保医療年金課長","answer":"今まだ検討の途中ということでございまして、最終的に、平成２３年度を１つのめどとしながら今検討をしています。具体的数値を持ち合わせていることはありませんが、その点、扶養者が多い方等について検討するものが多いということが言えるかと思います。","id":"exchange-083"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、ここのところは、収入が少ない、払う人が困難な場合には、減免制度を大いに活用していただきたいということを要望しておきたいと思います。実際に品川区の影響がどうだったのかということと、どういうふうにしているのか、伺っておきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"それを抑制するために、積立金を当てはめながら保険料を抑制していくという形で、第４期３,９００円に落としたです。ことし３億円積んだわけですが、２３億円、すみません。","id":"exchange-084"},{"speaker":"宮崎委員","kind":"質問","question":"２３億円に来ているということなんですけれども、さっき伺った介護従事者のほうなんですけれども、どういうふうになっているのか。そういう趣旨で生かされているのかというのはどうなんか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"実施していると聞いております。あわせまして、国が臨時基金をつくりまして、１人当たり１万５,０００円ということで交付しているというところでもあります。","id":"exchange-085"},{"speaker":"山路委員","kind":"質問・要望","question":"私のほうから２点ほどお伺いします。１１９ページ、成年後見制度事業と１２１ページ、おとしよりと子どものふれあい事業についてお伺いいたします。","respondent":"冨岡高齢者福祉課長、永尾高齢者いきがい課長","answer":"利用支援事業ですが、家裁による決定によりまして、その申立者に対して求償をする。その部分のための経費です。 それにつきましては、３３校で実施いたしました。こちらにつきましても、小学校１校ですが、小学校６年生の子を連れて実施いたしました。","id":"exchange-086"},{"speaker":"山路委員","kind":"質問","question":"こういう非常に難しい面が過去にあったんですけれども、今後はどういうふうな展開をしていけるのか。そういう新しいアイデアも今後取り入れていったらどうかと思いますが、それぞれどのようにお考えですか、お伺いいたします。","respondent":"冨岡高齢者福祉課長、永尾高齢者いきがい課長","answer":"いろんな実施をしている部分でありますが、あるいは公正証書の遺言作成支援ということで、よく被後見人とお話をしながら進めてまいりたいと考えているところです。 おとしよりと子どものふれあい事業ですが、シルバーセンターを中心にいろいろ交流の事業を幅広く広げているところです。シルバーセンターを活用いたしまして、いろいろな地域の小学校と中学校と連携しながら…","id":"exchange-087"},{"speaker":"山路委員","kind":"質問・要望","question":"任意後見は、法的なこととか、いろいろありますけれども、これからスムーズに成立がいくようにさらに期待しております。情報を提供したり、いろんなことにつながっていくと思いますので、新しいアイデアをまた考えていただきたいことを要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"川西委員","kind":"質問・要望","question":"これは私が申し上げるまでもありませんが、ここの利用者にとっては、同じような助成が対象になっていないのかどうか、伺います。先ほども出ていましたその他の民間の保育所も大変飽和状態がより拡大していくという状況ですから、区内の区立保育園をもう１回、利用枠の拡大。","respondent":"冨岡高齢者福祉課長、福島ものづくり・経営支援課長、吉岡保育課長、安井子育て支援課長","answer":"現況の部分につきましては、通常の入所調整の中で対応しています。それから、特別養護老人ホームにつきまして、東京都の第三者評価の受審ですが… こちらにつきましては、第三者評価そのものは行っていませんけれども、補助金が入っている関係で、都および区からの監査を行っているものです。… それから、それから１１月には荏原保育園５名プラス大井保育園で５名ということで、合わせて１５名の緊急対策の一時保育の枠をつくりました。… 新規で９６５名ぐらい、平成２０年度の場合あったんですけれども…","id":"exchange-089"},{"speaker":"川西委員","kind":"質問・要望","question":"チャイルドステーションがさらに充実してほしいと考えている１人ですので、広いところですから、どうにでも改善できるのだと思います。それで３０名になってしまったのかなと思いますけれども、その辺の所管課の認識はいかがなものか尋ねました。","respondent":"吉岡保育課長","answer":"何分、設置をする場所によって一定の施設的な制約がありますので、その中で事業者として最大限の努力をした結果が３０人という定員だろうと考えているところです。","id":"exchange-090"},{"speaker":"林委員","kind":"質問・要望","question":"７５歳以上の方々の医療費が大変かかって、１年振り返って、目標にしていた改善がされたのかどうかを聞かせてほしいと求めました。これも１行だけの話で細かいんですけれども、ご説明をほしいと求めました。","respondent":"榎本人事課長、本城国保医療年金課長","answer":"マイナスが１億９,５９８万８,８１４円のマイナスということで、人数は２人増えているんですけれども、金額的にはマイナスになるというものです。事業主負担のほうの部分が、例えば国保会計ですと… 私のほうからは、後期高齢者医療制度が導入されて、当初の目的にかなった形になっているかという関係でご説明します。こちらについては、郵送費ということだけではなくて…","id":"exchange-091"},{"speaker":"林委員","kind":"質問・要望","question":"そうすると、やめられることに対しては、区長会で反対すべきじゃないかなと。いきなり区長が答えるにわけにはいかないんでしょうけれども、副区長でもわかったらお話を聞かせていただきたいですけど、。","respondent":"濱野区長、榎本人事課長","answer":"これは組織的に対応すべきだろうと思うわけでありますけれども、要望いたしました。そういうことを要望し、それは大体受け入れられという認識で横尾会長はお帰りになって、記者会見をやっております。 先ほどの民生費８１億円の中には、非常勤の職員等報酬１,５７０万円を含んでおります。","id":"exchange-092"},{"speaker":"林委員","kind":"質問","question":"あの保育園とぷりすくーる西五反田とのこれからの関係をどうするのかということも出てくると思うんですけれども、その辺について、教えてください。それで終わります。","respondent":"吉岡保育課長","answer":"のびっこ園台場ということで、２園の幼保一体施設がございまして、こちらも同じように区立幼稚園プラス……〔時間切れにより答弁なし〕。","id":"exchange-093"},{"speaker":"西本委員","kind":"質問・要望","question":"以前から要望はしておりますけれども、大体一貫校の学校では、そのときが一番制服等々の購入をしなければならないということで経費がかさむ。これを何とかしていただけないかという要望をしているわけですが、それの経過報告をしてほしいと求めました。","respondent":"平澤生活福祉課長","answer":"生活福祉に絡む小中一貫校標準服の購入についてご説明します。そのほかにはございません。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"これはこの款で聞くことではなかったのかどうかですけれども、５年生のときが、中学生は就学援助という形で、支度金というのがあると思うんですが、ここの中に入るのかなと思って聞いてはいるんですが、款が違うのであれば、そこでお聞きしますけれども、それだけお答えください。","respondent":"平澤生活福祉課長","answer":"私ども、民生費でご説明しているのは、失礼いたしました、１３２ページにあります小中一貫校標準服購入費ということで、生活保護世帯に限った助成です。","id":"exchange-095"},{"speaker":"西本委員","kind":"質問・要望","question":"貸付を幾らか出していると思うんですけれども、それを品川区に返したときの最終的に財産と考えたときに、どういう区割りになるのでしょうか。区の財産はどこまでで、民間の、今はこうほうえんになると思うんですが、どこまでになるのでしょうか、お答えほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"こうほうえんの旧原小学校跡の施設ですけれども、土地と建物の躯体につきましては、区のほうです。造作をした部分は、法人の造作物ということになります。","id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"では、今の建物の持ち物の責任というんですか、どこがどこの部分を持っているのか。要は、建物については、区の部分と、それからこうほうえんの部分があるという認識でよろしいのか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"建物の部分は、区のものと新たに付加したものは法人のものと、そういう形に協定でなっております。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"今はそうじゃないと思っていますけれども、そういった場合に、この施設はどういうふうな形になってしまうのでしょうか。企業のものの部分があるわけですから、そこまで考えた形で契約をされているのか、お聞きしたいと思います。","respondent":"木下健康福祉事業部長","answer":"その工事をした主体が所有するというのが一般的な考え方ですが、ただ、そこの部分については話し合いをするということになろうかと思います。途中でというお話がありましたけれども、大変経営的にも安定しているところですので…","id":"exchange-098"},{"speaker":"西本委員","kind":"質問・要望","question":"先々を考えたときに、品川区としてはどういう考え方を持ってやっていくのかというのを整理していったほうがいいんじゃないかなと考えています。同じかどうかわかりませんけれども、こういった形の施設というのは品川区にはどれだけあるものなのか教えてほしいと求めました。","respondent":"木下健康福祉事業部長","answer":"例えば八潮南の特養については、これは区立の指定管理という方向で考えておりますので、施設の使用の仕方の形態としては違うものになっているということです。","id":"exchange-099"},{"speaker":"西本委員","kind":"質問","question":"品川区にあるわけですから、いろんな施設との関係とかという、そういう関係がどこまで持てているんだろうかなと非常に疑問に思うことがあるんですね。今後の業者を選定する際の考え方をお聞きしたいと思います。","respondent":"木下健康福祉事業部長","answer":"ただし、品川区とこうほうえんの間では協定書も結んでいますし、区の考えているようなサービスを提供してもらうような体制をとっております。そういう点でいうと、全く私は問題がないと思っておりまして、その中で……〔時間切れにより答弁なし〕","id":"exchange-100"},{"speaker":"須貝委員","kind":"質問・要望","question":"特にゼロ歳から２歳児までは子どもを預かってくれる保育園施設というものは、区民もそうですが、切実な要望だと考えております。これは品川区の保育を受けたいというような要望がこの２３区の中で、品川区の認識、見解はどのようにお考えか尋ねました。","respondent":"吉岡保育課長","answer":"先ほど来ご説明していますけれども、さまざまな方策をとる中で、その要望にお答えをしていかなければいけないと考えているところです。一面、今現在住んでいらっしゃる区民の方のご要望に最大限お答えするという中では、ちょっとつらい面もあるかなと考えているところです。","id":"exchange-101"},{"speaker":"須貝委員","kind":"意見","question":"その割合を国が３.１％、都が２.２％、利用者が１２.８％、品川区は８１.１％、要は８割以上も負担しているという実態があります。税配分の公平さというのはあると思うんですが、その辺に対して区のご見解を説明を求めました。","respondent":"吉岡保育課長","answer":"区民の方が優先されるというのは当然そういう考え方だろうとは思いますけれども、保育に欠ける状況の中で、一定の申し込みはできるという状況かなと考えています。","id":"exchange-102"},{"speaker":"須貝委員","kind":"意見","question":"区民の税金を使う、区の予算を使うということでは、私はそれはぴしっとやるべきじゃないかなと思います。２３区の保育サービスが均一ならばおそらく問題はないと思うんですが、品川区に多くの方が、その辺についてもう一度見解を説明を求めました。","respondent":"吉岡保育課長","answer":"大変失礼いたしました。一応今の児童福祉法の考え方では、お気持ちは重々わかるんですけれども、なかなか難しいところがあるかなと思っているところです。","id":"exchange-103"},{"speaker":"須貝委員","kind":"質問","question":"皆さんの税金を有効に、そして適切に区民サービスに投入するということは、私は基本の理念だと思います。その辺について、企画財政課はどういうふうにお考えなのか尋ねました。","respondent":"金子企画財政課長","answer":"それぞれの事業の中で要件が定められていて、住所要件の考え方もさまざまあるだろうと考えております。ですので、１つの研究する課題として受けとめさせていただければと思います。","id":"exchange-104"},{"speaker":"須貝委員","kind":"質問","question":"もっと資金もそうですが、特に人件費、人が大切な１つの大きな要素だと思います。その点についてご意見を、ご見解を説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"地域の高齢者の方のために、我々は全体のバランスを考えた職員の配置で、区内に１９カ所あります在宅介護支援センターと連携をとりながら、そちらの力も頼りながら、連携をとりながら、今度も、区民の高齢者の方にできるだけご相談に乗っていきたいと考えているところです。","id":"exchange-105"},{"speaker":"堺委員","kind":"提案","question":"私、中途失聴者や難聴者のための施策の拡充についてお尋ねをした経緯がありますので、その辺について何点か確認をさせていただければと考えています。その辺はいかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"平成１８年の障害者自立支援法ができた段階で、中途失聴者、難聴者への派遣についても考えていかなくてはならないのかなと思います。その辺につきましては、今後検討してまいりたいと思いますので、よろしくお願いします。","id":"exchange-106"},{"speaker":"堺委員","kind":"質問・要望","question":"非常にやさしい課長ですから、そういう気持ちは十分に、今でもそういうお言葉が口から出てくるのではないかという期待をしているんですね。ぜひ検討していただきたい、こう思うんですが、もう一度この件についてお考えをお聞かせいただけませんか。","respondent":"高橋障害者福祉課長","answer":"聞こえにくくなった方にとって、手話通訳ができなかったり、情報が入ってこないということの困難性は十分承知しております。その辺につきましては、いろいろな多方面を考えた上で、この事業については進めていくということで検討をしていきますので、よろしくお願いします。","id":"exchange-107"},{"speaker":"堺委員","kind":"質問","question":"それから、時間の関係で、２点目ですが、成果報告書１２１ページのしながわ出会いの湯、これに関連して、簡単で結構です。成果報告書のところに若干書いてはありますが、その辺のところを教えていただけますか。","respondent":"山岡健康課長","answer":"昨年は３５カ所の公衆浴場で実施させていただきました。これは近隣の大田区、目黒区、世田谷区あたりから比べると、よく頑張っている数字だと考えています。","id":"exchange-108"},{"speaker":"堺委員","kind":"提案","question":"課長は、組合とお話をできればとお答えをいただきましたので、その後の経過について教えていただけますか。ぜひ設置していただきたいと思っておるので、状況を教えていただけますかとの意見を述べました。","respondent":"山岡健康課長","answer":"ＡＥＤの設置につきましては、管理をしっかりやって、常時使える状況にしておかなければなりません。あるいはバッテリーは４年ほどで交換、本体は７年ほどで交換しなくてはいけないですので、その辺を含めて相談をしていきたいと考えております。","id":"exchange-109"},{"speaker":"須藤委員","kind":"質問","question":"それから、受診件数が約６２万件で、１６.６回というのがお子さんたちが１年間にかかる件数がこうですよというふうにとらえていいのかどうか。それから、ＡＥＤの設置をしていただいているんですけれども、品川区で過去に使用した例があるのかどうか、その点を聞かせてください。","respondent":"永尾高齢者いきがい課長、安井子育て支援課長、山岡健康課長","answer":"シルバー成年式ですが、過去５年間を見てみますと、年々参加率は減少の傾向にあります。今年度につきましては、対象者数が３,１３９人でございまして… こちらについては、健全な発達というか、そういった意味でこれを使わせていただいております。児童手当のほうもそうなんですけれども… 八潮北公園で実際に倒れた方がいて、使って無事に蘇生したという、そういうふうなご連絡を所管のほうから受けております。それ以外は…","id":"exchange-110"},{"speaker":"須藤委員","kind":"質問","question":"それから、子どもすこやかのほうは、先ほど１６.６回という数字が１年間のお子さんの件数でいいんですかという質問をしたんだけど。日本語として乱れているんじゃないですかというので、教育長にこういう言葉、いいんですかというのを聞いてみたいと。","respondent":"永尾高齢者いきがい課長、安井子育て支援課長","answer":"特に今年については、生まれた年を考えますと、今までと同じような考え方ではいけないなと私も思いました。今回、アンケートをとっておりますので、そのアンケートを見ながら、また新しい企画を考えていきたいと考えております。 答弁が漏れまして申しわけございませんでした。大体１６回、１５回、ここ数年そのくらいの回数が続いているところです。","id":"exchange-111"},{"speaker":"須藤委員","kind":"質問","question":"現代では逆に病院で亡くなる方が８割という数字になってきて、この制度が入ったことについて、行政側はどういう感覚を持たれたのか。僕ら自身が急激な変化に対してどういう認識を持つんだということまでしっかりＰＲする必要があると思うが、いかがか尋ねました。","respondent":"安井子育て支援課長、本城国保医療年金課長","answer":"今後関係の機関と十分検討して、そこら辺の連携を図りながら、こちらの事業についても考えていきたいと考えています。よろしくお願いします。 その意味で若年者と高齢者に明確な割合の中で、お一人おひとりに保険料をお納めいただいたりしている制度の中で進んでいるところです。仕組みの形の上の説明ということが基本になっていた面もあるかと思いますが、そんな中で…","id":"exchange-112"},{"speaker":"須藤委員","kind":"質問・要望","question":"我々の年齢からしっかりと考えるような意識を区民の方々に理解を求めていくという考え方をつくっていくべき必要があると思うんですけれども。大往生ということをどういうふうに考え、とらえてくるんだとか、そのあたりはどういうふうに考えているのか。","respondent":"木下健康福祉事業部長","answer":"例えば成年後見の任意後見についての説明会をやりますと、その証左だと考えていますので、こういう事業を進めていく中で。その他機会があれば、啓発の場というものも検討していきたいと考えています。","id":"exchange-113"},{"speaker":"須藤委員","kind":"意見","question":"この後期高齢者医療制度というものといろんなものがつながってこないと思うので、そういったものの考え方というのはどういうふうに思っているのか。長野県というのは非常に長寿であるし、そのあたりはどういうふうに評価をしているのか、最後に説明を求めました。","respondent":"山田副区長","answer":"そういう講座をお持ちになって、ボランティアの方々、医療系の方々に対して講座をずっと組んできております。今おっしゃったように、自分たち一人ひとりの生き方そのものを問いながら、より良い死に方を考えていくということが大事ではないかと考えています。","id":"exchange-114"},{"speaker":"土井委員","kind":"質問・要望","question":"金返せという返還を求めるという場合だとか、最後は保険医の指定を取り消すとか、そういうのがどうなっているかということをお伺いしたいと思います。例えば１８９ページには、この借料のところはどこにくっついていくのかということもあって、お伺いをいたします。","respondent":"吉岡保育課長、本城国保医療年金課長","answer":"先ほどお答えいたしましたとおり、一定の認証保育所についても面積基準がありますので、そこから来るものが大きいのかなと考えているところです。従来から区で考えていますのは、預かり保育を実施していただいておりますし… 例えば平成２０年度でいいますと、合計６,９９０万円ほどの診療報酬を誤ったということで、結果的に安く済んだという形で効果が出ているところです。６台ほどの機械、それを活用して…","id":"exchange-115"},{"speaker":"土井委員","kind":"質問・要望","question":"心理的効果等があって、そこら辺、どのようにお考えになっているかなということを伺わせてください。要するに、そこまでしか初めから考えないで３０人の場所を探していくことなのか、その辺を聞かせていただきたいと思ったわけです。","respondent":"本城国保医療年金課長、吉岡保育課長","answer":"７,０００万円弱の効果に対して同額のものがということだったかと思うんですが、７９０万円ということで、約１０倍ぐらいの効果という形になっているところです。 ３０人という園も確かにありますが、多いところは５８人とか６０人とか、待機児の解消のためにはなるべく多く入れていただければと考えているところです。","id":"exchange-116"},{"speaker":"南委員","kind":"質問・要望","question":"２段階下がったとか、クラスというんですかね、段階的な数字も教えてほしいと求めました。これに伴って、経過措置という形で、９月末日までそういう措置がとられましたけれども、この経過措置を受けた方々の人数も説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"そのうち軽度化ということでは、３８９件です。内訳は今手元にございませんが、その中で、引き続き経過措置を希望された方は、５８名です。","id":"exchange-117"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ内容も含めて、後で教えてほしいと求めました。それから、どういうふうな対応をしなさいという情報提供、これがどういうふうにあったのかというのをまず知りたいと思うんです。","respondent":"冨岡高齢者福祉課長","answer":"新しいテキストということでご説明をしているというところでありますので、制度の変わり目にはちゃんと事前に説明を申し上げて、それから今回の１０月１日からの部分についても当然事前に９月に説明会をしていると。","id":"exchange-118"},{"speaker":"南委員","kind":"質問","question":"大腿骨を骨折しているので、１０分も立っていることができないということで、魚を焼くぐらいがせいぜいだとおっしゃるんですね。週４回５時間のヘルプサービスを受けているけれども、こういう現状を区としてどういうふうに認識しておられるのか、まずそこを伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"個々の制度の改善につきましては、今回の１０月１日から、訪問員のテキスト、調査員のテキストも変わりましたので、それで対応されているようです。それに基づきまして今後とも適正な認定審査と給付に努めてまいりたいと考えております。","id":"exchange-119"},{"speaker":"南委員","kind":"質問・要望","question":"これは確かな事実ですから、改善を求めていくということを強く要求したいと思っていますが、その点についての認識を改めて伺います。ことしの４月と１０月の時点でどのくらいあって、待機者がどのくらいなのかという、その数字をまず伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"特養ホームの入所調整の状況ですが、平成２０年度につきましては、９月分が、審査をした数が４９５人、それから、今年３月ですが、４９１人、それから入所者数が３月の時点で９８３人です。","id":"exchange-120"},{"speaker":"南委員","kind":"確認","question":"今の数字、ちょっとわからなかったんですけれども、３月の時点では４９１人が申請して、入所が九百幾つとおっしゃったんですか。ちょっとその辺、確認したいと思います。","respondent":"冨岡高齢者福祉課長","answer":"事前にご説明申し上げて、下がる場合には経過措置ができますよということで対応していることでございまして、そういう形の了解をいただいているです。それから、最後申し上げました、人数につきましては、これは年度末の入所者、入所している方のトータルの数字です。","id":"exchange-121"},{"speaker":"南委員","kind":"質問・要望","question":"私の質問がきちんとお伝えできなかったのか、わかりませんけれども、時間の関係できょうはちょっとまたの機会にしたいと思いますけれども、きちんと入所の状況を教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-122"},{"speaker":"三上委員","kind":"質問","question":"それから、視覚障害の方で、３級から６級まで程度はあると思うんですけれども、それでよろしいでしょうか。そこらあたりをお伺いしたいと思います。","respondent":"高橋障害者福祉課長","answer":"ＳＰコードということで、活字文書読上げ装置が支給されている件数ですが、平成１５年に私どもの日常生活用具ということで支給を開始しました。それと、視覚障害者の級ですが、委員おっしゃるとおり、６級まです。","id":"exchange-123"},{"speaker":"三上委員","kind":"確認","question":"広報のほうでどこまでやっていますかと伺ったわけですけれども、どなたかに送る場合に、郵便物の第四種ということでしょうか。品川区の職員の間で、こういったことに対しての認識を深めていきましょうという研修会は行われていますでしょうか、どうか尋ねました。","respondent":"高橋障害者福祉課長","answer":"申しわけございませんが、職員向けの研修ということは現在やっておりません。対応している障害者生活支援センターの相談員とか、日常業務の中でのどういう対応をしていくかというところでのレベルアップは図っておりますが。","id":"exchange-124","title":"議員研修会の内容と所要時間"},{"speaker":"三上委員","kind":"質問・要望","question":"そこのところの情報がそういうふうにして来ているわけですから、お金もついてきているわけですから、それを積極的にやっていってもらいたい。こういうことですから、品川区もそういった意味にあって、どうするかということについて、その姿勢として、残り時間ご答弁いただきたい。","respondent":"榎本人事課長","answer":"研修はいろいろと手法はありますけれども、所管とも十分相談して、補助等もあるということで、そういうものを活用しながら、十分工夫して成果が上がる研修を検討していきたいと考えております。","id":"exchange-125"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから福祉施策と全体的な協働という意味で確認をしていきたいのが１点、２１９ページ、１件ずつ。その奥様というのは、その方でさえわからなかったというのはどういう意味だかちょっと理解がいかなかったので、その辺ご説明ほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"お話の趣旨からしますと、例えば認定審査会が３０日ぐらいで認定が決まるというところが、延びますという通知ではないかと理解したところです。１カ月で間に合わないという状況がございまして…","id":"exchange-126"},{"speaker":"鈴木委員","kind":"質問","question":"これは私も何回か今までも質問させていただいているんですけれども、たしか平成１４年６月から入って、事業費１,１００万円という数字が出ています。常にここ何年間かたしか１,１００万円という予算、私も質問、区としての考え方を説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"これにつきましては、１,１００万円ということで、人件費相当と、それから、運営費の一部補助をするです。もともと全体をカバーするということではありませんし、対応していると、今後もそれで対応していければと思っているところです。","id":"exchange-127"},{"speaker":"鈴木委員","kind":"質問","question":"手元に資産がある、資力のある人ならいいんですけれども、資力のない人の場合、その部分をどうやって後見人にお金を払っていくのか。そこら辺を今後考えたとき、区の必要性は出てこないでいいのかどうか、そこを説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"補助しているということは、たしか平成２１年度の初めからやっておりますので、その部分で社会福祉協議会の中で回していただけるということで理解をしています。","id":"exchange-128"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう１点目、お年寄りと子どものつながりというものが、実際この半年間ぐらいで何かうまくいき出したのかなと。いってほしいなという思いの中で、どんな状況になっているかお答えをほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"それから、保育園の行事にも参加されているというような形で、さらなる交流を深めておいでになると聞いているところです。","id":"exchange-129"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは答えまだ無理かな、要望にしておきます。私が最近感じるのは、障害者関係の施策の中にＮＰＯが増えてきているんじゃないかなという感じもするので、その辺お答えほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"ＮＰＯ法人との連携ですが、ＮＰＯ法人を取るためには、さまざまな地域活動をしながら取っている団体があります。区との連携をきちっと進めるということで法人格を取るという動きの中で、ＮＰＯ法人を取っていくという動きです。","id":"exchange-130"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区が委託をしたことによって、委託費がすぐ出てくれるのかどうか。支払い契約がどういう委託契約になっているかわからないんですけど、すぐにお金が出てくれているのかどうか、そこら辺の考え方を説明を求めました。","respondent":"高橋障害者福祉課長","answer":"私どもの運営につきましては、例えばぴゅあ・さぽーとが障害者就労支援センターを運営するための委託をしております。この内容につきましては、法人の運営にも影響しますので、４月当初に請求書をもらいまして、即入金するという手続きを進めしています。","id":"exchange-131"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これからも区と一体となって、またＮＰＯとしても足りない部分を区のほうからもなるべくフォローしてあげて、育てていってほしいなと。それで、いい協働を行っていただきたいということをお願いして質問を終わりにします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-132"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/842680?Template=document&Id=1312#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":108851,"voices":330}}]);
